import (
  "os"
  "bufio"
  "strconv"
  "fmt"
  "math"
)

var scanner *bufio.Scanner

func getI() int64 {
  scanner.Scan()
  x, _ := strconv.ParseInt(scanner.Text(), 10, 64)
  return x
}
func getF() float64 {
  scanner.Scan()
  x, _ := strconv.ParseFloat(scanner.Text(), 64)
  return x
}
func getS() string {
  scanner.Scan()
  return scanner.Text()
}

func main() {
  scanner = bufio.NewScanner(os.Stdin)
  scanner.Split(bufio.ScanWords)
  writer := bufio.NewWriter(os.Stdout)
  defer writer.Flush()

  r, x1, y1, x2, y2 := getI(), getI(), getI(), getI(), getI()
  d := math.Sqrt(float64((x2-x1)*(x2-x1) + (y2-y1)*(y2-y1)))
  result := int(math.Ceil(d / float64(2*r)))
  writer.WriteString(fmt.Sprintf("%d\n", result))
}

