func main() {
	defer w.Flush()
	var n int64
	for I(&n, "\n") == nil {
		solve(n)
	}
}

func solve(n int64) {
	var s []byte
	I(&s, "\n")
	a, b := make([]int, len(s)/2), make([]int, len(s)/2)
	for i, v := range s[:len(s)/2] {
		a[i] = int(v)
	}
	for i, v := range s[len(s)/2:] {
		b[i] = int(v)
	}
	sort.Ints(a)
	sort.Ints(b)
	aa := false
	bb := false
	for i := 0; i < len(a); i++ {
		if a[i] > b[i] {
			aa = true
		} else if a[i] < b[i] {
			bb = true
		} else {
			aa = true
			bb = true
		}
	}
	if aa && bb {
		O("NO", "\n")
	} else {
		O("YES", "\n")
	}
}

