    sort.Ints(left)
    right := make([]int,n)
    for i := n; i < (2*n); i++ {
        right[i-n] = int(s[i])
    }
    sort.Ints(right)
    ans := true
    if left[0] == right[0] {
        ans = false
    } else {
        for i := 1; i < n; i++ {
            if ((left[i] >= right[i]) && (left[i-1] <= right[i-1])) || ((left[i] <= right[i]) && (left[i-1] >= right[i-1])) {
                ans = false
                break
            }
        }
    }
    if ans { fmt.Println("YES") } else { fmt.Println("NO") }
}

