import (
	"bufio"
	"fmt"
	"os"
	"sort"
)

type sortRunes []rune

func (s sortRunes) Less(i, j int) bool {
	return s[i] < s[j]
}

func (s sortRunes) Swap(i, j int) {
	s[i], s[j] = s[j], s[i]
}

func (s sortRunes) Len() int {
	return len(s)
}

func need_automaton(input1 string, input2 string) bool {
	input1Bytes := []rune(input1)
	input2Bytes := []rune(input2)

	if len(input2Bytes) > len(input1Bytes) {
		return false
	}

	i, j := 0, 0

	for {
		if i >= len(input2Bytes) || j >= len(input1Bytes) {
			break
		}

		if input2Bytes[i] == input1Bytes[j] {
			i++
			j++
		} else {
			j++
		}
	}

	if i == len(input2Bytes) {
		return true
	} else {
		return false
	}
}

func need_array(input1 string, input2 string) bool {
	if len(input1) != len(input2) {
		return false
	}

	input1Bytes := []rune(input1)
	input2Bytes := []rune(input2)

	sort.Sort(sortRunes(input1Bytes))
	sort.Sort(sortRunes(input2Bytes))

	for i := 0; i < len(input1Bytes); i++ {
		if input1Bytes[i] != input2Bytes[i] {
			return false
		}
	}

	return true
}

func need_both(input1 string, input2 string) bool {
	input1Bytes := []rune(input1)
	input2Bytes := []rune(input2)

	sort.Sort(sortRunes(input1Bytes))
	sort.Sort(sortRunes(input2Bytes))

	if len(input2Bytes) > len(input1Bytes) {
		return false
	}

	i, j := 0, 0

	for {
		if i >= len(input2Bytes) || j >= len(input1Bytes) {
			break
		}

		if input2Bytes[i] == input1Bytes[j] {
			i++
			j++
		} else if input2Bytes[i] > input1Bytes[j] {
			j++
		} else {
			break
		}
	}

	if i == len(input2Bytes) {
		return true
	} else {
		return false
	}
}

func main() {
	var word1, word2 string
	scanner := bufio.NewScanner(os.Stdin)

	if scanner.Scan() {
		word1 = scanner.Text()
	}

	if scanner.Scan() {
		word2 = scanner.Text()
	}

	if need_array(word1, word2) {
		fmt.Println("array")
	} else if need_automaton(word1, word2) {
		fmt.Println("automaton")
	} else if need_both(word1, word2) {
		fmt.Println("both")
	} else {
		fmt.Println("need tree")
