import (
	"bufio"
	"fmt"
	"os"
)

var reader= bufio.NewReader(os.Stdin)
var writer= bufio.NewWriter(os.Stdout)
var cnt[33]int
var dp[105][105]int
var s string
var t string

func max(a int, b int) int {
	if a < b {
		return b
	}
	return a
}

func main()  {
	defer writer.Flush()
	fmt.Fscanf(reader, "%s\n", &s)
	for i := 0; i < len(s); i++ {
		cnt[int(s[i] - 'a')]++
	}
	fmt.Fscanf(reader, "%s\n", &t)
	for i := 0; i < len(t); i++ {
		cnt[int(t[i] - 'a')]--
	}

	var neg = 0
	var pos = 0

	for i := 0; i < 26; i++ {
		if cnt[i] > 0 {
			pos++
		}
		if cnt[i] < 0 {
			neg++
		}
	}

	if neg > 0 {
		fmt.Fprintf(writer, "need tree")
		return
	}

	if pos == 0 {
		fmt.Fprintf(writer, "array")
		return
	}

	var n = len(s)
	var m = len(t)
	for i := 1; i <= n; i++ {
		for j := 1; j <= m; j++ {
			if s[i - 1] == t[j - 1] {
				dp[i][j] = dp[i - 1][j - 1] + 1
			} else {
				dp[i][j] = max(dp[i - 1][j], dp[i][j - 1])
			}
		}
	}

	if dp[n][m] == m {
		fmt.Fprintf(writer, "automaton")
	} else {
		fmt.Fprintf(writer, "both")
	}
}

