import (
	"fmt"
	"math"
)

func no()  { fmt.Println("NO") }
func yes() { fmt.Println("YES") }

func main() {
	var n, R, r int
	fmt.Scan(&n, &R, &r)
	if n == 1 {
		if R < r {
			no()
		} else {
			yes()
		}
		return
	}
	if 2*r > R {
		no()
		return
	}
	if 2*r == R {
		if n == 2 {
			yes()
		} else {
			no()
		}
		return
	}
	a := math.Asin((float64(r)) / float64((R - r)))
	if a*float64(n)*2 > 0.000000001+math.Asin(1)*4 {
		no()
	} else {
		yes()
	}
}

