import (
	"bufio"
	"fmt"
	"os"
	"strconv"
)

func main() {
	scanner := bufio.NewScanner(os.Stdin)
	scanner.Buffer(make([]byte, 2048*2048), 2048*2048)
	scanner.Split(bufio.ScanWords)

	scanner.Scan()
	n, _ := strconv.Atoi(scanner.Text())
	scanner.Scan()
	m, _ := strconv.Atoi(scanner.Text())

	// answer
	ans := make([]int, n)

	s := make([]int, m)
	d := make([]int, m)
	sd := make([]int, m)
	c := make([]int, m)
	for i := 0; i < m; i++ {
		scanner.Scan()
		s[i], _ = strconv.Atoi(scanner.Text())
		scanner.Scan()
		d[i], _ = strconv.Atoi(scanner.Text())
		sd[i] = d[i]
		scanner.Scan()
		c[i], _ = strconv.Atoi(scanner.Text())
	}

	for i := 0; i < n; i++ {
		ex := nextExam(s, d, c, i+1)
		if ex == -1 {
			ans[i] = 0
			continue
		}
		if d[ex] == i+1 {
			if c[ex] != 0 {
				fmt.Println(-1)
				return
			}
			ans[i] = m + 1
			continue
		}
		ans[i] = ex + 1
		c[ex]--
	}

	for i := 0; i < n; i++ {
		fmt.Printf("%d ", ans[i])
	}
	fmt.Println()
}

func nextExam(s, d, c []int, today int) int {
	minVal := -1
	m := len(d)
	for i := 0; i < m; i++ {
		if d[i] < today {
			continue
		}
		if d[i] == today {
			return i
		}
		if c[i] == 0 {
			continue
		}
		if s[i] > today {
			continue
		}
		if minVal == -1 || d[i] < d[minVal] {
			minVal = i
		}
	}
	return minVal
}

