		sort.Slice(todo[i], func(j, k int) bool { return todo[i][j].d < todo[i][k].d })
		for _, p := range todo[i] {
			if pr[p.i] > 0 {
				pr[p.i]--
				ans = append(ans, p.i+1)
				continue o
			}
		}
		ans = append(ans, 0)
	}
	for _, left := range pr {
		if left > 0 {
			Fprint(out, -1)
			return
		}
	}
	Fprint(out, ans...)
}

