func main() {
	p, y = ReadInt2()

	for i := y; i > p; i-- {
		memo := TrialDivision(i)
		ok := true
		for k := range memo {
			if k <= p {
				ok = false
				break
			}
		}

		if ok {
			fmt.Println(i)
			return
		}
	}
	fmt.Println(-1)
}

// TrialDivision returns the result of prime factorization of integer N.
func TrialDivision(n int) map[int]int {
	var i, exp int
	p := map[int]int{}

	if n <= 1 {
		panic(errors.New("[argument error]: TrialDivision only accepts a NATURAL number"))
	}

	for i = 2; i*i <= n; i++ {
		exp = 0
		for n%i == 0 {
			exp++
			n /= i
		}

		if exp == 0 {
			continue
		}
		p[i] = exp
	}
	if n > 1 {
		p[n] = 1
	}

	return p
}

