type Prob struct {
    in *bufio.Reader
}

func (prob *Prob) NextLine() string {
    line, _, _ := prob.in.ReadLine()
    return string(line[:])
}

func (prob *Prob) NextByte() byte {
    bt, _ := prob.in.ReadByte()
    return bt
}

func (prob *Prob) Next() string {
    var buff bytes.Buffer
    bt := prob.NextByte()
    for bt == '\n' || bt == ' ' {
        bt = prob.NextByte()
    }
    for bt != '\n' && bt != ' ' {
        buff.WriteByte(bt)
        bt = prob.NextByte()
    }
    return buff.String()
}

func (prob *Prob) NextInt() int {
    var x int
    bt := prob.NextByte()
    for bt > '9' || bt < '0' {
        if bt == '-' {
            return -prob.NextInt()
        }
        bt = prob.NextByte()
    }
    for bt >= '0' && bt <= '9' {
        x = x * 10 + int(bt - '0')
        bt = prob.NextByte()
    }
    return x
}

func gcd(a int64, b int64) int64 {
    if a == 0 {
        return b
    }
    return gcd(b % a, a)
}

func (prob Prob) Solve() {
    n := int64(prob.NextInt())
    k := int64(prob.NextInt())
    a := int64(prob.NextInt())
    b := int64(prob.NextInt())

    ma := int64(-1)
    mi := int64(-1)
    s1 := a
    s2 := (k - a) % k
    for i := int64(1); i <= n; i++ {
        t1 := i * k + b
        t2 := i * k + (k - b) % k
        r1 := n * k / gcd(n * k, t1 - s1)
        if ma == -1 || ma < r1 {
            ma = r1
        }
        if mi == -1 || mi > r1 {
            mi = r1
        }
        r1 = n * k / gcd(n * k, t1 - s2)
        if ma == -1 || ma < r1 {
            ma = r1
        }
        if mi == -1 || mi > r1 {
            mi = r1
        }
        r1 = n * k / gcd(n * k, t2 - s1)
        if ma == -1 || ma < r1 {
            ma = r1
        }
        if mi == -1 || mi > r1 {
            mi = r1
        }
        r1 = n * k / gcd(n * k, t2 - s2)
        if ma == -1 || ma < r1 {
            ma = r1
        }
        if mi == -1 || mi > r1 {
            mi = r1
        }
    }

    fmt.Printf("%d %d\n", mi, ma)
}


func main() {
    Prob{in: bufio.NewReader(os.Stdin)}.Solve()
}

