func gcd(a, b int64) int64 {
	for b != 0 {
		a, b = b, a%b
	}
	return a
}

func posMod(a, mod int64) int64 {
	a = a % mod
	if a <= 0 {
		a += mod
	}
	return a
}

func main() {
	defer writer.Flush()

	var n, k, a, b, g, nk int64
	var x1, x2, y1, y2 int64
	var l1, l2, l3, l4 int64
	var mn, mx int64
	scan(&n, &k)
	scan(&a, &b)

	nk = n * k

	mn, mx = nk, 1

	for i := int64(0); i < n; i++ {
		x1, x2 = posMod(1-a, nk), posMod(1+a, nk)
		y1, y2 = posMod(i*k+1-b, nk), posMod(i*k+1+b, nk)
		// pln(i, "---------------------------------------------------")
		// pln(x1, x2, y1, y2)

		l1, l2, l3, l4 = posMod(y1-x1, nk), posMod(y2-x1, nk), posMod(y1-x2, nk), posMod(y2-x2, nk)

		g = gcd(l1, nk)
		// pln(i, l1, g)
		mn = min(mn, nk/g)
		mx = max(mx, nk/g)

		g = gcd(l2, nk)
		// pln(i, l2, g)
		mn = min(mn, nk/g)
		mx = max(mx, nk/g)

		g = gcd(l3, nk)
		// pln(i, l3, g)
		mn = min(mn, nk/g)
		mx = max(mx, nk/g)

		g = gcd(l4, nk)
		// pln(i, l4, g)
		mn = min(mn, nk/g)
		mx = max(mx, nk/g)
	}
	// pln("RESULT = ", mn, mx)
	pln(mn, mx)
	return
}

