			break
		}
	}
	for ; index < n; index++ {
		if array[index] != array[index-1] {
			break
		}
	}
	for ; index < n; index++ {
		if array[index] >= array[index-1] {
			break
		}
	}
	if index < n {
		return "NO\n"
	}
	return "YES\n"
}

