/*
	To solve this problem we need to tinker a bit with the mechanism
	of mod & power. If we just use naive approach we will have overflow
	since the number of n is very large.

	So basically in this operation we want to get the remainder of m / (2^n)
	without computing the result of 2^n first.

	So my approach is we divide m with 2 one by one up until n. Thus
	following conditions will happen:
	- if m could be divided completely by all 2s, then the remainder is 0
	  since this means m could be completely divided by 2^n
	- if could not be divided completey by all 2, there are 2 conditions:
	  * the remaining value of m is smaller than remaining 2s, if this happens
		returns m since this means m cannot be divided more by 2. It's just like
		5 / 20, the remainder would be 5, right?
	  * the remaining value of m is bigger than remaining 2s, then we need to get
		the remainder from it, after that multiply with all 2s we already used so
		far then we could get the true remainder for m / (2^n). The example of this
		condition is 42 / (2^4), if we simplify this we will get 21 / (2^3) which
		has remainder 5, notice that the true reminder of 42 / (2^4) is 10 which is
		remainder of (21 / (2^3)) * 2. This yield true for 84 / (2^5) which has true
		reminder 20. So you could already see the connection here.
*/

import (
	"bufio"
	"fmt"
	"os"
)

func main() {
	var n, m int64
	stdin := bufio.NewReader(os.Stdin)
	fmt.Fscanf(stdin, "%d\n%d", &n, &m)
	fmt.Println(solve(m, n))
}

func solve(m int64, n int64) int64 {
	tmp := m
	steps := 0
	for tmp%2 == 0 && n > 0 {
		tmp /= 2
		steps++
		n--
	}
	// m is completely divisible by 2^n
	if n == 0 {
		return 0
	}
	// check if tmp is smaller than remaining 2s progressively
	var mul int64 = 1
	for n > 0 {
		mul *= 2
		if mul > tmp {
			// tmp is smaller
			return m
		}
		n--
	}
	// tmp is bigger
	remainder := tmp % mul
	for i := 0; i < steps; i++ {
		remainder *= 2
	}
	return remainder
}

