				if (L[i] + L[j] - L[k]) >= diff {
					return true
				}
			}
		}
	}
	return false
}

func main() {
	var L = make([]int, 4)
	_, _ = fmt.Scanf("%d %d %d %d", &L[0], &L[1], &L[2], &L[3])
	sort.Ints(L)
	if triangle(L, 1) {
		fmt.Println("TRIANGLE")
	} else if triangle(L, 0) {
		fmt.Println("SEGMENT")
	} else {
		fmt.Println("IMPOSSIBLE")
	}
}

