// Divisors returns the divisors of an argument integer as map[int]int.
func Divisors(n int64) map[int64]int64 {
	var l int64
	res := make(map[int64]int64)

	for l = 1; l*l <= n; l++ {
		if n%l == 0 {
			res[l] = 1
			res[n/l] = 1
		}
	}

	return res
}

