func canDeal(a, b, c int, checked map[int]bool) bool {
	if c < a && c < b {
		return false
	}
	if c%a == 0 || c%b == 0 {
		return true
	}
	defer func() { checked[c] = true }()
	if !checked[c] {
		return canDeal(a, b, c-a, checked) || canDeal(a, b, c-b, checked)
	}
	return false
}

