// CalcAdvancers returns the number of advancers to the next round.
func CalcAdvancers(n, k int, ranks []int) int {
	pos := k - 1
	pts := ranks[pos]
	next := func(in int) int { return in + 1 }
	prev := func(in int) int { return in - 1 }
	if pts == 0 {
		next, prev = prev, next
	}

	for pos >= 0 && pos < n {
		if ranks[pos] < pts {
			return pos
		}
		if pts == 0 && ranks[pos] > pts {
			return pos + 1
		}
		pos = next(pos)
	}

	if pos < 0 {
		return 0
	}

	return pos
}

