	scanner.Scan()
	k, _ := strconv.Atoi(scanner.Text())

	ranks := make([]int, 0)
	for scanner.Scan() {
		next, _ := strconv.Atoi(scanner.Text())
		ranks = append(ranks, next)
	}

	fmt.Printf("%d\n", CalcAdvancers(n, k, ranks))
}

