func binSearch(a []int, key int) int {
	l := -1
	r := len(a)
	for l < r-1 {
		m := (l + r) / 2
		if a[m] < key {
			l = m
		} else {
			r = m
		}
	}

	if a[r] != key {
		return -1
	}

	return r
}

