var DIV int64 = 1000000007

func culc(a, n int64) int64 {
	if n == 0 {
		return 1
	}

	if n == 1 {
		return a
	}

	if n%2 == 1 {
		return culc(a, n-1) * a % DIV
	}

	sum := culc(a, n/2)
	return sum * sum % DIV
}

func main() {

