func pow(a, b int64) int64 {
	as := make([]int64, 2);
	bs := make([]int64, 2);
	as[1] = a;
	bs[1] = 1;
	for b > bs[len(bs)-1] {
		as = append(as, (as[len(as)-1] * as[len(as)-1]) % 1000000007)
		bs = append(bs, 2*bs[len(bs)-1])
	}

	var ans int64 = 1
	for i := len(bs)-1; i > 0; i-- {
		if b >= bs[i] {
			ans = (ans * as[i]) % 1000000007
			b -= bs[i]
		}
	}
	return ans
}

