	m := sc.Map2D(r, c)

	anyInRow, anyInCol := make([]bool, r), make([]bool, c)
	for y := range m {
		for x := range m[0] {
			if m[y][x] == byte('S') {
				anyInRow[y] = true
				anyInCol[x] = true
			}
		}
	}

	ans := 0
	for y := range m {
