const MOD = 998244353
const MAX_N = 2021*2 + 10

var F [MAX_N]int
var I [MAX_N]int

func modAdd(a int, b int) int {
	a += b
	if a >= MOD {
		a -= MOD
	}
	return a
}

func modMul(a int, b int) int {
	res := int64(a) * int64(b)
	res %= MOD
	return int(res)
}

func pow(a, b int) int {
	r := 1
	for b > 0 {
		if b&1 == 1 {
			r = modMul(r, a)
		}
		a = modMul(a, a)
		b >>= 1
	}
	return r
}

func init() {
	F[0] = 1
	for i := 1; i < MAX_N; i++ {
		F[i] = modMul(i, F[i-1])
	}
	I[MAX_N-1] = pow(F[MAX_N-1], MOD-2)
	for i := MAX_N - 2; i >= 0; i-- {
		I[i] = modMul(i+1, I[i+1])
	}
}

func nCr(n int, r int) int {
	res := F[n]
	res = modMul(res, I[r])
	res = modMul(res, I[n-r])
	return res
}

func solve(n int, m int) int {
	// must be dp, but how?
	if n < m {
		n, m = m, n
	}
	var ans int
	for r := 1; r < n; r++ {
		var f int
		for c := m - 1; c >= 1; c-- {
			f = modAdd(f, modMul(nCr(n-r+m-c-1, n-r), nCr(c+n-r-1, n-r-1)))
			ans = modAdd(ans, modMul(nCr(r+c-1, r), modMul(nCr(m-c+r-1, r-1), f)))
		}
	}

	n, m = m, n

	for r := 1; r < n; r++ {
		var f int
		for c := m - 1; c >= 1; c-- {
			ans = modAdd(ans, modMul(nCr(r+c-1, r), modMul(nCr(m-c+r-1, r-1), f)))
			f = modAdd(f, modMul(nCr(n-r+m-c-1, n-r), nCr(c+n-r-1, n-r-1)))
		}
	}

	return modMul(ans, 2)
}

