func f(n int64) int64 {
	return (n - 1) * n / 2
}

func min_pairs(n, m int64) int64 {
	q := n / m
	mod := n % m
	return f(q)*(m-mod) + f(q+1)*mod
}

func max_pairs(n, m int64) int64 {
	return f(n - (m - 1))
}

