func takeInput(scanner *bufio.Scanner) (int, int, int) {
	var inputParameters []int

	scanner.Scan()
	input := strings.Split(scanner.Text(), " ")
	for _, param := range input {
		convertedParam, _ := strconv.Atoi(param)
		inputParameters = append(inputParameters, convertedParam)
	}
	return inputParameters[0], inputParameters[1], inputParameters[2]
}

func calcTotalData(dataPerSec int, videoLength int) int {
	return videoLength * dataPerSec
}

func calcTotalDownloadTime(totalData int, downloadPerSec int) float64 {
	return math.Ceil(float64(totalData) / float64(downloadPerSec))
}

