// n以下の最大の素数を返す
func sub(n int64) int64 {
	for i := n; i >= 2; i-- {
		if IsPrime(i) {
			return i
		}
	}
	return 1
}

// IsPrime judges whether an argument integer is a prime number or not.
func IsPrime(n int64) bool {
	var i int64

	if n == 1 {
		return false
	}

	for i = 2; i*i <= n; i++ {
		if n%i == 0 {
			return false
		}
	}

	return true
}

