func find(wanted, word string) bool {
	var first string
	for len(wanted) > 0 && len(word) > 0 {
		first, wanted = string(wanted[0]), wanted[1:]
		index := strings.Index(word, first)
		if index == -1 {
			return false
		}
		word = word[index+1:]
	}
	return len(wanted) == 0
}

