func sort(rr, gg, bb int64) (int64, int64, int64) {
	if rr >= gg {
		if gg >= bb {
			return rr, gg, bb
		} else if rr >= bb {
			return rr, bb, gg
		}
		return bb, rr, gg
	}
	if rr >= bb {
		return gg, rr, bb
	} else if gg >= bb {
		return gg, bb, rr
	}
	return bb, gg, rr
}

func f(r, g, b int64) int64 {
	x := r - b
	y := g - b
	if y > 0 {
		if x >= 2 * y {
			return y + f(r - 2 * y, b, b)
		}
		k := (2 * x - y) / 3
		if (2 * x - y) % 3 != 0 {
			k++
		}
		return x - k + f(b + y - 2 * x + 3 * k, b, b)
	}
	if r >= 4 * b {
		return 2 * b
	}
	t := (4 * b - r) / 3
	if (4 * b - r) % 3 != 0 {
		t++
	}
	return 2 * b - t
}

func main() {
	var rr, gg, bb int64
	fmt.Scanf("%d %d %d", &rr, &gg, &bb)
	r, g, b := sort(rr, gg, bb)
	fmt.Println(f(r, g, b))
}

