	Assert(err == nil)
	return f
}

func Assert(b bool)  {
	if !b {
		panic("Assertion error")
	}
}

func GetLine(scanner *bufio.Scanner) string {
	Assert(scanner.Scan() && scanner.Err() == nil)
	return scanner.Text()
}

func ReadIntLine(scanner *bufio.Scanner) []int {
	lst := make([]int, 0)
	for _, s := range strings.Fields(GetLine(scanner)) {
		i, err := strconv.Atoi(s)
		Assert(err == nil)
		lst = append(lst, i)
	}
	return lst
}

func SliceIndex(limit int, predicate func(i int) bool) int {
	for i := 0; i < limit; i++ {
		if predicate(i) {
			return i
		}
	}
	return -1
}

func Ternary(c bool, a, b interface{}) interface{} {
	if c { return a }
	return b
}

func main() {
	f := os.Stdin
	//f := strings.NewReader("Now is the winter of our discontent,\n1 3 4\n")
	//f = OpenFile("/home/ilya/opt/programming/tasks/724A.txt")

	sc := bufio.NewScanner(f)

	days := []string{"monday", "tuesday", "wednesday", "thursday", "friday", "saturday", "sunday"}
	ReadDay := func() int {
		s := GetLine(sc)
		idx := SliceIndex(len(days), func(i int) bool { return days[i] == s })
		Assert(idx != -1)
		return idx
	}

	first  := ReadDay()
	second := ReadDay()
	diff := second - first
	if diff < 0 {
		diff += 7
	}

	possibles := []int{0, 2, 3}
	res := SliceIndex(len(possibles), func(i int) bool { return possibles[i] == diff })

	fmt.Println(Ternary(res == -1, "NO", "YES"))
}

