}

func Solve(board [8]string) string {
	whitePawn := 7
	blackPawn := 0
	for j := 0; j < 8; j++ {
		for i := 0; i < 8; i++ {
			if string(board[i][j]) == "B" {
				break
			} else if string(board[i][j]) == "W" {
				whitePawn = min(i, whitePawn)
				break
			}
		}
		for i := 7; i >= 0; i-- {
			if string(board[i][j]) == "W" {
				break
			} else if string(board[i][j]) == "B" {
				blackPawn = max(i, blackPawn)
				break
			}
		}
	}
	if whitePawn <= 7-blackPawn {
		return "A"
	}
	return "B"
}

