import (
	"fmt"
	"math"
)

type Point struct {
	X, Y float64
}

type Square struct {
	Points [4]Point
}

func rotateAxis(p Point, angle float64) (res Point) {
	res = Point{}
	angle = (angle * math.Pi) / 180
	res.X = p.X*math.Cos(angle) + p.Y*math.Sin(angle)
	res.Y = -1*p.X*math.Sin(angle) + p.Y*math.Cos(angle)
	return
}

func isInSquare(sq Square, p Point) (b bool) {
	var minHoz float64 = 101
	for _, v := range sq.Points {
		minHoz = math.Min(minHoz, v.Y)
	}

	var maxHoz float64 = -101
	for _, v := range sq.Points {
		maxHoz = math.Max(maxHoz, v.Y)
	}

	var minVer float64 = 101
	for _, v := range sq.Points {
		minVer = math.Min(minVer, v.X)
	}

	var maxVer float64 = -101
	for _, v := range sq.Points {
		maxVer = math.Max(maxVer, v.X)
	}

	return (p.X >= minVer && p.X <= maxVer) && (p.Y >= minHoz && p.Y <= maxHoz)
}

func solve(sq, sq45 Square) bool {
	center := Point{0, 0}
	for _, v := range sq45.Points {
		center.X += v.X
		center.Y += v.Y
		if isInSquare(sq, v) {
			return true
		}
	}

	center.X /= 4
	center.Y /= 4
	if isInSquare(sq, center) {
		return true
	}

	rotatedSquare := Square{}
	for i := range rotatedSquare.Points {
		rotatedSquare.Points[i] = rotateAxis(sq45.Points[i], 45)
	}

	center = Point{0, 0}
	for _, v := range sq.Points {
		center.X += v.X
		center.Y += v.Y
		rotatedPoint := rotateAxis(v, 45)
		if isInSquare(rotatedSquare, rotatedPoint) {
			return true
		}
	}

	center.X /= 4
	center.Y /= 4
	rotatedCenter := rotateAxis(center, 45)
	if isInSquare(rotatedSquare, rotatedCenter) {
		return true
	}

	return false
}

func consoleInput() {
	var x, y float64
	sq := Square{}
	for i := 0; i < 4; i++ {
		fmt.Scan(&x, &y)
		sq.Points[i] = Point{
			X: x,
			Y: y,
		}
	}

	sq45 := Square{}
	for i := 0; i < 4; i++ {
		fmt.Scan(&x, &y)
		sq45.Points[i] = Point{
			X: x,
			Y: y,
		}
	}

	if solve(sq, sq45) {
		fmt.Println("YES")
	} else {
		fmt.Println("NO")
	}
}

