func needs(sum, xor, carry, digit int64) int64 {
	if digit < 1 {
		return 1 - carry
	}

	if (xor & digit) != 0 {
		if (sum & digit) != 0 {
			return (1 - carry) * 2 * needs(sum, xor, 0, digit>>1)
		}
		return carry * 2 * needs(sum, xor, 1, digit>>1)
	}

	if (sum & digit) != 0 {
		return needs(sum, xor, 1, digit>>1)
	}
	return needs(sum, xor, 0, digit>>1)
}

