func main() {
	input := bufio.NewScanner(os.Stdin)
	hasInput := input.Scan()
	if hasInput == false {
		panic("Number of problems missing")
	}

	tmp := strings.Split(input.Text(), " ")
	t, err := strconv.Atoi(tmp[1])
	input.Scan()
	q := strings.Split(input.Text(), "")
	if err != nil {
		panic("Something went wrong")
	}

	q = tick(q, t)

	fmt.Println(strings.Join(q, ""))
}

func tick(q []string, t int) []string {
	s := make([]bool, len(q))
	var tmp string

	for i := 0; i <= t; i++ {
		for j, _ := range q {
			if s[j] == true && len(q) > j+1 {
				tmp = q[j]
				q[j] = q[j+1]
				q[j+1] = tmp
				s[j] = false
			}
		}

		for j, v := range q {
			if v == "B" && len(q) > j+1 && q[j+1] == "G" {
				s[j] = true
			}
		}

	}

	return q
}

