var memo map[int]bool

func main() {
	defer Flush()

	memo = make(map[int]bool)
	memo[0] = true

	_, x := readInts(0)
	for i := range x {
		if solve(x[i]) {
			println("YES")
		} else {
			println("NO")
		}
	}
}

func solve(x int) bool {
	if x < 0 {
		return false
	}
	t, ok := memo[x]
	if ok {
		if t {
			return true
		} else {
			return false
		}
	}
	if solve(x-3) || solve(x-7) {
		memo[x] = true
		return true
	}
	memo[x] = false
	return false

}

