func is_palindrome(t string) bool {
	var c []string = strings.Split(t, "")

	for i, j := 0, len(c)-1; i < j; i, j = i+1, j-1 {
		c[i], c[j] = c[j], c[i]
	}

	u := strings.Join(c, "")

	if t == u {
		return true
	}

	return false
}

func get_trailing_scores_count(t string) int {

	count := 0

	for i := len(t) - 1; i > 0; i = i - 1 {
		if t[i] == '0' {
			count += 1
		} else {
			break
		}
	}

	return count
}

func add_leading_zeros(t string, c int) string {
	u := t

	for i := 0; i < c; i = i + 1 {
		u = "0" + u
	}

	return u
}

func solve(t string) bool {

	if is_palindrome(t) {
		return true
	}

	trailing_zeros := get_trailing_scores_count(t)

	u := add_leading_zeros(t, trailing_zeros)

	if is_palindrome(u) {
		return true
	}

	return false
}

func main() {
	var t string

	fmt.Scanf("%s", &t)

	if solve(t) {
		fmt.Println("YES")
	} else {
		fmt.Println("NO")
	}
}

