func main() {
	ms := NewMuchScanner()
	s := ms.ReadString()
	n := len(s)

	leadingZeros := 0
	trailingZeros := 0

	for i := 0; i < n && s[i] == '0'; i++ {
		leadingZeros++
	}
	for i := n - 1; i >= 0 && s[i] == '0'; i-- {
		trailingZeros++
	}

	zerosToAdd := diff(leadingZeros, trailingZeros)
	z := make([]byte, zerosToAdd)
	for i := range z {
		z[i] = '0'
	}
	zeros := string(z)

	if leadingZeros > trailingZeros {
		s = concat(s, zeros)
	} else {
		s = concat(zeros, s)
	}
	n = len(s)

	isOk := true
	for i := 0; i < n/2; i++ {
		j := n - 1 - i
		if s[i] != s[j] {
			isOk = false
		}
	}

	if isOk {
		fmt.Println("YES")
	} else {
		fmt.Println("NO")
	}
}

func diff(a, b int) int {
	if a > b {
		return a - b
	}
	return b - a
}

func concat(a, b string) string {
	var buf bytes.Buffer
	buf.WriteString(a)
	buf.WriteString(b)
	return buf.String()
}

// MuchScanner is a wrapper for bufio.Scanner
type MuchScanner struct {
	scanner *bufio.Scanner
}

// NewMuchScanner creates new insances of MuchScanner
func NewMuchScanner() *MuchScanner {
	sc := bufio.NewScanner(os.Stdin)
	sc.Split(bufio.ScanWords)
	return &MuchScanner{
		scanner: sc,
	}
}

// TokenSize sets maximal token size
func (ms *MuchScanner) TokenSize(tokenSize int) {
	ms.scanner.Buffer(make([]byte, tokenSize), tokenSize)
}

// ReadString reads next word as a string
func (ms *MuchScanner) ReadString() string {
	ms.scanner.Scan()
	return ms.scanner.Text()
}

// ReadInt reads next int number
func (ms *MuchScanner) ReadInt() int {
	n, _ := strconv.Atoi(ms.ReadString())
	return n
}

// ReadIntArr reads next n int numbers
func (ms *MuchScanner) ReadIntArr(n int) []int {
	arr := make([]int, n)
	for i := range arr {
		arr[i] = ms.ReadInt()
	}
	return arr
}

