func find(n, k int64) int64 {
    sz, prev := int64(0), int64(0)
    for i := int64(0); i < n; i++ {
        prev, sz = sz, 2*sz+1
    }
    if k == prev {
        return n
    }
    if k > prev {
        return find(n-1, k-prev-1)
    }
    return find(n-1, k)
}

