type Trav func(func(data interface{}))

type TermRLE struct {
	data   interface{}
	amount int
}

func toRLE(a Trav) Trav {
	var current = TermRLE{nil, 0}
	return func(f func(interface{})) {
		a(func(data interface{}) {
			if current.amount == 0 {
				current = TermRLE{data, 1}
			} else if data != current.data {
				f(current)
				current = TermRLE{data, 1}
			} else {
				current.amount++
			}
		})
		if current.amount != 0 {
			f(current)
			current = TermRLE{nil, 0}
		}
	}
}

