	var n int
	fmt.Scan(&n)
	var s string
	fmt.Scan(&s)
	toRLE(func(f func(interface{})) {
		for _, i := range s {
			f(i)
		}
	})(func(data interface{}) {
		n--
	})
	fmt.Println(n)
}

