type Set struct {
	items map[interface{}]struct{}
}

func (s *Set) Size() int {
	return len(s.items)
}
func (s *Set) Empty() bool {
	return s.Size() == 0
}

func (s *Set) Add(t ...interface{}) {
	for _, v := range t {
		s.items[v] = struct{}{}
	}
}

func (s *Set) Remove(t ...interface{}) {
	for _, v := range t {
		delete(s.items, v)
	}
}

func (s *Set) Contains(t ...interface{}) bool {
	for _, v := range t {
		if _, ok := s.items[v]; !ok {
			return false
		}
	}
	return true
}

func (s *Set) List() []interface{} {
	ret := make([]interface{}, 0, s.Size())
	for k, _ := range s.items {
		ret = append(ret, k)
	}
	return ret
}

func New(values ...interface{}) *Set {
	ret := &Set{
		items: make(map[interface{}]struct{}),
	}
	for _, v := range values {
		ret.Add(v)
	}
	return ret
}

func main() {
	defer out.Flush()

	set := New()
	for i := 1; i*i <= 1_000_000_000; i++ {
		set.Add(i * i)
	}
	for i := 1; i <= 1000; i++ {
		set.Add(i * i * i)
	}

	arr := make([]int, 0, set.Size())
	for _, v := range set.List() {
		arr = append(arr, v.(int))
	}

	sort.Ints(arr)

	var kase int
	fmt.Fscan(in, &kase)

	for kk := 1; kk <= kase; kk++ {
		var n int
		fmt.Fscan(in, &n)

		low, high := 0, len(arr)-1

		for low <= high {
			mid := (low + high) / 2

			if n >= arr[mid] {
				low = mid + 1
			} else {
				high = mid - 1
			}
		}
		fmt.Fprintf(out, "%d\n", high+1)
	}
}

