func bs(n, k int) int {
    //Find the answer
    var lo, hi, mid, ans int = 0, n, 0, 0
    for lo <= hi {
        mid = (lo+hi)/2
        left := k-2*mid
        if (n-mid)*3 <= left {
            ans = mid
            hi = mid-1
        } else {
            lo = mid+1
        }
    }
    return ans
}

