func solve(a, b, c, d int64) int64 {
	sum := int64(0)
	p := make([]int64, Mx64(b+c+2, d+2))
	for i := a; i <= b; i++ {
		p[i+b] += 1
		p[i+c+1] += -1
	}
	for i := 1; i < len(p); i++ {
		p[i] += p[i-1]
	}

	for i := Mx64(b+c+1, d+1); i >= a; i-- {
		p[i-1] += p[i]
	}

	for i := c; i <= d; i++ {
		sum += int64(p[i+1])
	}
	return sum
}

