func Read(s *bufio.Reader) string {
    line, _ := s.ReadString('\n')
    return line
}

func Write(s *bufio.Writer, a ...interface{}) {
    fmt.Fprintln(s, a...)
    s.Flush()
}

func Max(a, b int) (int, int) {
    if b > a {
        b, a = a, b
    }
    return a, b
}

func main() {
    reader := bufio.NewReader(os.Stdin)

    var a, b int
    line, _ := reader.ReadString(' ')
    fmt.Sscanln(line, &a)
    fmt.Sscanln(Read(reader), &b)

    a, b = Max(a, b)

    writer := bufio.NewWriter(os.Stdout)
    Write(writer, b, (a - b) / 2)    
}

