package main

import (
	"fmt"
)

var (
	colours = []byte("RGBYW")
	numbers = []byte("12345")
)

func bits(x int) (ans int) {
	for x > 0 {
		x &= (x - 1)
		ans++
	}
	return
}

func main() {
	var n int
	fmt.Scan(&n)
	cards := make([]string, n)
	for i := range cards {
		fmt.Scan(&cards[i])
	}
	res := 10
	for c := 0; c < 1 << 5; c++ {
		for nu := 0; nu < 1 << 5; nu++ {
			if bits(c) + bits(nu) > res {
				continue
			}
			know := make(map[byte]bool)
			for i := 0; i < 5; i++ {
				if c & (1 << uint(i)) != 0 {
					know[colours[i]] = true
				}
				if nu & (1 << uint(i)) != 0 {
					know[numbers[i]] = true
				}
			}
			var (
				nothing = make(map[string]bool)
				knowNu = make(map[byte]map[byte]bool)
				knowC = make(map[byte]map[byte]bool)
			)
			good := true
			for _, card := range cards {
				if !know[card[0]] && !know[card[1]] {
					nothing[card] = true
					if len(nothing) > 1 {
						good = false
						break
					}
				} else if !know[card[0]] {
					m := knowNu[card[1]]
					if m == nil {
						m = make(map[byte]bool)
						knowNu[card[1]] = m
					}
					m[card[0]] = true
					if len(m) > 1 {
						good = false
						break
					}
				} else if !know[card[1]] {
					m := knowC[card[0]]
					if m == nil {
						m = make(map[byte]bool)
						knowC[card[0]] = m
					}
					m[card[1]] = true
					if len(m) > 1 {
						good = false
						break
					}
				}
			}
			if good {
				res = bits(c) + bits(nu)
			}
		}
	}
	fmt.Println(res)
}

