func factorial(number int64) int64 {
	var i, result int64 = 0, 1

	for i = 2; i <= number; i++ {
		result *= i
	}

	return result

}

func main() {

	scanner := bufio.NewScanner(os.Stdin)
	scanner.Scan()
	n := scanner.Text()

	var number, factorialVal, denom int64
	number, _ = strconv.ParseInt(n, 10, 64)

	factorialVal = factorial(number)
	denom = (number / 2) * number

	fmt.Println(factorialVal / denom)

}

