func main() {
	var str_a string
	var str_b int64
	input := bufio.NewReader(os.Stdin)
	fmt.Fscan(input, &str_a)
	fmt.Fscan(input, &str_b)
	var cnt [256]int
	for i := 0; i < len(str_a); i++ {
		cnt[str_a[i]-'0']++
	}
	var ans int64
	// fmt.Println(len(str_a))
	for i := 0; i < len(str_a); i++ {
		for j := 9; j >= 0; j-- {
			if cnt[j] == 0 {
				// fmt.Println(j, cnt[j])
				continue
			}
			flag := false
			t := ans
			t = t * 10
			t += int64(j)
			cnt[j]--

			if check(t, cnt, str_b) {
				ans = t
				flag = true
			} else {
				cnt[j]++
			}
			if flag {
				break
			}
		}
	}
	fmt.Println(ans)
}

func check(t int64, cnt [256]int, str_b int64) bool {
	for i := 0; i < 10; i++ {
		for cnt[i] > 0 {
			t = t * 10
			t += int64(i)
			cnt[i]--
		}
	}
	return t <= str_b
}

