package main

import (
	"fmt"
	"sort"
)

func min(x, y int) int {
    if x < y {
		return x
	}
	return y
}

func abs(x int) int {
	if x < 0 {
		return -x
	}
	return x
}

func reverse(v []int) {
	for i := 0; i < len(v) / 2; i++ {
		v[i], v[len(v) - i - 1] = v[len(v) - i - 1], v[i]
	}
}

func numToVec(a int64) []int {
	var vec []int

	for a > 0 {
		vec = append(vec, int(a % 10))
		a /= 10
	}
	return vec
}

func sliceCompare(a, b []int) bool {
	n := len(a)

	for i := 0; i < n; i++ {
		if a[i] < b[i] {
			return true
		} else if a[i] > b[i] {
			return false
		}
	}

	return true
}

func printVec(vec []int) {
	n := len(vec)

	for i := 0; i < n; i++ {
		fmt.Printf("%d", vec[i])
	}
	fmt.Printf("\n")
}

func searchPos(vec []int, l, r, num int) int {
	for i := l; i < r; i++ {
		if vec[i] == num {
			return i
		}
	}
	return -1
}

func main() {
	var a, b int64
	var Va, Vb []int

	fmt.Scanf("%d\n", &a)
	fmt.Scanf("%d\n", &b)

	Va = numToVec(a)
	reverse(Va)

	Vb = numToVec(b)
	reverse(Vb)

	if len(Va) != len(Vb) {
		sort.Ints(Va)
		reverse(Va)
		printVec(Va)
	} else {
		n := len(Va)

		for i := 0; i < n; i++ {
			for dig := 9; dig >= 0; dig-- {
				pos := searchPos(Va, i, n, dig)
				if pos == -1 {
					continue
				}

				Va[i], Va[pos] = Va[pos], Va[i]			
				if i != n - 1 {
					sort.Ints(Va[i+1:])
				}

				if sliceCompare(Va, Vb) == true {
					break
				}
			}
		}

		printVec(Va)
	}

}

