	scanner.Split(bufio.ScanWords)
	writer := bufio.NewWriter(os.Stdout)
	defer writer.Flush()
	a, b, x, y := scanInt(scanner), scanInt(scanner), scanInt(scanner), scanInt(scanner)
	low, high := 1, 2*1000*1000*1000
	for low != high {
		k := int((int64(low)+int64(high))/2)
		div_xy := k/(x*y)
		div_x, div_y := k/x - div_xy, k/y - div_xy
		div_neither := k - div_x - div_y - div_xy
		need_a, need_b := a - div_y, b - div_x
		if need_a < 0 {
			need_a = 0
		}
		if need_b < 0 {
			need_b = 0
		}
		if need_a + need_b <= div_neither {
			high = k
		} else {
			low = k+1
		}
	}
	writer.WriteString(fmt.Sprintf("%d\n", low))
}

