type Team struct {
	name string
	pts, x, y, played int
}

type Sorter []Team

func (s Sorter) Len() int { return len(s) }
func (s Sorter) Swap(i, j int) { s[i], s[j] = s[j], s[i] }
func (s Sorter) Less(i, j int) bool { 
	if s[i].pts > s[j].pts {
		return true
	}
	if s[i].pts < s[j].pts {
		return false
	}
	if s[i].x - s[i].y > s[j].x - s[j].y {
		return true
	}
	if s[i].x - s[i].y < s[j].x - s[j].y {
		return false
	}
	if s[i].x > s[j].x {
		return true
	}
	if s[i].x < s[j].x {
		return false
	}
	return s[i].name < s[j].name
}

