		t1.x += s1
		t1.y += s2
		t2.x += s2
		t2.y += s1

		if s1 > s2 {
			t1.pts += 3
		}else if s1 < s2 {
			t2.pts += 3
		}else {
			t1.pts += 1
			t2.pts += 1
		}
	}

	var berland, other Team
	var teams [4]*Team
	var at int = 0
	for _, value := range s2m {
		teams[at] = value
		at += 1

		if value.played == 2 {
			if value.name == "BERLAND" {
				berland = *value
			}else {
				other = *value
			}
