var bufin *bufio.Reader
var bufout *bufio.Writer

type res struct {
	ind int
	wrd string
}

func inside_parthesis(S string, x *res) bool {
	l, r := false, false
	for i := x.ind; i >= 0; i-- {
		if S[i] == '(' {
			l = true
			break
		} else if S[i] == ')' {
			break
		}
	}
	for i := x.ind; i < len(S); i++ {
		if S[i] == ')' {
			r = true
			break
		} else if S[i] == '(' {
			break
		}
	}
	return l && r
}
func mysplit(S string) []res {
	var cur string
	var start int
	var ret []res

	for i, c := range S {
		if c != '_' && c != '(' && c != ')' {
			if cur == "" {
				start = i
			}
			cur += string(c)
		} else if cur != "" {
			ret = append(ret, res{start, cur})
			cur = ""
		}
	}
	if cur != "" {
		ret = append(ret, res{start, cur})
	}
	return ret
}

func main() {
	bufin = bufio.NewReader(os.Stdin)
	bufout = bufio.NewWriter(os.Stdout)
	defer bufout.Flush()
	var N int
	fmt.Fscanf(bufin, "%d\n", &N)
	var S string
	fmt.Fscanf(bufin, "%s\n", &S)
	words := mysplit(S)
	cnt := 0
	maxlen := 0
	for _, x := range words {
		if inside_parthesis(S, &x) {
			cnt += 1
		} else {
			if maxlen < len(x.wrd) {
				maxlen = len(x.wrd)
			}
		}
	}
	fmt.Fprintf(bufout, "%d %d\n", maxlen, cnt)

}

