	N, M := sc.NextInt64(), sc.NextInt64()

	for {
		if N == 0 || M == 0 {
			break
		}
		if N/M >= 2 {
			N -= N / M / 2 * 2 * M
		} else if 2 <= M/N {
			M -= M / N / 2 * 2 * N
		} else {
			break
		}
	}
