		if n%i == 0 {
			return false
		}
	}
	return n != 1
}

// Divisor 约数枚举
func Divisor(n int) (res []int) {
	for i := 1; i*i <= n; i++ {
		if n%i == 0 {
			res = append(res, i)
			if i != n/i {
				res = append(res, n/i)
			}
		}
	}
	return
}

