func L(n int) int {
	if n==0 { return 0 }
	if n < 10 { return 1 }

	var P=make([]int, n+1)
	var C=make([]int, 10)

	for i:=0; i < 10; i++ { P[i]=1 }
	for i:=10; i <= n; i++ {
		m:=cyfry(i, C)
		min:=-1
		for j:=0; j < m; j++ {
			if C[j] > 0 {
				if min < 0 {
					min=P[i-C[j]]
				} else {
					if P[i-C[j]] < min {
						min=P[i-C[j]]
					}
				}
			}
		}
		P[i]=min+1
	}
	return P[n]
}

func cyfry(n int, c []int) int {
	var i int
	for i=0; n > 0; i++ {
		c[i]=n%10
		n/=10
	}
	return i
}

func min(a, b int) int {
	if a < b { return a }
	return b
}

