var n, a, b, c int
var res []int

func main() {
	scanner := bufio.NewScanner(os.Stdin)
	scanner.Scan()
	raw := scanner.Text()
	segs := strings.Split(raw, " ")
	n, _ = strconv.Atoi(segs[0])
	a, _ = strconv.Atoi(segs[1])
	b, _ = strconv.Atoi(segs[2])
	c, _ = strconv.Atoi(segs[3])

	d := Do()
	fmt.Println(d)
}

func Do() int {
	res = make([]int, n+1, n+1)
	for idx := 1; idx <= n; idx++ {
		res[idx] = Cut(idx)
		// fmt.Println("res", idx, res)
	}
	return res[n]
}

func Cut(idx int) int {
	if idx == 0 {
		return 0
	}
	max := 0
	if idx >= a {
		left := idx - a
		if left == 0 {
			max = 1
			goto bnote
		} else {
			if res[left] == 0 {
				max = 0
				goto bnote
			} else {
				max = 1 + res[left]
			}
		}
	}
bnote:
	bmax := 0
	{
		if idx >= b {
			left := idx - b
			if left == 0 {
				bmax = 1
				goto cnote
			} else {
				if res[left] == 0 {
					bmax = 0
					goto cnote
				} else {
					bmax = 1 + res[left]
				}
			}
		}
	}
cnote:
	cmax := 0
	{
		if idx >= c {
			left := idx - c
			if left == 0 {
				cmax = 1
				goto over
			} else {
				if res[left] == 0 {
					cmax = 0
					goto over
				} else {
					cmax = 1 + res[left]
				}
			}
		}
	}
over:
	{
		zhi := max3(max, bmax, cmax)
		return zhi
	}
}

func max3(a, b, c int) int {
	res := []int{a, b, c}
	// fmt.Println(res)
	sort.Ints(res)
	return res[2]
}

