var writer = NewBufferedWriter(os.Stdout)

func main() {
	defer writer.Flush()
	n, b, p := reader.NextInt64(), reader.NextInt64(), reader.NextInt64()
	y := n*p
	x := int64(0)
	for n > 1 {
		k := getK(n)
		x += k*b + k/2
		n = k/2 + n - k
	}
	writer.Printf("%d %d\n", x, y)
}

func getK(n int64) int64 {
	curr := int64(1)
	for n > 1 {
		n >>= 1
		curr <<= 1
	}
	return curr
}

