func koutsu(t1, t2, t3 string) int {

	if t1 == t2 && t2 == t3 {
		return 0
	}

	strs := []string{t1, t2, t3}
	sort.Strings(strs)
	if strs[0] == strs[1] || strs[1] == strs[2] {
		return 1
	}
	return 2
}

func contains(value string, str []string) bool {
	for _, st := range str {
		if st == value {
			return true
		}
	}
	return false
}

func shuntsu(t1, t2, t3 string) int {
	tiles := []string{t1, t2, t3}
	letters := [3]string{"m", "p", "s"}
	best := 2
	for i := 1; i <= 7; i++ {
		for _, lt := range letters {
			na := strconv.Itoa(i) + lt
			nb := strconv.Itoa(i+1) + lt
			nc := strconv.Itoa(i+2) + lt
			c := 0
			if contains(na, tiles) {
				c++
			}
			if contains(nb, tiles) {
				c++
			}
			if contains(nc, tiles) {
				c++
			}
			best = min(best, 3-c)
		}
	}
	return best
}

func min(a, b int) int {
	if a < b {
		return a
	}
	return b
}

