func bitSum(a int64) int {
	sum := 0
	for {
		if a <= 0 {
			break
		}
		sum += int(a % 10)
		a /= 10
	}
	return sum
}

func main() {
	var n int64
	fmt.Scan(&n)
	if n < 10 {
		fmt.Println(n)
		return
	}

	ten := int64(10)
	m := n
	for {
		m /= 10
		if m < 10 {
			break
		}
		ten *= 10
	}

	a := int64(9)
	for {
		c := int64(a*10 + 9)
		if n-c < 0 {
			for i := int64(1); i < 10; i++ {
				if n > i*ten+a {
					a = (i-1)*ten + a
					break
				}
			}
			break
		}
		a = c
	}

	sum := bitSum(a)
	sum += bitSum(n - a)

	fmt.Println(sum)
}

