type pair struct {
	nn int
	dd int
}

func main() {
	var n, m int
	fmt.Scanf("%d%d", &n, &m)

	if n >= m {
		fmt.Println(n - m)
	} else {
		visited := make([]bool, 2*m+1)

		device := make([]pair, 1)
		device[0] = pair{n, 0}

		ans := 0
		visited[n] = true
		for {
			// pop front element
			tmp := device[0]
			device = device[1:]
			// copy(device[0:len(device)-1], device[1:])

			if tmp.nn == m { // reached destination
				ans = tmp.dd
				break
			}

			// add neighbors to the queue
			if tmp.nn*2 < 2*m+1 && visited[tmp.nn*2] == false {
				device = append(device, pair{tmp.nn * 2, tmp.dd + 1})
				visited[tmp.nn*2] = true
			}
			if tmp.nn-1 >= 0 && visited[tmp.nn-1] == false {
				device = append(device, pair{tmp.nn - 1, tmp.dd + 1})
				visited[tmp.nn-1] = true
			}
		}

		fmt.Println(ans)
	}
}

