		//max = n
	} else {
		c1, n1 := findFirstBigger(n, m)
		//fmt.Println(c1, n1)
		bestTimes = c1 + (n1 - m)
	}
	//fmt.Println(bestTimes)
	//ret = make([]int, max*2+1)
	//for i := 0; i < len(ret); i++ {
	//	ret[i] = -1
	//}
	dfs1(n, m, 0)
	fmt.Println(bestTimes)
}

func dfs1(n int, m int, count int) {
	//fmt.Println(n, m, count)
	if count > bestTimes {
		return
	}
	if n == m {
		if count < bestTimes {
			bestTimes = count
		}
		//fmt.Println("====")
		return
	}
	if n == 0 {
		//fmt.Println("====")
		return
	}
	if n > m {
		if count+n-m < bestTimes {
			bestTimes = count + n - m
		}
		//fmt.Println("====")
		return
	} else {
		if m%2 == 0 {
			dfs1(n, m/2, count+1)
		} else {
			_, n1 := findFirstBigger(n, m)
			for i := n1; i > m; i-- {
				if i%2 == 0 {
					dfs1(n, i, count+i-m)
				}
			}
		}

	}
}

// 次数， temp
func findFirstBigger(n, m int) (int, int) {
	temp := n
	count := 0
	for {
		count++
		temp *= 2
		if temp >= m {
			return count, temp
		}
	}
}

