// There are two buttons, one red and another blue
// Pressing red button multiplies n by 2
// Pressing blue button reduces n by 1
// What is the minimum number of clicks to reduce 'n' to 'm'?

func min_clicks(n, m int) int {
	if n >= m {
		return n - m
	}
	if m % 2 == 1 {
		return min_clicks(n, m + 1) + 1
	}
	return min_clicks(n, m / 2) + 1
}

