	reader := bufio.NewReader(os.Stdin)
	writer := bufio.NewWriter(os.Stdout)
	var n, m int
	fmt.Fscanf(reader, "%d %d", &n, &m)
	fmt.Fprintf(writer, "%d\n", min_clicks(n, m))
	writer.Flush()
}

