type stackval struct {
	current int
	steps   int
}

func solve(n, m int) int {
	var visited [10001]int
	var best = 10000

	s := list.New()
	el := stackval{n, 0}

	s.PushBack(el)

	for s.Len() > 0 {
		el := s.Remove(s.Front()).(stackval)
		visited[el.current] = 1
		if el.current >= m {
			steps := el.steps + (el.current - m)
			if steps < best {
				best = steps
			}
		} else {
			if el.current > 0 {
				if visited[el.current-1] == 0 {
					s.PushBack(stackval{el.current - 1, el.steps + 1})
				}
			}
			if el.current*2 < 10001 && visited[el.current*2] == 0 {
				s.PushBack(stackval{el.current * 2, el.steps + 1})
			}
		}
	}

	return best
}

