func main() {
	// allow for up to 102 entries (line plus newline)
	b := make([]byte, 102)

	// allow for up to 201 entries (dot plus newline)
	out := make([]byte, 0, 201)

	n, errRead := os.Stdin.Read(b)
	if errRead != nil && errRead != io.EOF {
		os.Exit(1)
	}

	b = b[:n]

	for _, c := range b {
		if c >= 'A' && c <= 'Z' {
			c += 32 // 'a' - 'A' = 32
		}

		switch {
		case c < 'A': // newline: append as-is
			out = append(out, c)
		case c == 'a' || c == 'e' || c == 'i' || c == 'o' || c == 'u' || c == 'y':
			continue
		default:
			out = append(out, '.', c)
		}
	}

	os.Stdout.Write(out)
}

