func zcy(n int64) int64 {
	keta := int64(0)

	m := n
	for m > 0 {
		m /= 10
		keta++
	}
	a := pow(10, keta) * n
	for p := keta - 1; p >= 0; p-- {
		a += (n % 10) * pow(10, p)
		n /= 10
	}
	return a

