		return res
	}
	invF := [...]int64{mx: pow(F[mx], m-2)}
	for i := mx; i > 0; i-- {
		invF[i-1] = invF[i] * int64(i) % m
	}
	C := func(n, k int) int64 { return F[n] * invF[k] % m * invF[n-k] % m }
	f := func(a, b int) (s int64) {
		for i := 0; i <= a && i <= b; i++ {
			s = (s + C(a, i)*C(b, i)%m*F[i]) % m
		}
		return
	}

	var a, b, c int
	Scan(&a, &b, &c)
	Print(f(a, b) * f(b, c) % m * f(a, c) % m)
}

