func dfs(x, y, c, dir, step int) {

	if c == n || vis[x][y][c][dir][step] {
		return
	}

	//fmt.Printf("%d %d %d %d %d\n", x, y, c, dir, step)

	mark[x][y] = true
	vis[x][y][c][dir][step] = true
	if step > 0 {
