	} else {
		dfs(x+dx[(dir+1)%8], y+dy[(dir+1)%8], c+1, (dir+1)%8, t[c+1]-1)
		dfs(x+dx[(dir+7)%8], y+dy[(dir+7)%8], c+1, (dir+7)%8, t[c+1]-1)
	}
}

