)

type move struct {
	x  int
	y  int
	dx int
	dy int
	w  int
}

const W = 5000 * 1000
const H = 5*30*2 + 10
const Z = H / 2

var used [H][H]bool
var wave [H][H][3][3][2]bool
var t [31]int
var n int
var maxw int

var q [W]move
var hd, tl int

func push(m move) {
	q[tl] = m
	if tl == W-1 {
		tl = 0
	} else {
		tl += 1
	}
}

func pop() move {
	ret := q[hd]
	if hd == W-1 {
		hd = 0
	} else {
		hd += 1
	}
	return ret
}

func empty() bool {
	return hd == tl
}

var ndx [3][3]int
var ndy [3][3]int
var ndxx [3][3]int
var ndyy [3][3]int

func do() {
	m := pop()

	tt := t[m.w]
	lx := m.x + (tt-1)*m.dx
	ly := m.y + (tt-1)*m.dy

	//fmt.Printf("%d lines from (%d, %d) with dir (%d, %d)\n", tt, m.x-Z, m.y-Z, m.dx, m.dy)

	for i := 0; i < tt; i++ {
		used[m.x+i*m.dx][m.y+i*m.dy] = true
	}

	if m.w+1 < n {
		ndx1 := ndx[1+m.dx][1+m.dy]
		ndy1 := ndy[1+m.dx][1+m.dy]
		x1 := lx + ndx1
		y1 := ly + ndy1

		nw := (m.w + 1) % 2
		if m.w+1 > maxw {
			maxw = m.w + 1
			clear()
		}

		if !wave[x1][y1][1+ndx1][1+ndy1][nw] {
			wave[x1][y1][1+ndx1][1+ndy1][nw] = true
			push(move{x1, y1, ndx1, ndy1, m.w + 1})
		}

		ndx2 := ndxx[1+m.dx][1+m.dy]
		ndy2 := ndyy[1+m.dx][1+m.dy]
		x2 := lx + ndx2
		y2 := ly + ndy2
		if !wave[x2][y2][1+ndx2][1+ndy2][nw] {
			wave[x2][y2][1+ndx2][1+ndy2][nw] = true
			push(move{x2, y2, ndx2, ndy2, m.w + 1})
		}
	}
}

func clear() {
	k := maxw % 2
	for x := 0; x < H; x++ {
		for y := 0; y < H; y++ {
			for i := 0; i < 3; i++ {
				for j := 0; j < 3; j++ {
					wave[x][y][i][j][k] = false
				}
			}
		}
	}
}

func main() {

	ndy = [3][3]int{
		{0, 1, 1},
		{-1, 0, 1},
		{-1, -1, 0},
	}

	ndx = [3][3]int{
		{-1, -1, 0},
		{-1, 0, 1},
		{0, 1, 1},
	}

	ndyy = [3][3]int{
		{-1, -1, 0},
		{-1, 0, 1},
		{0, 1, 1},
	}

	ndxx = [3][3]int{
		{0, -1, -1},
		{1, 0, -1},
		{1, 1, 0},
	}

	in := bufio.NewReader(os.Stdin)

	fmt.Fscanf(in, "%d\n", &n)
	for i := 0; i < n; i++ {
		fmt.Fscanf(in, "%d", &t[i])
	}

	for x := 0; x < H; x++ {
		for y := 0; y < H; y++ {
			for i := 0; i < 3; i++ {
				for j := 0; j < 3; j++ {
					for z := 0; z < 2; z++ {
						wave[x][y][i][j][z] = false
					}
				}
			}
			used[x][y] = false
		}
	}

	wave[Z][Z][0][1][0] = true
	push(move{Z, Z, 0, 1, 0})
	maxw = 0

	for !empty() {
		do()
	}

	ret := 0
	for x := 0; x < H; x++ {
		for y := 0; y < H; y++ {
			if used[x][y] {
				ret += 1
			}
		}
	}
	fmt.Println(ret)
}

