var reader = bufio.NewReader(os.Stdin)
var writer = bufio.NewWriter(os.Stdout)

const N  = 102
const Mask  = 2
const INF  = 1e9 + 1

var n int
var dp[N][N][Mask] int
var cnt[N] int
var a[N] int

func min(a int, b int) int {
	if a < b {
		return a
	}
	return b
}

func main()  {
	defer writer.Flush()
	fmt.Fscanf(reader, "%d\n", &n)

	var odd = 0
	for i := 1; i <= n; i++ {
		fmt.Fscanf(reader, "%d", &a[i])
		cnt[i] = cnt[i - 1]
		if a[i]%2 != 0 {
			cnt[i]++
			odd++
		}
	}

	var mo = n / 2
	if n % 2 != 0 {
		mo++
	}
	mo -= odd

	for i := 0; i <= n; i++ {
		for j := 0; j <= n; j++ {
			dp[i][j][0] = INF
			dp[i][j][1] = INF
		}
	}

	dp[0][0][0] = 0
	dp[0][0][1] = 0

	for i := 0; i < n; i++ {
		for j := 0; j <= mo; j++ {
			for k := 0; k < 2; k++ {
				if a[i+1] > 0 {
					// already
					var nk= a[i+1] % 2
					var add= 0
					if nk != k {
						add++
					}
					dp[i+1][j][nk] = min(dp[i+1][j][nk], dp[i][j][k]+add)
				} else {
					// even
					{
						var add= 0
						if k != 0 {
							add++
						}
						dp[i+1][j][0] = min(dp[i+1][j][0], dp[i][j][k]+add)
					}
					// odd
					{
						var add= 0
						if k != 1 {
							add++
						}
						if j+1 <= mo {
							dp[i+1][j+1][1] = min(dp[i+1][j+1][1], dp[i][j][k]+add)
						}
					}
				}
			}
		}
	}

	var ret = min(dp[n][mo][0], dp[n][mo][1])
	fmt.Fprintf(writer, "%d\n", ret)
}

