import (
	"fmt"
	"sort"
)

func work(capacity int, arrOne []int, arrTwo []int) int {
	sort.Ints(arrOne)
	sort.Ints(arrTwo)
	used, cnt, ans := 0, 0, 0
	for i, j := -1, -1; i <= len(arrOne); i++ {
		for ; j + 1 < len(arrTwo) && used + arrTwo[j + 1] <= capacity; j++ {
			used += arrTwo[j + 1]
			cnt += 2
		}
		for ; j >= 0 && used > capacity; j-- {
			used -= arrTwo[j]
			cnt -= 2
		}
		if used <= capacity && cnt > ans {
			ans = cnt
		}
		if i + 1 < len(arrOne) {
			used += arrOne[i + 1]
			cnt++
		}
	}
	// fmt.Println("-=", ans)
	return ans
}

func main() {
	var n, x int
	fmt.Scan(&n)
	if n == 1 {
		fmt.Println(0)
		return
	}
	cntOdd, cntEven := (n + 1) / 2, n / 2
	var odd, odd2, even, even2 []int
	last, emptyLen, ans := -1, 0, 0
	for i := 0; i < n; i++ {
		fmt.Scan(&x)
		if x == 0 {
			emptyLen++
			continue
		}
		x %= 2
		if x == 1 {
			cntOdd--
		} else {
			cntEven--
		}
		if last != -1 && x != last {
			ans++
		}
		if emptyLen > 0 {
			if last == -1 || last == x {
				if last == -1 {
					ans++
					if x == 0 {
						even = append(even, emptyLen)
					} else {
						odd = append(odd, emptyLen)
					}
				} else {
					ans += 2
					if x == 0 {
						even2 = append(even2, emptyLen)
					} else {
						odd2 = append(odd2, emptyLen)
					}
				}
			}
			emptyLen = 0
		}
		last = x
	}

	if last == -1 {
		fmt.Println(1)
		return
	}
	if emptyLen > 0 {
		ans++
		if last == 0 {
			even = append(even, emptyLen)
		} else {
			odd = append(odd, emptyLen)
		}
	}
	// fmt.Println("ans", ans)
	ans -= work(cntEven, even, even2)
	ans -= work(cntOdd, odd, odd2)
	fmt.Println(ans)
}

