func getMax(s, m int) string {
	var max string
	for s > 9 {
		max = max + "9"
		s -= 9
		m--
	}
	max = max + strconv.Itoa(s)
	m--
	for i := 0; i < m; i++ {
		max = max + "0"
	}
	return max
}

func getMin(s, m int) string {
	var min string
	for s > 9 {
		min = "9" + min
		s -= 9
		m--
	}
	if m == 1 {
		min = strconv.Itoa(s) + min
	} else {
		if s > 1 {
			min = strconv.Itoa(s-1) + min
			m--
		}
		for i := 0; i < m-1; i++ {
			min = "0" + min
		}
		min = "1" + min
	}
	return min
}

