func main() {
	reader := bufio.NewReaderSize(os.Stdin, 1<<13)
	writer := bufio.NewWriterSize(os.Stdout, 1<<13)
	n := ReadInt(reader)
	a := make([]int, n)
	for i := 0; i < n; i++ {
		a[i] = ReadInt(reader) - 1
	}
	fmt.Fprintln(writer, solve(a))
	writer.Flush()
}

func solve(a []int) int64 {
	n := len(a)
	res := int64(0)
	reached := make([]bool, n)
	for i := 0; i < n; i++ {
		if !reached[i] {
			k := i
			count := int64(0)
			for !reached[k] {
				reached[k] = true
				k = a[k]
				count++
			}
			if k != i {
				return -1
			}
			if count == 0 {
				continue
			}
			if count%2 == 0 {
				count /= 2
			}
			if res == 0 {
				res = count
			} else {
				res = lcm(res, count)
			}
		}
	}
	return res
}

func gcd(a, b int64) int64 {
	if b == 0 {
		return a
	}
	return gcd(b, a%b)
}

func lcm(a, b int64) int64 {
	g := gcd(a, b)
	return (a / g) * b
}

func min(a, b int) int {
	if a < b {
		return a
	}
	return b
}

func ReadInt(reader *bufio.Reader) int {
	return int(ReadInt64(reader))
}

func ReadInt64(reader *bufio.Reader) int64 {
	b, err := reader.ReadByte()
	for !isValid(b, err) {
		b, err = reader.ReadByte()
	}
	sign := int64(1)
	if b == '-' {
		sign *= -1
		b, err = reader.ReadByte()
	}
	res := int64(0)
	for isValid(b, err) {
		res = res*10 + int64(b-'0')
		b, err = reader.ReadByte()
	}
	return res * sign
}

func isValid(b byte, err error) bool {
	return err == nil && (('0' <= b && b <= '9') || b == '-')
}

