	fmt.Scanf("%d %d %d\n", &x, &y, &m)
	return x, y, m
}

func fibo(x, y, m int64) int64 {
	var n int64
	if x >= m || y >= m {
		return int64(0)
	}
	if n = 0; x < m && y < m && (x+y) <= y && (x+y) <= x {
		n = -1
		return n
	} else if math.Signbit(float64(x)) != math.Signbit(float64(y)) {
		if x > y {
			x, y = y, x
		}
		n = (-x) / y
		x = -((-x) % y)
	}

	for x < m && y < m {
		t := x + y
		if x < y {
			x = t
		} else {
			y = t
		}
		n++
	}
	return n
}

