func main() {
	io := FastIO{reader: bufio.NewReader(os.Stdin), writer: bufio.NewWriter(os.Stdout)}

	N := io.NextLong()
	M := io.NextLong()
	K := io.NextLong()
	X := io.NextLong()
	Y := io.NextLong()

	max := Max(GetAt(N, M, 1, 1, K), GetAt(N, M, 2, 1, K), GetAt(N, M, N - 1, 1, K))
	min := GetAt(N, M, N, M, K)
	sergey := GetAt(N, M, X, Y, K)

	io.Printf("%d %d %d\n", max, min, sergey)

	io.FlushOutput()
}

func GetAt(N, M, R, C, K int64) int64 {
	R--
	C--

	if R < 0 || R >= N || C < 0 || C >= M {
		return 0
	}

	var cnt int64
	if N == 1 {
		cnt = K / M
		if C < K % M {
			cnt++
		}
	} else {
		T := M * (N + N - 2)
		P := K / T
		if R == 0 || R == N - 1 {
			cnt = P
		} else {
			cnt = P * 2
		}
		rem := K % T
		// fmt.Printf("(%d, %d), T = %d, P = %d, cnt = %d, rem = %d\n", R, C, T, P, cnt, rem)
		// fmt.Printf("  idx1 = %d, idx2 = %d\n", (M * R) + C, M * ((2 * N) - R - 2) + C)
		if R < N - 1 && (M * R) + C < rem {
			cnt++
		}
		if M * ((2 * N) - R - 2) + C < rem {
			cnt++
		}
	}
	// fmt.Printf("  cnt = %d\n", cnt)
	return cnt
}

func Min(args ...int64) int64 {
	min := args[0]
	for i := 1; i < len(args); i++ {
		if (args[i] < min) {
			min = args[i]
		}
	}
	return min
}

func Max(args ...int64) int64 {
	max := args[0]
	for i := 1; i < len(args); i++ {
		if (args[i] > max) {
			max = args[i]
		}
	}
	return max
}

type FastIO struct {
	reader *bufio.Reader
	writer *bufio.Writer
}

func (io *FastIO) NextChar() byte {
	c, _ := io.reader.ReadByte()
	return c
}

func (io *FastIO) NextInt() int {
	c := io.NextChar()
	for IsSpaceChar(c) {
		c = io.NextChar()
	}
	sgn := 1
	if c == '-' {
		sgn = -1
		c = io.NextChar()
	}
	res := 0
	for !IsSpaceChar(c) {
		res = (res * 10) + int(c - '0')
		c = io.NextChar()
	}
	return sgn * res
}

func (io *FastIO) NextLong() int64 {
	c := io.NextChar()
	for IsSpaceChar(c) {
		c = io.NextChar()
	}
	sgn := int64(1)
	if c == '-' {
		sgn = -1
		c = io.NextChar()
	}
	res := int64(0)
	for !IsSpaceChar(c) {
		res = (res * 10) + int64(c - '0')
		c = io.NextChar()
	}
	return sgn * res
}

func (io *FastIO) NextIntArray(size int) []int {
	return io.NextIntArrayOffset(size, 0)
}

func (io *FastIO) NextIntArrayOffset(size, offset int) []int {
	arr := make([]int, size + offset)
	for i := 0; i < size; i++ {
		arr[i + offset] = io.NextInt()
	}
	return arr
}

func (io *FastIO) NextLongArray(size int) []int64 {
	return io.NextLongArrayOffset(size, 0)
}

func (io *FastIO) NextLongArrayOffset(size, offset int) []int64 {
	arr := make([]int64, size + offset)
	for i := 0; i < size; i++ {
		arr[i + offset] = io.NextLong()
	}
	return arr
}

func (io *FastIO) NextString() string {
	c := io.NextChar()
	for (IsSpaceChar(c)) {
		c = io.NextChar()
	}
	var sb bytes.Buffer
	for !IsSpaceChar(c) {
		sb.WriteByte(c)
		c = io.NextChar()
	}
	return sb.String()
}

func (io *FastIO) NextLine() string {
	c := io.NextChar()
	for (IsSpaceChar(c)) {
		c = io.NextChar()
	}
	var sb bytes.Buffer
	for !IsLineBreakChar(c) {
		sb.WriteByte(c)
		c = io.NextChar()
	}
	return sb.String()
}

func (io *FastIO) Printf(format string, args ...interface{}) {
	io.writer.WriteString(fmt.Sprintf(format, args...))
}

func (io *FastIO) FlushOutput() {
	io.writer.Flush()
}

func IsSpaceChar(c byte) bool {
	switch c {
	case 0, '\t', '\n', '\r', ' ':
		return true
	default:
		return false
	}
}

func IsLineBreakChar(c byte) bool {
	switch c {
		case 0, '\n', '\r':
			return true
		default:
			return false
	}
}

