func solve(mat []int, t1, t2, n, b, k int) int {
	for b < n {
		if mat[b] == 1 {
			t1--
		} else {
			t2--
		}
		b += k
	}
	ans := t1 - t2
	if ans < 0 {
		ans = 0 - ans
	}
	return ans
}
func main() {
	buf := bufio.NewReader(os.Stdin)
	var n, k int
	fmt.Fscanf(buf, "%d %d\n", &n, &k)
	mat := make([]int, n+1)
	var t1 int = 0
	var t2 int = 0
	for i := 0; i < n; i++ {
		fmt.Fscanf(buf, "%d", &mat[i])
		if mat[i] == 1 {
			t1++
		} else {
			t2++
		}
	}
	max := -1
	for b := 0; b < k; b++ {
		tmp := solve(mat, t1, t2, n, b, k)
		if max == -1 || max < tmp {
			max = tmp
		}
	}
	fmt.Printf("%d\n", max)
}

