func is_simple(n int64) bool {
    var result bool = true

    if math.Mod(float64(n), 2) == 0 {
        return false
    }


    end := int64(math.Pow(float64(n), 0.5)) + 1
    var i int64
    for i = 3; i <= end; i += 2 {
        if math.Mod(float64(n), float64(i)) == 0 {
            result = false
            break
        }   
    }

    return result
}

func main() {
    reader := bufio.NewReader(os.Stdin)

    var n int64
    fmt.Sscanln(Read(reader), &n)

    var result int64 = n

    if !is_simple(n) {
        result = 1

        if math.Mod(float64(n), 2) == 0 {
            result *= 2

            for math.Mod(float64(n), 2) == 0 {
                n = n / 2
            }
        }

        var i int64
        var end int64 = int64(math.Pow(float64(n), 0.5)) + 1
        for i = 3; i <= end; i += 2 {
            if math.Mod(float64(n), float64(i)) == 0 {
                result *= i
                for math.Mod(float64(n), float64(i)) == 0 {
                    n = n / i
                } 
                end = int64(math.Pow(float64(n), 0.5)) + 1
            }   
        }

        result *= n
    }

    writer := bufio.NewWriter(os.Stdout)   
    Write(writer, result)
}

