//	URL: http://codeforces.com/contest/911/problem/B
//	PROBLEM RESTATEMENT
//		Cake one has a pieces, cake two has b pieces.
//		Cake must be distributed to n plates s.t:
//			- Each plate contains >= x pieces, x >= 1.
//			- All cake is distributed.
//			- A given plate only has one type of cake pieces.
//		Given a, b, n, what is the maximum x we can achieve?
//	CONSTRAINTS
//		1 <= a, b <= 100; 2 <= n <= a + b
//	APPROACH
//		(1) Let c = # of plates with pieces of cake one.
//			Let n - c = # of plates with pieces of cake two.
//		(2) Assume the problem only had one cake.
//			The answer for one cake is trivially x = a / c.
//		(3) With two cakes, we are trying to maximize x, where x =
//			min(a/c, b/(n - c)), and where c is unknown.
//		(4) In O(n) time, we can iterate through all values of c [1, n) and
//			find the answer.

package main

import (
	"bufio"
	"fmt"
	"os"
)

func min(x int, y int) int {
	if x < y {
		return x
	}
	return y
}

func max(x int, y int) int {
	if x > y {
		return x
	}
	return y
}

func solve(n int, a int, b int) int {
	x := 0
	for c := 1; c < n; c += 1 {
		x = max(min(a/c, b/(n-c)), x)
	}
	return x
}

func main() {
	reader, writer := bufio.NewReader(os.Stdin), bufio.NewWriter(os.Stdout)
	defer writer.Flush()
	var n, a, b int
	fmt.Fscanf(reader, "%d %d %d\n", &n, &a, &b)
	fmt.Fprintf(writer, "%d\n", solve(n, a, b))
}

