// Node to store in queue
type Node struct {
	value int64
	prev  *Node
}

// NewNode to create node with value is n.
func NewNode(n int64) *Node {
	return &Node{
		value: n,
	}
}

func main() {
	var stdin *bufio.Reader
	// LOCAL
	f, _ := os.Open("input.txt")
	stdin = bufio.NewReader(f)

	// ONLINE JUDGE
	stdin = bufio.NewReader(os.Stdin)

	var a, b int64
	fmt.Fscan(stdin, &a, &b)

	var queue = []*Node{NewNode(a)}
	var seen = make(map[int64]bool)
	for len(queue) > 0 {
		var top = queue[0]
		queue = queue[1:]
		seen[top.value] = true

		if top.value == b {
			// Trace
			fmt.Println("YES")
			var res []int64
			for n := top; n != nil; n = n.prev {
				res = append(res, n.value)
			}
			fmt.Println(len(res))
			for i := len(res) - 1; i >= 0; i-- {
				fmt.Print(res[i], " ")
			}

			return
		}

		if top.value*2 <= b && !seen[top.value*2] {
			var n = NewNode(top.value * 2)
			n.prev = top
			queue = append(queue, n)
		}
		if top.value*10+1 <= b && !seen[top.value*10+1] {
			var n = NewNode(top.value*10 + 1)
			n.prev = top
			queue = append(queue, n)
		}

	}

	fmt.Println("NO")

}

