	"fmt"
	"os"
)

var bufin *bufio.Reader
var bufout *bufio.Writer

var a, b int
var trace map[int]int

func dfs(x int) bool {
	if x == b {
		return true
	}
	if x <= b/2 {
		y := x * 2
		_, found := trace[y]
		if !found {
			trace[y] = x
			if dfs(y) {
				return true
			}
		}
	}
	if x <= (b-1)/10 {
		y := x*10 + 1
		_, found := trace[y]
		if !found {
			trace[y] = x
			if dfs(y) {
				return true
			}
		}
	}
	return false
}

func main() {
	bufin = bufio.NewReader(os.Stdin)
	bufout = bufio.NewWriter(os.Stdout)
	defer bufout.Flush()

	fmt.Fscanf(bufin, "%d %d\n", &a, &b)
	trace = make(map[int]int)

	trace[a] = a
	if dfs(a) {
		fmt.Fprintf(bufout, "YES\n")

		var res []int
		for b != a {
			res = append(res, b)
			b = trace[b]
		}
		res = append(res, a)

		n := len(res)
		fmt.Fprintf(bufout, "%d\n", n)
		for i := n - 1; i >= 0; i-- {
			fmt.Fprintf(bufout, "%d ", res[i])
		}
	} else {
		fmt.Fprintf(bufout, "NO\n")
	}

}

