func main() {
	reader := bufio.NewReader(os.Stdin)
	arr1 := make([]int, 3)
	arr2 := make([]int, 3)
	for {
		line, _, err := reader.ReadLine()
		if err != nil {
			break
		}
		sum1 := 0
		for i := 0; i < 3; i++ {
			arr1[i] = int(line[i] - '0')
			sum1 += arr1[i]
		}
		sum2 := 0
		for i := 3; i < 6; i++ {
			arr2[i-3] = int(line[i] - '0')
			sum2 += arr2[i-3]
		}
		if sum1 == sum2 {
			fmt.Printf("0\n")
			continue
		}
		if sum1 < sum2 {
			arr1, arr2 = arr2, arr1
			sum1, sum2 = sum2, sum1
		}
		delta := sum1 - sum2
		count := 0
		for {
			sort.Sort(sort.IntSlice(arr1))
			sort.Sort(sort.IntSlice(arr2))
			count++
			if arr1[2] > 9-arr2[0] {
				if arr1[2] >= delta {
					break
				}
				delta -= arr1[2]
				arr1[2] = 0
			} else {
				if 9-arr2[0] >= delta {
					break
				}
				delta -= (9 - arr2[0])
				arr2[0] = 9
			}

		}
		fmt.Printf("%d\n", count)

	}
}

