func main() {
	scanner := bufio.NewScanner(os.Stdin)
	scanner.Scan()
	input := strings.TrimSpace(scanner.Text())

	values := make([]int, len(input))
	for i, a := range input {
		values[i] = int(a - '0')
	}

	fmt.Println(solver(values))
}

func solver(values []int) int {
	n := len(values) / 2
	valsA := values[:n]
	valsB := values[n:]
	sort.Ints(valsA)
	sort.Ints(valsB)

	sumA := sum(valsA)
	sumB := sum(valsB)

	if sumA == sumB {
		return 0
	}

	// lets assume that sumA always bigger sumB
	if sumB > sumA {
		sumA, sumB = sumB, sumA
		valsA, valsB = valsB, valsA
	}

	d := sumA - sumB
	deltaA := valsA[2]
	deltaB := 9 - valsB[0]

	if d <= max(deltaA, deltaB) {
		return 1
	}

	if deltaA > deltaB {
		valsA[2] = 0
	} else {
		valsB[0] = 9
	}

	d = diff(valsA, valsB)
	sort.Ints(valsA)
	sort.Ints(valsB)
	deltaA = valsA[2]
	deltaB = 9 - valsB[0]
	if d <= max(deltaA, deltaB) {
		return 2
	}

	return 3
}

func sum(values []int) int {
	sum := 0
	for i := 0; i < len(values); i++ {
		sum += values[i]
	}
	return sum
}

func diff(valsA, valsB []int) int {
	return sum(valsA) - sum(valsB)
}

func max(a, b int) int {
	if a > b {
		return a
	}
	return b
}

