const Mod = 100000000

func Solve(n1, n2, k1, k2 int) int {
	dp := [101][101][2]int{}
	dp[0][0][0] = 1
	dp[0][0][1] = 1
	for i := 0; i <= n1; i++ {
		for j := 0; j <= n2; j++ {
			for k := 1; k <= k1 && k <= i; k++ {
				dp[i][j][0] = (dp[i][j][0] + dp[i-k][j][1]) % Mod
			}
			for k := 1; k <= k2 && k <= j; k++ {
				dp[i][j][1] = (dp[i][j][1] + dp[i][j-k][0]) % Mod
			}
		}
	}
	return (dp[n1][n2][0] + dp[n1][n2][1]) % Mod
}

