	writer := bufio.NewWriter(os.Stdout)
	defer writer.Flush()

	var n1, n2, k1, k2 int
	fmt.Fscanf(reader, "%d %d %d %d\n", &n1, &n2, &k1, &k2)

	fmt.Fprintf(writer, "%d\n", Solve(n1, n2, k1, k2))
