const M = 1000000007

func Count(x, y int) int {
	dp := make([]int, x+1)
	dp[0] = 1
	for i := 1; i <= x; i++ {
		for j := 1; j <= y; j++ {
			if i-j >= 0 {
				dp[i] = (dp[i] + dp[i-j]) % M
			}
		}
	}
	return dp[x]
}

func Solve(n, k, d int) int {
	return (Count(n, k) - Count(n, d-1) + M) % M
}

