const mod = 1e9 + 7

var n, k, d int64
var visited []bool
var dp [][2]int64

func solve(n int64) {
	k, d = readInt(), readInt()
	visited, dp = make([]bool, n+1), make([][2]int64, n+1)
	dp[0][0] = 1
	O(do(n, 1), "\n")
}

func do(n, contains int64) int64 {
	if visited[n] {
		return dp[n][contains]
	}
	visited[n] = true
	for i := int64(1); i <= k && i <= n; i++ {
		if i < d {
			dp[n][0] += do(n-i, 0)
		} else {
			dp[n][1] += do(n-i, 0)
		}
		dp[n][1] += do(n-i, 1)
		dp[n][0] %= mod
		dp[n][1] %= mod
	}
	return dp[n][contains]
}

