const mod = 1e9 + 7

var n, k, d int
var visited []bool
var dp [][2]int

func solve(n int) {
	k, d = readInt(), readInt()
	visited, dp = make([]bool, n+1), make([][2]int, n+1)
	dp[0][0] = 1
	O(do(n, 1), "\n")
}

func do(n, contains int) int {
	if visited[n] {
		return dp[n][contains]
	}
	visited[n] = true
	for i := 1; i <= k && i <= n; i++ {
		if i < d {
			dp[n][0] += do(n-i, 0)
			dp[n][0] %= mod
		} else {
			dp[n][1] += do(n-i, 0)
			dp[n][1] %= mod
		}
		dp[n][1] += do(n-i, 1)
		dp[n][1] %= mod
	}
	return dp[n][contains]
}

