import (
	"bufio"
	"fmt"
	"os"
	"strconv"
)

type MyScanner struct {
	*bufio.Scanner
	justScanned bool
}

func NewMyScanner() *MyScanner {
	sc := bufio.NewScanner(os.Stdin)
	sc.Split(bufio.ScanWords)
	return &MyScanner{sc, false}
}

func (sc *MyScanner) Has() bool {
	sc.justScanned = true
	return sc.Scan()
}

func (sc *MyScanner) Int() int {
	if !sc.justScanned {
		sc.Scan()
	}
	sc.justScanned = false

	x, _ := strconv.Atoi(sc.Text())
	return x
}

func (sc *MyScanner) Bool() bool {
	if !sc.justScanned {
		sc.Scan()
	}
	sc.justScanned = false

	return sc.Bytes()[0] == byte('1')
}

var sc = NewMyScanner()

func solve() int {
	n := sc.Int()
	a := make([]bool, n)

	sum := 0
	for i := range a {
		a[i] = sc.Bool()
		if a[i] {
			sum++
		}
	}

	if sum == n {
		return n - 1
	}

	act, best := 0, 0
	for i := range a {
		if !a[i] {
			act++
			if act > best {
				best = act
			}
		} else {
			act--
			if act < 0 {
				act = 0
			}
		}
	}
	return best + sum
}

func main() {
	fmt.Println(solve())
}

