func count(s *string, n, k, l int) bool {
	for i := 0; i <= n+k-l*2; i++ {
		stat := true
		for j := 0; j < l; j++ {
			if i+j+l < n && (*s)[i+j] != (*s)[i+j+l] {
				stat = false
				break
			}
		}
		if stat {
			return true
		}
	}
	return false
}

