func main() {
	buf := bufio.NewReader(os.Stdin)

	var n, max, min int
	fmt.Fscanf(buf, "%d\n", &n)
	mat := make([]int, n)
	max = 0
	min = 100
	for i := 0; i < n; i++ {
		fmt.Fscanf(buf, "%d", &mat[i])
		if mat[i] > max {
			max = mat[i]
		}
		if mat[i] < min {
			min = mat[i]
		}
	}
	fmt.Fscanf(buf, "\n")
	if max == min {
		fmt.Printf("0\n")
		return
	}
	mid := (max + min) / 2
	hasmid := false
	for i := 0; i < n; i++ {
		if mat[i] != max && mat[i] != min && mat[i] != mid {
			fmt.Printf("-1\n")
			return
		}
		if mat[i] == mid {
			hasmid = true
		}
	}

	if ((max - min) & 1) == 1 {
		if max-min > 1&&hasmid {
			fmt.Printf("-1\n")
		}else{
			fmt.Printf("%d\n",max-min)
		}
	}else{
			fmt.Printf("%d\n",max-mid)
	}

}

