		fmt.Scan(&nums[i])
	}

	sort.Ints(nums)
	allEqual := true
	for i := 1; i < n; i++ {
		nums[i] -= nums[0]
		allEqual = allEqual && nums[i] == 0
	}
	if allEqual {
		fmt.Println(0)
		return
	}

	for i := 1; i <= 100; i++ {
