			if nums[j] == 0 {
				continue
			}
			if nums[j]%i != 0 {
				break
			}
			if nums[j]/i > 2 {
				break
			}
			if j == n-1 {
				fmt.Println(i)
				return
			}
		}
	}
	fmt.Println(-1)
