package main

import (
	"bufio"
	"fmt"
	"os"
	"sort"
)

func getUniqueElements(n int, a []int) []int {
	nums := make(map[int]bool)
	elems := []int{}
	for _, elem := range a {
		if !nums[elem] {
			nums[elem] = true
			elems = append(elems, elem)
		}
	}
	return elems
}

func Solve(n int, a []int) int {
	b := getUniqueElements(n, a)
	k := len(b)
	if k > 3 {
		return -1
	}
	sort.Ints(b)
	if len(b) == 1 {
		return 0
	}
	diff := b[len(b)-1] - b[0]
	if len(b) == 2 {
		if diff%2 == 1 {
			return diff
		}
		return diff / 2
	}
	if diff%2 == 1 || b[1]+diff/2 != b[2] {
		return -1
	}
	return diff / 2
}

func main() {
	reader := bufio.NewReader(os.Stdin)
	writer := bufio.NewWriter(os.Stdout)
	defer writer.Flush()

	var n int
	fmt.Fscanf(reader, "%d\n", &n)
	a := make([]int, n)
	for i := 0; i < n; i++ {
		fmt.Fscanf(reader, "%d", &a[i])
	}

	fmt.Fprintf(writer, "%d\n", Solve(n, a))
}

