func main() {
	reader := bufio.NewReader(os.Stdin)
	arr := gsls(reader)
	rot := gsli(reader)[0]

	start := pos(arr[0])
	end := pos(arr[1])

	// fmt.Printf("arr: %#v \n rot: %#v \n start: %v \n end: %v", arr, rot, start, end)

	cwEnd := posMod(start+rot, 4)
	ccwEnd := posMod(start-rot, 4)

	diff := posMod(end-start, 4)

	if diff == 0 || diff == 2 {
		fmt.Print("undefined")
	} else if end == cwEnd {
		fmt.Print("cw")
	} else if end == ccwEnd {
		fmt.Print("ccw")
	} else {
		fmt.Printf("cwEnd = %v, ccwEnd = %v", cwEnd, ccwEnd)
	}
	return
}

func pos(x string) (pos int) {
	switch x {
	case "^":
		pos = 0
	case ">":
		pos = 1
	case "v":
		pos = 2
	case "<":
		pos = 3
	}

	return
}

// Input helpers

// If you don't pass in a reference to the reader, and just instantiate a new
// one every time, it will work locally, with IO typed at human-speed, but not
// on Codeforces.

// Get Space-separated Line as Strings
//
// Example input:
// 1 test 382.0
// Example output:
// ["1", "test", "382.0"]

func gsls(reader *bufio.Reader) (arr []string) {
	// Get a full line
	input, _ := reader.ReadString('\n')

	//Strip newline and return chars, if any
	input = strings.TrimSuffix(input, "\n")
	input = strings.TrimSuffix(input, "\r")

	// Split at the spaces into an array
	arr = strings.Split(input, " ")

	return
}

// Get Space-separated Line as Integers
// Any non-valid integers will be 0
//
// Example input:
// test 1 12.3 -117
// Example output:
// [0, 1, 0, -117]

func gsli(reader *bufio.Reader) (arr []int) {
	stringArr := gsls(reader)

	for _, e := range stringArr {
		cur, _ := strconv.Atoi(e)
		arr = append(arr, cur)
	}

	return
}

// Get Space-separated Line as 64-bit Floats
// Any non-valid floats will be 0
//
// Example input:
// test 128.328 12 -11.0
// Example output:
// [0, 128.328, 12, -11]

func gslf(reader *bufio.Reader) (arr []float64) {
	stringArr := gsls(reader)

	for _, e := range stringArr {
		cur, _ := strconv.ParseFloat(e, 64)
		arr = append(arr, cur)
	}

	return
}

// Math helpers

// Positve Modulo
// Returns x mod y, but always positive

func posMod(x, y int) int {
	return (x%y + y) % y
}

