func solve() {
	board := make([][]byte, 9)
	for i, _ := range board {
		board[i] = make([]byte, 9)
	}

	for i := 0; i < 27; i++ {
		s := readString()
		for j, c := range s {
			x := j + ((i % 3) * 3)
			y := i / 3
			board[x][y] = byte(c)
		}
	}
	lasty := readInt() - 1
	lastx := readInt() - 1
	newx := (lastx % 3) * 3
	newy := (lasty % 3) * 3
	if isfull(board, newx, newy) {
		fillall(board)
	} else {
		fill(board, newx, newy)
	}

	for y := 0; y < 9; y++ {
		for x := 0; x < 9; x++ {
			fmt.Printf("%c", board[x][y])
			if x == 2 || x == 5 {
				fmt.Print(" ")
			}
		}
		fmt.Println()
		if y == 2 || y == 5 {
			fmt.Println()
		}
	}
}

func isfull(board [][]byte, x, y int) bool {
	for i := 0; i < 3; i++ {
		for j := 0; j < 3; j++ {
			if board[x+i][y+j] == '.' {
				return false
			}
		}
	}
	return true
}

func fill(board [][]byte, x, y int) {
	for i := 0; i < 3; i++ {
		for j := 0; j < 3; j++ {
			if board[x+i][y+j] == '.' {
				board[x+i][y+j] = '!'
			}
		}
	}
}

func fillall(board [][]byte) {
	fill(board, 0, 0)
	fill(board, 0, 3)
	fill(board, 0, 6)

	fill(board, 3, 0)
	fill(board, 3, 3)
	fill(board, 3, 6)

	fill(board, 6, 0)
	fill(board, 6, 3)
	fill(board, 6, 6)
}

