var (
	isNotPrime []bool
	primes     []int
	n          int
)

func main() {
	debug.SetGCPercent(-1)

	fmt.Scanf("%d", &n)
	// n = 20

	calcPrimes(n)

	left := getLowerBound(n)

	x0Lower := getLowerBound(left)

	for i := left + 1; i < n; i++ {
		x0Lower = min(x0Lower, getLowerBound(i))
	}

	fmt.Println(x0Lower)
}

func min(a, b int) int {
	if a < b {
		return a
	}

	return b
}

func max(a, b int) int {
	if a > b {
		return a
	}

	return b
}

func getLowerBound(n int) int {
	divider := findMaxPrimeDivider(n)

	return n - divider + 1
}

func findMaxPrimeDivider(x int) int {
	sqrtx := int(math.Sqrt(float64(x))) + 1

	for i := 0; i < len(primes) && primes[i] < sqrtx; i++ {
		if x%primes[i] == 0 {
			x /= primes[i]

			for isNotPrime[x] && x%primes[i] == 0 {
				x /= primes[i]
			}

			if !isNotPrime[x] {
				return x
			}
		}
	}

	return 1
}

func calcPrimes(n int) {
	isNotPrime = make([]bool, n+1)

	for i := 2; i*i <= n; i++ {
		if !isNotPrime[i] {
			for j := i * i; j <= n; j += i {
				isNotPrime[j] = true
			}
		}
	}

	primes = make([]int, 0, n/2)

	for i := 2; i <= n; i++ {
		if !isNotPrime[i] {
			primes = append(primes, i)
		}
	}
}

