)

type Range struct {
	left, right int
}

var (
	isNotPrime []bool
	primes     []int
	n          int
)

func main() {
	debug.SetGCPercent(-1)

	fmt.Scanf("%d", &n)
	// n = 1e6

	calcPrimes(n)

	x1Range := getRange(n)

	x0Range := getRange(x1Range.left)

	for i := x1Range.left + 1; i < x1Range.right; i++ {
		x0Range = joinRanges(x0Range, getRange(i))
	}

	fmt.Println(x0Range.left)
}

func min(a, b int) int {
	if a < b {
		return a
	}

	return b
}

func max(a, b int) int {
	if a > b {
		return a
	}

	return b
}

func joinRanges(r1, r2 Range) Range {
	left := min(r1.left, r2.left)

	right := max(r1.right, r2.right)

	return Range{left, right}
}

func getRange(n int) Range {
	divider := findMaxPrimeDivider(n)

	return Range{n - divider + 1, n}
}

func findMaxPrimeDivider(x int) int {
	sqrtx := int(math.Sqrt(float64(x))) + 1

	for i := 0; i < len(primes) && primes[i] < sqrtx; i++ {
		if x%primes[i] == 0 {
			x /= primes[i]

			for isNotPrime[x] && x%primes[i] == 0 {
				x /= primes[i]
			}

			if !isNotPrime[x] {
				return x
			}
		}
	}

	return 1
}

func calcPrimes(n int) {
	isNotPrime = make([]bool, n+1)

	for i := 2; i*i <= n; i++ {
		if !isNotPrime[i] {
			for j := i * i; j <= n; j += i {
				isNotPrime[j] = true
			}
		}
	}

	primes = make([]int, 0, n/2)

	for i := 2; i <= n; i++ {
		if !isNotPrime[i] {
			primes = append(primes, i)
		}
	}
}

