	maxi := 1
	for k := range memo {
		ChMax(&maxi, k)
	}

	l := x2 - maxi + 1
	r := x2

	_, P := sieve(x2)
	ans := INF_BIT30
	for _, p := range P {
		if p >= l {
			continue
		}

		q := Kiriage(l, p)
