func run(in io.Reader, out io.Writer) {
	const mod int64 = 1e9 + 7
	f := func(n, m int) int64 {
		if m > n {
			return 0
		}
		res := int64(1)
		for i := 0; i < m; i++ {
			res = res * int64(n-i) % mod
		}
