	var n, x, pos, less, gr int
	Fscan(in, &n, &x, &pos)
	sort.Search(n, func(mid int) bool {
		if mid < pos {
			less++
		} else if mid > pos {
			gr++
		}
		return mid > pos
	})
	other := n - 1 - less - gr
	Fprint(out, f(x-1, less)*f(n-x, gr)%mod*f(other, other)%mod)
}

