	}
	if m > n-x {
		return 0
	}
	res := int64(1)
	magic := int64(1000000007)
	for i := int64(0); i < l; i++ {
		res = (res * (x - i - 1)) % magic
	}
	for i := int64(0); i < m; i++ {
		res = (res * (n - x - i)) % magic
	}
	for i := int64(1); i <= n-m-l-1; i++ {
		res = (res * i) % magic
	}
	return res
}

