var min struct {
  	mt sync.RWMutex
	data int
}


func decision(p int64, x int64, y int64,  f changer, wg* sync.WaitGroup )  {
	defer wg.Done()
	s := x
	randomizer := func() bool{
		i := (s / 50) % 475
		for j:=0 ; j< 25; j++ {
			i = (i * 96 + 42) % 475
			if 26+i == p {
				return true
			}
		}
		return false
	}
	cur := 0
	flag := true
	for;flag;{
		if randomizer() {
			min.mt.Lock()
			if min.data > cur {
				min.data = cur
			}
			min.mt.Unlock()
			return
		}
		min.mt.RLock()
		if min.data < cur {
			flag = false
		} else {
			var dt int
			s, dt  = f(s)
			cur += dt
		}
		min.mt.RUnlock()
		if y>s{
			flag = false
		}
	}
}

func decision_starter(p int64, x int64, y int64,  f changer, wg* sync.WaitGroup) {
	wg.Add(1)
	go decision(p,x,y,f,wg)
