package main

import (
	"bufio"
	"fmt"
	"os"
)

type Edge struct {
	A int
	B int
}

func createMatrix(n int, m int, edges []Edge) [][]bool {
	matrix := make([][]bool, n)
	for i := 0; i < n; i++ {
		matrix[i] = make([]bool, n)
	}
	for _, edge := range edges {
		matrix[edge.A-1][edge.B-1] = true
		matrix[edge.B-1][edge.A-1] = true
	}
	return matrix
}

func Solve(n int, m int, edges []Edge) int {
	if n < 7 {
		return m
	}
	matrix := createMatrix(n, m, edges)
	minMutualNeighbors := n + 1
	for i := 0; i < n; i++ {
		for j := i + 1; j < n; j++ {
			mutualNeighbors := 0
			for z := 0; z < n; z++ {
				if z != i && z != j && matrix[i][z] && matrix[j][z] {
					mutualNeighbors += 1
				}
			}
			if mutualNeighbors < minMutualNeighbors {
				minMutualNeighbors = mutualNeighbors
			}
		}
	}
	return m - minMutualNeighbors
}

func main() {
	reader := bufio.NewReader(os.Stdin)
	writer := bufio.NewWriter(os.Stdout)
	defer writer.Flush()

	var n, m int
	fmt.Fscanf(reader, "%d %d\n", &n, &m)
	edges := make([]Edge, m)
	for i := 0; i < m; i++ {
		fmt.Fscanf(reader, "%d %d\n", &edges[i].A, &edges[i].B)
	}

	fmt.Fprintf(writer, "%d\n", Solve(n, m, edges))
}

