import "fmt"

const MOD = int64(1e9 + 7)

var (
	k   int64
	n   int64
	inv [100]int64
)

func qpow(x, k int64) int64 {
	var y int64 = 1
	for k > 0 {
		if k%2 > 0 {
			y = y * x % MOD
		}
		k >>= 1
		x = x * x % MOD
	}
	return y
}
func solve(x int64, cnt int64) int64 {
	dp := [10001][60]int64{}
	s := int64(1)
	for i := int64(0); i <= cnt; i++ {
		dp[0][i] = s
		s = s * x % MOD
	}
	for i := int64(1); i <= k; i++ {
		var s int64 = 0
		for j := int64(0); j <= cnt; j++ {
			s += dp[i-1][j]
			if s >= MOD {
				s -= MOD
			}
			dp[i][j] = s * inv[j+1] % MOD
		}
	}
	return dp[k][cnt]
}

func main() {
	for i := int64(1); i < 100; i++ {
		inv[i] = qpow(i, MOD-2)
	}
	fmt.Scanln(&n, &k)
	var ans int64 = 1
	for i := int64(2); i*i <= n; i++ {
		var c int64 = 0
		for n%i == 0 {
			c++
			n /= i
		}
		if c > 0 {
			ans = ans * solve(i, c) % MOD
		}
	}
	if n > 1 {
		ans = ans * solve(n, 1) % MOD
	}
	fmt.Println(ans)
}

