	var la, ra, ta, lb, rb, tb int64
	fmt.Fscanf(reader, "%d %d %d\n", &la, &ra, &ta)
	fmt.Fscanf(reader, "%d %d %d", &lb, &rb, &tb)

	factor := gcd(ta, tb)

	var ans1, ans2 int64

	// Bob first, Alice after
	// (la - lb) + (ka * ta) - (kb * tb) = diff > 0
	diff1 := (la - lb) % factor
	if diff1 < 0 {
		diff1 += factor
	}
	if rb - lb + 1 < diff1 {
		ans1 = 0
	} else if rb - lb + 1 > diff1 + (ra - la + 1) {
		ans1 = ra - la + 1
	} else {
		ans1 = rb - lb + 1 - diff1
	}

	diff2 := (lb - la) % factor
	if diff2 < 0 {
		diff2 += factor
	}
	if ra - la + 1 < diff2 {
		ans2 = 0
	} else if ra - la + 1 > diff2 + (rb - lb + 1) {
		ans2 = rb - lb + 1
	} else {
		ans2 = ra - la + 1 - diff2
	}
	if ans1 > ans2 {
		fmt.Printf("%d", ans1)
	} else {
		fmt.Printf("%d", ans2)
	}

}

