func fastRead(reader *bufio.Reader) (i int, j int) {
	var c rune
	c, _, _ = reader.ReadRune()

	//space = 32
	//space and between 0-9
	for c != 32 && c > 47 && c < 58 {
		//x = x*10+c
		i = (i << 1) + (i << 3) + int(c) - 48
		c, _, _ = reader.ReadRune()
	}

	c, _, _ = reader.ReadRune()
	//newline = 10
	for c != 10 && c > 47 && c < 58 {
		//x = x*10+c
		j = (j << 1) + (j << 3) + int(c) - 48
		c, _, _ = reader.ReadRune()
	}

	return
}

