func factorize(N, K int64) int64 {

	var U int64 = int64(math.Sqrt(float64(N)))
	//var U int64 = Sqrt(N)

	var k int64 = 1

	var i int64 = 1

	var d int64 = -1

	for {

		if N%i == 0 {

			d = i
			if dbg {
				fmt.Println("U, N, d, i, k, K", U, N, d, i, k, K)
			}
			if k == K {
				return d
			}

			k++

		}

		i = i + 1

		if i > U {
			break
		}

	}

	for {

		if N%i == 0 {

			d1 := N / i

			if d1 != d {

				d = d1

				if dbg {
					fmt.Println("U, N, d, i, k, K", U, N, d, i, k, K)
				}

				if k == K {
					return d
				}

				k++
			}

		}

		i = i - 1
		if i < 1 {
