func I(i ...interface{}) error {
	_, err := fmt.Fscan(r, i...)
	return err
}

func O(o ...interface{}) {
	fmt.Fprint(w, o...)
}

var (
	r *bufio.Reader
	w *bufio.Writer
)

func init() {
	if f, err := os.Open("in.goC"); err == nil {
		r = bufio.NewReader(f)
	} else {
		r = bufio.NewReader(os.Stdin)
	}
	w = bufio.NewWriter(os.Stdout)
}

func main() {
	defer w.Flush()
	var n uint64
	for I(&n) == nil {
		solve(n)
	}
}

func solve(n uint64) {
	var k, o, ans uint64
	I(&k)
	var arr []uint64
	for i := uint64(1); i <= uint64(math.Sqrt(float64(n))); i++ {
		if n%i == 0 {
			arr = append(arr, i)
			ans++
			if ans == k {
				o = i
				break
			}
		}
	}
	if ans < k {
		q := ans
		for q > 0 {
			q--
			if n/arr[q] == arr[q] {
			    continue
			}
			arr = append(arr, n/arr[q])
			ans++
			if ans == k {
				o = n / arr[q]
				break
			}
		}
	}
	if ans < k {
		O(-1, "\n")
	} else {
		O(o, "\n")
	}
}

