type Cin struct {
	scanner *bufio.Scanner
}

func (c *Cin) NextInt() int {
	c.scanner.Scan()
	line := c.scanner.Text()
	return c.convertInt(line)
}

func (c *Cin) NextIntSlice() []int {
	c.scanner.Scan()
	line := strings.Split(c.scanner.Text(), " ")
	var ret []int
	for _, s := range line {
		ret = append(ret, c.convertInt(s))
	}
	return ret
}

func (c *Cin) NextTwoInt() (int, int) {
	line := c.NextIntSlice()
	return line[0], line[1]
}

func (c *Cin) convertInt(data string) int {
	i, _ := strconv.Atoi(data)
	return i
}

var cin = &Cin{
	scanner: bufio.NewScanner(os.Stdin),
}

type element struct {
	value int
	step  int
	next  *element
	last  *element
}

func newElement(value, step int) *element {
	return &element{value: value, step: step}
}

type queue struct {
	head *element
	tail *element
}

func (q *queue) push(value, step int) {
	item := newElement(value, step)
	if q.isEmpty() {
		q.head = item
		q.tail = q.head
		return
	}
	item.last = q.tail
	q.tail.next = item
	q.tail = item
}

func (q *queue) isEmpty() bool {
	return q.head == nil
}

func (q *queue) pop() *element {
	if q.isEmpty() {
		panic("pop from empty queue")
	}
	item := q.head
	q.head = q.head.next
	return item
}

func newQueue() *queue {
	return &queue{}
}

func handle(n, m int) int {
	q := newQueue()
	q.push(n, 0)
	set := map[int]int{n: 0}
	for !q.isEmpty() {
		ele := q.pop()
		if ele.value == m {
			return ele.step
		}
		if ele.value > m {
			continue
		}
		if _, ok := set[ele.value*2]; !ok {
			set[ele.value*2] = ele.step + 1
			// fmt.Printf("val=[%v],step=[%v]\n", ele.value*2, ele.step+1)
			q.push(ele.value*2, ele.step+1)
		}
		if _, ok := set[ele.value*3]; !ok {
			set[ele.value*3] = ele.step + 1
			// fmt.Printf("val=[%v],step=[%v]\n", ele.value*3, ele.step+1)
			q.push(ele.value*3, ele.step+1)
		}
	}
	return -1
}

func main() {
	n, m := cin.NextTwoInt()
	fmt.Printf("%d\n", handle(n, m))
}

