import "fmt"

/**
 * 根据指定的层数，算出总的方块数
 */
func fetchSumByLevel(level int) int {
    return (level * (level + 1) * (level + 2) / 6)
}

/**
 * 在指定的区间内，二分搜索，查找一个能使总的方块数达到最大值的层数，这个最大值一定小于等于给定的方块数
 *
 * @param begin_level, 指定区间的起始（包括该下标）
 * @param end_level, 指定区间的结束（不包括该下标）
 * @param cubes_amt, 给定的方块数，最大层数时的总方块数一定要小于等于这个值
 *
 * @return 返回能叠的最大层数
 */
func binSearch(begin_level, end_level, cubes_amt int) int {
    for begin_level < end_level {
        cur_level := (begin_level + end_level) / 2
        cur_sum   := fetchSumByLevel(cur_level)

        if cubes_amt == cur_sum {
            return cur_level
        } else if cubes_amt > cur_sum {
            begin_level = cur_level + 1
        } else {
            end_level = cur_level
        }
    }
    return begin_level - 1
}

func main(){
    const (
        MIN_LEVEL = 1
        MAX_LEVEL = 40
    )

    cubes_amt := 0
    fmt.Scanf("%d", &cubes_amt)
    fmt.Printf("%d", binSearch(MIN_LEVEL, MAX_LEVEL, cubes_amt))
}

