const M = 1e9+7

func Solve(n, k int) int64 {
	dp := make([][]int64, k+1)
	for i := 1; i <= k; i++ {
		dp[i] = make([]int64, n+1)
	}
	for i := 1; i <= n; i++ {
		dp[1][i] = 1
	}
	for i := 1; i < k; i++ {
		for j := 1; j <= n; j++ {
			for d := 1; d*j <= n; d++ {
				dp[i+1][d*j] = (dp[i][j] + dp[i+1][d*j]) % M
			}
		}
	}
	s := int64(0)
	for _, elem := range dp[k] {
		s = (s + elem) % M
	}
	return s
}

