const MOD = 1000000007

var (
	G [][]int
	dp [][]int
)

func solve(n, k int) int {
	if k == 1 {
		return 1
	}
	if dp[n][k] != -1 {
		return dp[n][k]
	}
	dp[n][k] = solve(n, k - 1)
	for _, u := range G[n] {
		dp[n][k] += solve(u, k - 1)
		dp[n][k] %= MOD
	}
	return dp[n][k]
}

func main() {
	io := NewIo()
	defer io.Flush()
	N := io.NextInt()
	K := io.NextInt()
	G = make([][]int, N + 1)
	outdeg := make([]int, N + 1)
	for i := 1; i <= N; i++ {
		for j := 1; j <= i - 1; j++ {
			if i % j == 0 {
				G[i] = append(G[i], j)
				outdeg[i]++
			}
		}
	}
	dp = make([][]int, N + 1)
	for i := 1; i <= N; i++ {
		dp[i] = make([]int, K + 1)
		for j := 0; j <= K; j++ {
			dp[i][j] = -1
		}
	}
	ans := 0
	for i := 1; i <= N; i++ {
		ans += solve(i, K)
		ans %= MOD
		//for k := 1; k <= K; k++ {
		//	fmt.Fprintf(os.Stderr, "solve(%v,%v)=%v\n", i, k, solve(i, k))
		//}
	}
	io.PrintLn(ans)
}

