func toTernaryDigits(x int) []int {
  digits := []int{}
  if x == 0 {
    digits = append(digits, 0)
  }
  for x != 0 {
    digits = append(digits, x%3)
    x /= 3
  }
  return digits
}
func displayDigits(digits []int) {
  for i := len(digits)-1; i >= 0; i-- {
    fmt.Printf("%d", digits[i])
  }
  fmt.Printf("\n")
}

func main() {
  scanner = bufio.NewScanner(os.Stdin)
  scanner.Split(bufio.ScanWords)
  writer := bufio.NewWriter(os.Stdout)
  defer writer.Flush()

  a, c := int(getI()), int(getI())
  as, cs := toTernaryDigits(a), toTernaryDigits(c)
  for len(as) < len(cs) {
    as = append(as, 0)
  }
  for len(cs) < len(as) {
    cs = append(cs, 0)
  }
  n := len(as)
  bs := make([]int, n)
  for i := 0; i < n; i++ {
    bs[i] = (cs[i] + 3 - as[i]) % 3
  }
  b := 0
  for i := n-1; i >= 0; i-- {
