}


type stack []int


func reverse (s string) string {
	sb := strings.Builder{}
	for i := len(s) - 1; i >= 0; i--{
		sb.WriteString(s[i:i+1])
	}
	return sb.String()
}

func (s stack) Push(v int) stack {
	return append(s, v)
}

func (s stack) Pop() (stack, int, bool) {
	l := len(s)
	if l == 0 {return s, 0, false}
	return s[:l-1], s[l-1], true
}

func max(a, b int) int {
	if a > b {
		return a
	}
	return b
}

func min(a, b int) int {
	if a < b {
		return a
	}
	return b
}

