func solve(r, b []int) {
  rr, bb := 0, 0
  for i := range r {
    if r[i] > b[i] {
      rr++
    }
    if r[i] < b[i] {
      bb++
    }
  }
  score := 1
  if rr == 0 {
    score = -1
  } else if bb >= rr {
    score = (bb-rr+1)/rr + 1
    if (bb-rr+1)%rr > 0 {
      score++
    }
  }
  printf("%d", score)
}

