type V struct {
	P, Pchar, Link int
	Next, Walk [26]int
}

func (node V) String() string {
	return fmt.Sprintf("p = %v, pchar = %v, link = %v", node.P, node.Pchar, node.Link)
}

func CreateNode(p, pchar int) *V {
	v := &V{P:p, Pchar:pchar, Link:-1}
	for i := 0; i < len(v.Next); i++ {
		v.Next[i], v.Walk[i] = -1, -1
	}
	return v
}

func AddString(a string) {
	var v int = 0
	for i := 0; i < len(a); i++ {
		var c int = int(a[i] - 'A')
		if tree[v].Next[c] == -1 {
			tree[size] = CreateNode(v, c)
			tree[v].Next[c] = size
			size++
		}
		v = tree[v].Next[c]
	}
}

func Walk(v, c int) int {
	if tree[v].Walk[c] != -1 {
		return tree[v].Walk[c]
	}
	if tree[v].Next[c] != -1 {
		tree[v].Walk[c] = tree[v].Next[c]
	}else {
		if v == 0 {
			tree[v].Walk[c] = 0
		}else {
			tree[v].Walk[c] = Walk(Getlink(v), c)
		}
	}
	return tree[v].Walk[c]
}

func Getlink(v int) int {
	if tree[v].Link != -1 {
		return tree[v].Link
	}
	if v == 0 || tree[v].P == 0 {
		tree[v].Link = 0
	}else {
		tree[v].Link = Walk(Getlink(tree[v].P), tree[v].Pchar)
	}
	return tree[v].Link
}

func Dp(i, j, k int) int {
	if k == v {
		return -oo
	}
	if i == n {
		return 0
	}
	if j == m {
		return 0
	}

	if dp[i][j][k] != -1 {
		return dp[i][j][k]
	}

	var ret int = -oo
	if a[i] == b[j] {
		var next int = Walk(k, int(a[i] - 'A'))
		if next != v {
			ret = Max(ret, Dp(i + 1, j + 1, next) + 1)	
		}
	}

	ret = Max(ret, Dp(i + 1, j, k))
	ret = Max(ret, Dp(i, j + 1, k))

	dp[i][j][k] = ret
	return ret
}

func Print(i, j, k int) {
