	}
	if j == m {
		return
	}
	if a[i] == b[j] {
		var ret, which int = Dp(i + 1, j, k), 0
		if ret < Dp(i, j + 1, k) {
			ret, which = Dp(i, j + 1, k), 1
		}
		var next int = Walk(k, int(a[i] - 'A'))
		if next != v {
			if ret <= Dp(i + 1, j + 1, next) {
				ret, which = Dp(i + 1, j + 1, next), 2
			}	
		}

		if which == 0 {
