func factor(mp map[int]int,n int)  {
	for i:=2 ; i*i <= n; i++ {
		for n%i==0 {
			n/=i
			mp[i]++
		}
	}
	if n>1 {
		mp[n]++
	}
}
func newRes(mp map[int]int) int{
	val:=1
	for k,v := range mp {
		//fmt.Printf("k:%d,v:%d\n",k,v)
		for cnt:=0;cnt<(v+1)/2;cnt++ {
			val*=k
		}
	}
	return val
}

func main()  {
	var n int
	_,_=fmt.Scanln(&n)
	mp:=make(map[int]int)
	res,step:=n,0
	for {
		for k,_:= range mp {
			delete(mp,k)
		}
		factor(mp,res)
		ret:=newRes(mp)
		//fmt.Printf("before:%d ,after:%d\n",res,ret)
		if ret == res {
			break
		} else {
			step++
			res=ret
		}
	}
	flag:=false
	val:=res
	for {
		if val > n/val {
			break
		}

		val*=val
		if val== n{
			flag=true
			break
		}
	}
	if res==n {//prime
		step=0
	}else if !flag {//square
		step=step+1
	}
	fmt.Println(res,step)
}

