func main() {
	N := nextInt()
	if N == 1 {
		fmt.Println("1 0")
		return
	}
	primes := genPrimes()

	primeFactors := make(map[int]int)
	for _, p := range primes {
		for N%p == 0 {
			N /= p
			primeFactors[p]++
		}
		if N == 1 {
			break
		}
	}

	if N != 1 {
		primeFactors[N]++
	}

	//fmt.Fprintln(os.Stderr, primeFactors)

	maxExp := 0
	for _, exp := range primeFactors {
		if exp > maxExp {
			maxExp = exp
		}
	}

	bitlen := uint(bits.Len(uint(maxExp)))
	pow := 1 << (bitlen - 1)
	numSqrts := int(bitlen) - 1
	if pow < maxExp {
		pow <<= 1
		numSqrts++
	}

	base := 1
	muls := 0
	for p, exp := range primeFactors {
		base *= p
		if exp < pow {
			muls = 1
		}
	}

	fmt.Println(base, muls+numSqrts)
}

