func sum(n int64) int64 {
	var summ int64
	for n > 0 {
		summ += n%10
		n /= 10
	}
	return summ
}

func main(){
	var n int64
	r := bufio.NewScanner(os.Stdin)
	r.Split(bufio.ScanWords)
	w := bufio.NewWriter(os.Stdout)
	r.Scan()
	n, _ = strconv.ParseInt(r.Text(), 0, 64)
	var l int64 = int64(math.Sqrt(float64(n)))-40
	if l < 0 {
		l = 1
	}
	var s int64 = int64(math.Sqrt(float64(n)))+1
	for i:=l; i<s; i++ {
		if i*i+i*sum(i) == n {
