func build_tree() [][]uint64 {
	output := make([][]uint64, 35)
	for i:=0; i<=30; i++ {
		t := make([]uint64, 35)
		t[0]=1
		for j:=1; j<=i; j++ {
			t[j] = output[i-1][j] + output[i-1][j-1]
		}
		output[i] = t
	}
	return output
}

func main() {
	tree := build_tree()
	var n, m, t int
	var ans uint64
	fmt.Scan(&n, &m, &t)
	for i:=4; i<=n; i++ {
		if t-i < 1 || t-i > 30 {continue}
		ans += tree[n][i] * tree[m][t-i]
	}
	fmt.Println(ans)
}

