import (
	"fmt"
	"math"
	"strconv"
)

func main() {
	var nFloors int
	var sResident string
	var as []int
	_, _ = fmt.Scanln(&nFloors)

	for i := 0; i < nFloors; i++ {
		_, _ = fmt.Scan(&sResident)
		resident, _ := strconv.Atoi(sResident)
		as = append(as, resident)
	}

	bestX := math.MaxInt32
	for x := 0; x < len(as); x++ {
		if sum := sumForXA(x, as); sum < bestX {
			bestX = sum
		}
	}
	fmt.Println(bestX)
}

func sumForXA(x int, a []int) int {
	units := 0
	for i := 0; i < len(a); i++ {
		if a[i] > 0 {
			sum := 0
			// move from x to i
			sum += int(math.Abs(float64(i - x)))
			// move from i to 0
			sum += i
			// move from 0 to x
			sum += x
			// twice (elevator down, up)
			sum *= 2
			// multiply with a
			sum *= a[i]
			units += sum
		}
	}
	return units
}

