	scanner.Split(bufio.ScanWords)
	n := scanNum()
	p := make([]int, n)
	for i := 0; i < n; i++ {
		p[i] = scanNum()
	}
	min := math.MaxInt32
	for i := 0; i < n; i++ {
		sum := 0
		for j := 0; j < n; j++ {
			// Day
			sum += (abs(i-j) + j + i) * p[j]
			// Night
