const N = 205
const INF = -1000000000

func main() {
	io := NewFastIO(os.Stdin, os.Stdout)
	defer io.Flush()

	n, k := io.NextInt(), io.NextInt()
	s, t := io.Next(), io.Next()
	var suff [N][26]int

	for i := n; i >= 1; i-- {
		for j := 0; j < 26; j++ {
			suff[i][j] = suff[i+1][j]
		}
		suff[i][int(s[i-1]-'a')]++
	}

	if t[0] == t[1] {
		have, cur := 0, 0
		for i := 0; i < n; i++ {
			if s[i] == t[0] {
				cur++
			} else {
				have++
			}
		}
		cur += min(have, k)
		io.Println(cur * (cur - 1) / 2)
		return
	}

	var dp [N][N][N]int
	for i := 0; i < N; i++ {
		for j := 0; j < N; j++ {
			for k := 0; k < N; k++ {
				dp[i][j][k] = -1
			}
		}
	}

	a, b := int(t[0]-'a'), int(t[1]-'a')
	_ = a

	var dfs func(int, int, int) int
	dfs = func(i, r, c int) int {
		if r < 0 {
			return INF
		}
		if i == n+1 {
			if r == 0 {
				return 0
			} else {
				return INF
			}
		}
		if dp[i][r][c] != -1 {
			return dp[i][r][c]
		}
		ans := 0
		if s[i-1] == t[0] {
			ans = dfs(i+1, r, c+1) + suff[i+1][b]
			ans = max(ans, dfs(i+1, r-1, c))
			ans = max(ans, dfs(i+1, r-1, c)+c)
		} else if s[i-1] == t[1] {
			ans = dfs(i+1, r-1, c+1) - c + suff[i+1][b]
			ans = max(ans, dfs(i+1, r, c))
			ans = max(ans, dfs(i+1, r-1, c))
		} else {
			ans = dfs(i+1, r-1, c+1) + suff[i+1][b]
			ans = max(ans, dfs(i+1, r-1, c)+c)
			ans = max(ans, dfs(i+1, r, c))
		}
		dp[i][r][c] = ans
		return ans
