			mod[0] += int64((r - templ + 1) / 3)
			mod[1] += int64((r - templ + 1) / 3)
			mod[2] += int64((r - templ + 1) / 3)
			mod[0] %= int64(modBy)
			mod[1] %= int64(modBy)
