		if d%i == 0 {
			nxt := d / i
			divs = append(divs, i)
			if nxt != i {
				divs = append(divs, nxt)
			}
		}
	}

	lcmMin := float64(lcm(a, b))
	minK := float64(0)

	for _, q := range divs {
		if a%q != b%q {
			continue
		}
		var val float64
		k := q
		if a%q == 0 {
			val = float64(lcm(int64(a+q), int64(b+q)))
		} else {
			k = q - (a % q)
			val = float64(lcm(int64(a+k), int64(b+k)))
		}
		if val < lcmMin {
			lcmMin = val
			minK = float64(k)
		}
	}

	print(int(minK))
	print("\n")
}

