					b := in[0][i]*100 + in[2][j]*10 + in[1][k]
					c := in[2][i]*100 + in[0][j]*10 + in[1][k]
					d := in[1][i]*100 + in[0][j]*10 + in[2][k]
					e := in[1][i]*100 + in[2][j]*10 + in[0][k]
					f := in[2][i]*100 + in[1][j]*10 + in[0][k]
					if _, exists := o[a]; !exists {
