func main() {
  scanner = bufio.NewScanner(os.Stdin)
  scanner.Split(bufio.ScanWords)
  writer = bufio.NewWriter(os.Stdout)
  defer writer.Flush()

  zero := big.NewRat(0, 1)
  one := big.NewRat(1, 1)
  two := big.NewRat(2, 1)

  n, limit := getI(), getI()
  filled := make([][]*big.Rat, n)
  for r := range filled {
    filled[r] = make([]*big.Rat, r + 1)
    for c := range filled[r] {
      filled[r][c] = big.NewRat(0, 1)
    }
  }
  count := 0
  maxCount := (n + 1) * n / 2

  for t := 0; t < limit; t++ {
    pours := make([]*big.Rat, 1)
    pours[0] = big.NewRat(1, 1)
    for r := 0; r < n; r++ {
      allZero := true
      for _, pour := range pours {
        if pour.Cmp(zero) != 0 {
          allZero = false
          break
        }
      }
      if allZero {
        break
      }
      nextPours := make([]*big.Rat, r + 2)
      for i := range nextPours {
        nextPours[i] = big.NewRat(0, 1)
      }
      for c, pour := range pours {
        x := &big.Rat{}
        x.Add(filled[r][c], pour)
        if filled[r][c].Cmp(one) < 0 && x.Cmp(one) >= 0 {
          count++
          if count == maxCount {
            writer.WriteString(fmt.Sprintf("%d\n", count))
            return
          }
        }
        if x.Cmp(one) <= 0 {
          filled[r][c].Set(x)
          continue
        }
        pour.Sub(pour, one)
        pour.Add(pour, filled[r][c])
        filled[r][c].Set(one)
        pour.Quo(pour, two)
        nextPours[c].Add(nextPours[c], pour)
        nextPours[c + 1].Add(nextPours[c + 1], pour)
      }
      pours = nextPours
    }
  }

  writer.WriteString(fmt.Sprintf("%d\n", count))
}

