var one = int64(0x10000)

func progressRow(p [][]int64, row int) (spill bool) {
	spill = false
	for i := 0; i <= row; i++ {
		if p[row][i] > one {
			spill = true
			diff := p[row][i] - one
			diff >>= 1
			p[row+1][i] += diff
			p[row+1][i+1] += diff
			p[row][i] = one
		}
	}
	return spill
}

func progress(p [][]int64, n int) {
	p[0][0] += one
	for i := 0; i < n; i++ {
		spill := progressRow(p, i)
		if !spill {
			return
		}
	}
}

func solve(n, t int) int {
	p := make([][]int64, n+1)
	for i := 0; i <= n; i++ {
		p[i] = make([]int64, i+1)
	}
	for i := 0; i < t; i++ {
		progress(p, n)
	}
	count := 0
	for i := 0; i < n; i++ {
		for j := 0; j < i+1; j++ {
			if p[i][j] >= one {
				count++
			}
		}
	}
	return count
}

