const MAX_N = 500043
const MOD = 998244353

var F []int64

// var PM []int

func pow(a, b int64) int64 {
	var r int64 = 1
	for b > 0 {
		if b&1 == 1 {
			r *= a
			r %= MOD
		}
		a *= a
		a %= MOD
		b >>= 1
	}
	return r
}

func init() {
	F = make([]int64, MAX_N)
	F[0] = 1

	for i := 1; i < MAX_N; i++ {
		F[i] = int64(i) * F[i-1]
		F[i] %= MOD
	}
}

func IF(n int) int64 {
	x := F[n]
	return pow(x, MOD-2)
}

func nCr(n, r int) int64 {
	if n < r {
		return 0
	}
	res := F[n]
	res *= IF(r)
	res %= MOD
	res *= IF(n - r)
	res %= MOD
	return res
}

func solve(n, k int) int {
	var res int64

	for x := 1; x <= n; x++ {
		// x := PM[i]
		d := n / x
		if d < k {
			break
		}
		res += nCr(d-1, k-1)
		res %= MOD
	}

	return int(res)
}

