func solve(n, pos, l, r int) int {
	isLeftExist := abs(1-l) > 0
	isRightExist := abs(r-n) > 0
	if isLeftExist && isRightExist {
		return min(abs(pos-l), abs(pos-r)) + 1 + abs(l-r) + 1
	} else if isRightExist {
		return abs(pos-r) + 1
	} else if isLeftExist {
		return abs(pos-l) + 1
	}
	return 0
}

