package main

import (
	"bufio"
	"fmt"
	"math"
	"os"
)

func solve(c int, n int) float64 {
	total := math.Pow(2, float64(n))
	p := permutation(c, n)

	//right permutation answer / total permutation
	return p / total
}

func permutation(c int, n int) float64 {
	return factorial(n) / (factorial(n-c) * factorial(c))
}

func factorial(n int) float64 {
	res := 1
	for i := 1; i <= n; i++ {
		res *= i
	}

	return float64(res)
}

func main() {
	r := bufio.NewReader(os.Stdin)
	var command, received string
	var unrecognizedSignal int
	flag := true
	fmt.Fscanf(r, "%s\n", &command)
	fmt.Fscanf(r, "%s\n", &received)
	cache := map[byte]int{}

	for i := range command {
		cache[command[i]]++
	}

	for i := range received {
		if received[i] == '?' {
			unrecognizedSignal++
		} else {
			cache[received[i]]--
		}
	}

	for _, v := range cache {
		if v < 0 {
			flag = false
			break
		}
	}

	if flag {
		if unrecognizedSignal > 0 {
			fmt.Fprintf(os.Stdout, "%.10f\n", solve(cache['+'], unrecognizedSignal))

		} else {
			fmt.Fprintf(os.Stdout, "%.10f\n", float64(1))
		}
	} else {
		fmt.Fprintf(os.Stdout, "%.10f\n", float64(0))
	}

}

