	if diff < 0 {
		diff = -diff
	}
	if diff > unknown || (diff-unknown)%2 > 0 {
		fmt.Println("0")
		return
	}
	reverse = (unknown - diff) / 2
	if reverse < 0 {
		reverse = -reverse
	}
	fmt.Printf("%.11f\n", float64(combi(unknown, reverse))/float64(int(1)<<uint(unknown)))
}

