func main(){
	var str string
	fmt.Scanf("%s\n", &str)
	var dest = [5]string {"Danil", "Olya", "Slava", "Ann" ,"Nikita"}
	sum := 0
	for i := 0; i < 5; i++{
		sum += matchStr(str, dest[i])
	}
	if sum == 1{
		fmt.Println("YES")
	}else{
		fmt.Println("NO")
	}
}

func matchStr(src string, dest string) int{
	sum := 0
	for i := 0; i + len(dest) - 1 < len(src); i++{
		flag := true
		for j := 0; j < len(dest); j++{
			if src[i + j] != dest[j]{
				flag = false
			}
		}
		if flag {
			sum++
		}
	}
	return sum
}

