func test() {
	tests := []struct {
		in   string
		want string
	}{
		{in: `2`, want: `1`},
		{in: `3`, want: `2`},
		{in: `4`, want: `2`},
		{in: `5`, want: `3`},
		{in: `6`, want: `3`},
		{in: `7`, want: `3`},
		{in: `8`, want: `4`},
		{in: `9`, want: `4`},
		{in: `10`, want: `4`},
		{in: `11`, want: `4`},
		{in: `12`, want: `4`},
		{in: `13`, want: `5`},
		{in: `14`, want: `5`},
		{in: `15`, want: `5`},
		{in: `20`, want: `5`},
		{in: `21`, want: `6`},
	}
	for i, tt := range tests {
		fmt.Printf("=== TEST %d\n", i)
		buf := new(bytes.Buffer)
		solve(strings.NewReader(chomp(tt.in)), buf)
		if got, want := chomp(buf.String()), chomp(tt.want); got != want {
			fmt.Printf("%d: got %v, want %v\n", i, got, want)
		}
	}
}

func chomp(s string) string {
	return strings.Trim(s, "\n")
}

func assert(b bool) {
	if !b {
		_, file, line, ok := runtime.Caller(1)
		if ok {
			f, _ := os.Open(file)
			defer f.Close()
			s := bufio.NewScanner(f)
			lnum := 0
			for s.Scan() {
				lnum++
				if lnum == line {
					wd, _ := os.Getwd()
					fname, _ := filepath.Rel(wd, file)
					fmt.Printf("assertion fails: %s:%d: %v\n", fname, line, s.Text())
					break
				}
			}
		}
	}
}

