)

// Case .
type Case struct {
	a, b, x, y, z int64
}

func solve(c Case, w io.Writer) {
	a := 2*c.x + c.y - c.a
	b := c.y + 3*c.z - c.b
	if a < 0 {
		a = 0
	}
	if b < 0 {
		b = 0
	}
	w.Write(([]byte)(fmt.Sprintf("%d\n", a+b)))
}

func parseInput(lines <-chan string, res chan<- Case) {
	for {
		ab1, ok := <-lines
		if !ok {
			close(res)
			return
		}
		ab := int64s(words(ab1))
		xyz := int64s(words(<-lines))
		res <- Case{ab[0], ab[1], xyz[0], xyz[1], xyz[2]}
	}
}

func int64s(w []string) []int64 {
	res := make([]int64, 0, len(w))
	for _, word := range w {
		i, err := strconv.ParseInt(word, 10, 64)
		if err != nil {
			panic(err)
		}
		res = append(res, i)
	}
	return res
}

func words(s string) []string {
	prep := strings.Split(s, " ")
	res := make([]string, 0, len(prep))
	for _, l := range prep {
		if len(l) > 0 {
			res = append(res, l)
		}
	}
	return res
}

func run() error {
	exp, err := ioutil.ReadFile("expected.txt")
	if err == nil {
		fmt.Println("--------- expected --------- ")
		fmt.Println((string)(exp))
		fmt.Println("--------- computed --------- ")
	}

	inData, err := ioutil.ReadAll(os.Stdin)
	//inData, err := ioutil.ReadFile("in.txt")
	if err != nil {
		return fmt.Errorf("read input: %s", err)
	}
	lines := make(chan string, 8)
	cases := make(chan Case, 8)
	go func() {
		for _, line := range strings.Split((string)(inData), "\n") {
			s := strings.TrimSpace(line)
			if len(s) > 0 {
				lines <- s
			}
		}
		close(lines)
	}()
	go parseInput(lines, cases)
	for c := range cases {
		solve(c, os.Stdout)
	}
	return nil
}

func main() {
	if err := run(); err != nil {
		log.Fatal(err)
	}
}

