func main() {
	// in codeforces it seems int is equivalent with int32
	// so we need to say explicitly we need int64 to avoid overflow
	var a, b, x, y, z int64
	stdio := bufio.NewReader(os.Stdin)
	fmt.Fscanf(stdio, "%d %d\n%d %d %d", &a, &b, &x, &y, &z)

	// calculate total crystal we need for each kind of crystal
	needA := (2 * x) + y
	needB := (3 * z) + y
	// calculate total crystal should acquired
	fmt.Println(diff(a, needA) + diff(b, needB))
