	ss := []byte(s)
	vk := []byte("VK")
	max := bytes.Count(ss, vk)
	for i := range ss {
		if ss[i] == 'V' {
			ss[i] = 'K'
		} else {
			ss[i] = 'V'
		}
		mx := bytes.Count(ss, vk)
