type State struct {
  B, G, R int
}

var queue = []*State{}
var seen = make([]bool, 201 * 201 * 201)

func push(b, g, r int) {
  i := 201 * 201 * b + 201 * g + r
  if seen[i] {
    return
  }
  seen[i] = true
  queue = append(queue, &State{ b, g, r })
}

func main() {
  scanner = bufio.NewScanner(os.Stdin)
  scanner.Split(bufio.ScanWords)
  writer := bufio.NewWriter(os.Stdout)
  defer writer.Flush()

  _ = getI()
  s := getS()
  b, g, r := 0, 0, 0
  for _, ch := range s {
    if ch == 'B' {
      b++
    } else if ch == 'G' {
      g++
    } else {
      r++
    }
  }
  push(b, g, r)
  tail := 0
  for tail < len(queue) {
    x := queue[tail]
    tail++
    b, g, r = x.B, x.G, x.R
    if b > 0 && g > 0 {
      push(b - 1, g - 1, r + 1)
    }
    if b > 0 && r > 0 {
      push(b - 1, g + 1, r - 1)
    }
    if g > 0 && r > 0 {
      push(b + 1, g - 1, r - 1)
    }
    if b > 1 {
      push(b - 1, g, r)
    }
    if g > 1 {
      push(b, g - 1, r)
    }
    if r > 1 {
      push(b, g, r - 1)
    }
  }

  if seen[201 * 201] {
    writer.WriteString("B")
  }
  if seen[201] {
    writer.WriteString("G")
  }
  if seen[1] {
    writer.WriteString("R")
  }
  writer.WriteString("\n")
}

