func Solve(n int64) int64 {
	if n == 1 {
		return 1
	} else if n == 2 {
		return 2
	} else if n == 3 {
		return 6
	}
	if n%2 == 1 {
		return n * (n - 1) * (n - 2)
	} else if n%2 == 0 && n%3 == 0 {
		return (n - 1) * (n - 2) * (n - 3)
	}
	return n * (n - 1) * (n - 3)
}

