var MOD int64 = 1000000007

func sum(x, y int64) int64 {
	if y == 1 {
		return x
	}

	if y == 0 {
		return 1
	}

	if y%2 == 1 {
		return sum(x, y-1) * x % MOD
	}

	tmp := sum(x, y/2)
	return tmp * tmp % MOD
}

func calc(a int64, b int64) int64 {
	var num int64

	num = 0
	for a > 0 {
		num = num + a/b
		a = a / b
	}

	return sum(b, num)
}

var set []int = make([]int, 0, 1000)

func prime(p int) {
	m := int(math.Sqrt(float64(p + 1)))
	for i := 2; i <= m && i <= p; i++ {
		if p%i == 0 {
			set = append(set, i)

			for p%i == 0 {
				p = p / i
			}
		}
	}

	if p != 1 {
		set = append(set, p)
	}
}

func main() {
	var x, n int64
	fmt.Scanf("%d %d\n", &x, &n)

	prime(int(x))

	var ans int64 = 1
	for _, v := range set {
		ans = ans * calc(n, int64(v)) % MOD
	}

	fmt.Printf("%d\n", ans)
}

