func CF1528B(_r io.Reader, out io.Writer) {
	in := bufio.NewReader(_r)
	const mod = 998244353
	const mx int = 1e6
	d := [mx + 1]int{}
	for i := 1; i <= mx; i++ {
		for j := i; j <= mx; j += i {
			d[j]++
		}
	}

	var n int
	Fscan(in, &n)
	s := int64(d[n])
	for i, p2 := n-1, int64(1); i > 0; i-- {
		s = (s + p2*int64(d[i])) % mod
		p2 = p2 << 1 % mod
	}
	Fprint(out, s)
}

