type StepState struct {
	step, dist int
}
type PriorityQueue []*StepState

func (pq PriorityQueue) Len() int { return len(pq) }
func (pq PriorityQueue) Less(i, j int) bool {
	if pq[i].step != pq[j].step {
		return pq[i].step < pq[j].step
	}
	return pq[i].dist < pq[j].dist
}
func (pq PriorityQueue) Swap(i, j int) {
	pq[i], pq[j] = pq[j], pq[i]
}
func (pq *PriorityQueue) Push(x interface{}) {
	item := x.(*StepState)
	*pq = append(*pq, item)
}
func (pq *PriorityQueue) Pop() interface{} {
	old := *pq
	n := len(old)
	item := old[n-1]
	*pq = old[0 : n-1]
	return item
}

const (
	MOD = 998244353
)

var (
	smlDiv []int
)

type fact struct {
	base, exp int
}

func cntFact(n int) int {
	rem := n
	facts := make([]fact, 0)
	for rem > 1 {
		curSmlDiv := smlDiv[rem]
		if len(facts) == 0 || facts[len(facts)-1].base != curSmlDiv {
			facts = append(facts, fact{base: curSmlDiv, exp: 1})
		} else {
			facts[len(facts)-1].exp++
		}

		rem /= curSmlDiv
	}

	result := int64(1)
	for _, fact := range facts {
		result = (result * int64(fact.exp+1)) % MOD
	}
	return int(result)
}

func pow(a, b int) int {
	if b == 0 {
		return 1
	} else if b%2 == 1 {
		return int(int64(pow(a, b-1)) * int64(a) % MOD)
	} else {
		half := int64(pow(a, b/2))
		return int(half * half % MOD)
	}
}

