	smlDiv[1] = 1
	for i := 2; i <= N; i++ {
		if smlDiv[i] != -1 {
			continue
		}
		smlDiv[i] = i
		for j := int64(i) * int64(i); j <= int64(N); j += int64(i) {
			if smlDiv[j] == -1 {
				smlDiv[j] = i
			}
		}
	}

	ans := int64(0)
	for i := 1; i <= N; i++ {
		// fmt.Println(cntFact(i), pow(2, N-i-1))
		ans = (ans + int64(cntFact(i))*int64(pow(2, N-i-1))) % MOD
	}

	fmt.Fprintln(wr, ans)

}

