package main

import (
	"bufio"
	"os"
	"fmt"
)


var n, x int

const MOD  = 998244353

const MAX = 500

var dp [MAX + 5][MAX + 5]int64

var bp [MAX + 5][MAX + 5]int64

var fact [MAX + 5]int64
var nk [MAX + 5][MAX + 5]int64



func main() {

	r := bufio.NewReader(os.Stdin)

	fmt.Fscan(r, &n, &x)

	ans := solve()
	fmt.Println(ans)
}



func solve() int64 {

	fact[1] = 1
	fact[0] = 1

	for j := 2; j <= MAX; j++ {
		fact[j] = (fact[j - 1] * int64(j)) % MOD
	}

	for i := 1; i <= MAX; i++ {
		for j := 1; j <= i; j++ {
			//i choose j
			//i!/(i - j)! * j!
			ij := fact[i - j]
			invIj := modInverse(ij, MOD)

			jj := fact[j]
			invJ := modInverse(jj, MOD)

			ii := fact[i]

			temp := ii * invIj % MOD

			nk[i][j] = temp * invJ % MOD
		}
	}


	for i := 1; i <= MAX; i++ {
		for j := 1; j <= MAX; j++ {
			bp[i][j] = binpow(int64(i), int64(j), MOD)
		}
	}

	for i := 1; i <= x; i++ {
		dp[0][i] = 1
	}

	for i := 1; i <= x; i++ {
		dp[2][i] = int64(i)
	}

	for i := 3; i <= n; i++ {
		for j := 1; j <= x; j++ {

			var lastSegLen int
			segs := j/(i - 1)
			r := j % (i - 1)
			if r != 0 {
				lastSegLen = r
				segs++
			} else {
				lastSegLen = i - 1
			}

			//dp[i][j]

			for k := 1; k <= i; k++ {
				for p := 1; p <= segs - 1; p++ {

					t := bp[i - 1][k]

					t2 := nk[i][k]

					t3 := (t * t2) % MOD

					temp := t3 * dp[i - k][j - (i - 1) * p]

					temp %= MOD

					dp[i][j] += temp
					dp[i][j] %= MOD
				}
			}

			dp[i][j] += binpow(int64(lastSegLen), int64(i), MOD)
			dp[i][j] %= MOD

		}
	}

	return dp[n][x]
}

func binpow(a int64, b int64, m int64) int64 {
	a %= m
	var res int64 = 1
	for ; b > 0;
	{
		if b & 1 == 1 {
			res = res * a % m
		}

		a = a * a % m
		b >>= 1
	}
	return res
}

func modInverse(a int64, m int64) int64 {
	var x, y int64
	g := gcdExtended(a, m, &x, &y)

	if g != 1 {
		panic( "Inverse doesn't exist")
	} else {

		// m is added to handle negative x
		res := (x % m + m) % m
		return res
	}
}

func gcdExtended(a int64, b int64, x *int64, y *int64) int64 {

	// Base Case
	if a == 0 {
		*x, *y = 0,1
		return b
	}

	// To store results of recursive call
	var x1, y1 int64
	gcd := gcdExtended(b%a, a, &x1, &y1);

	// Update x and y using results of recursive
	// call
	*x = y1 - (b/a)*x1;
	*y = x1
	return gcd
}

