	scanner.Split(bufio.ScanWords)
	writer := bufio.NewWriter(os.Stdout)
	defer writer.Flush()
	k := scanInt(scanner)
	scanner.Scan()
	s := scanner.Text()
	n := len(s)
	pal := make([]int, n)
	for i, ch := range s {
		pal[i] = int(ch)
	}
	for i := (n-1)/2; i >= 0; i-- {
		j := n-1-i
		if pal[i] == pal[j] {
			continue
		}
		if pal[i] == '?' {
			pal[i] = pal[j]
		} else if pal[j] == '?' {
			pal[j] = pal[i]
		} else {
			writer.WriteString("IMPOSSIBLE\n")
			return
		}
	}
	seen := map[int]bool{}
	for i := 0; i < k; i++ {
		seen['a'+int(i)] = false
	}
	for _, ch := range pal {
		if ch != '?' {
			seen[ch] = true
		}
	}
	need := []int{}
	for ch, ok := range seen {
		if !ok {
			need = append(need, ch)
		}
	}
	sort.Ints(need)
	/*
	for _, ch := range pal {
		writer.WriteString(fmt.Sprintf("%c", ch))
	}
	writer.WriteString(fmt.Sprintf(" (k = %d)\n", k))
	writer.WriteString(fmt.Sprintf("need %d:", len(need)))
	for _, ch := range need {
		writer.WriteString(fmt.Sprintf(" %c", ch))
	}
	writer.WriteString("\n")
	*/
	nix := len(need)-1
	for i := (n-1)/2; i >= 0; i-- {
		if pal[i] != '?' {
			continue
		}
		j := n-1-i
		if nix == -1 {
			pal[i] = 'a'
			pal[j] = 'a'
		} else {
			pal[i] = need[nix]
			pal[j] = need[nix]
			nix--
		}
	}
	if nix != -1 {
		writer.WriteString("IMPOSSIBLE\n")
		return
	}
	for _, ch := range pal {
		writer.WriteString(fmt.Sprintf("%c", ch))
	}
	writer.WriteString("\n")
}

