	fmt.Scanf("%d %d %d", &n, &p, &k)
	fmt.Println(pages(n, p, k))
}

func pages(n, p, k int) string {
	var result []string

	if p-k > 1 {
		result = append(result, "<<")
	}
	for i := p - k; i < p; i++ {
		if i > 0 {
			result = append(result, strconv.Itoa(i))
		}
	}

	result = append(result, "("+strconv.Itoa(p)+")")

	for i := p + 1; i <= p+k; i++ {
		if i <= n {
			result = append(result, strconv.Itoa(i))
		}
	}

	if p+k < n {
		result = append(result, ">>")
	}

	return strings.Join(result, " ")
}

