	scanner.Split(bufio.ScanWords)
	writer := bufio.NewWriter(os.Stdout)
	defer writer.Flush()

	ax, ay := scanInt(scanner), scanInt(scanner)
	bx, by := scanInt(scanner), scanInt(scanner)
	cx, cy := scanInt(scanner), scanInt(scanner)
	x0, y0 := float64(bx-ax), float64(by-ay)
	l0 := math.Hypot(x0, y0)
	x0 /= l0
	y0 /= l0
	x1, y1 := float64(cx-bx), float64(cy-by)
	l1 := math.Hypot(x1, y1)
	x1 /= l1
	y1 /= l1
	if equal(x1, x0) && equal(y1, y0) {
		writer.WriteString("TOWARDS\n")
	} else if equal(x1, -y0) && equal(y1, x0) {
		writer.WriteString("LEFT\n")
	} else {
		writer.WriteString("RIGHT\n")
	}
}

