func min(a []int) int {
	minElem := a[0]
	for i := 1; i < 3; i++ {
		if a[i] < minElem {
			minElem = a[i]
		}
	}
	return minElem
}

func simulate(a int, b int, c int, day int) int {
	week := []string{"f", "r", "c", "f", "c", "r", "f"}
	daysFed := 0
	for {
		currentDay := day % 7
		if week[currentDay] == "f" && a > 0 {
			a -= 1
			daysFed += 1
		} else if week[currentDay] == "r" && b > 0 {
			b -= 1
			daysFed += 1
		} else if week[currentDay] == "c" && c > 0 {
			c -= 1
			daysFed += 1
		} else {
			break
		}
		day += 1
	}
	return daysFed
}

func simulateAll(a, b, c int) int {
	maxDays := 0
	for i := 0; i < 7; i++ {
		days := simulate(a, b, c, i)
		if days > maxDays {
			maxDays = days
		}
	}
	return maxDays
}

func Solve(a, b, c int) int {
	arr := []int{a / 3, b / 2, c / 2}
	minWeeks := min(arr)
	a -= 3 * minWeeks
	b -= 2 * minWeeks
	c -= 2 * minWeeks
	return 7*minWeeks + simulateAll(a, b, c)
}

