	var result int64
	result = 0
	length := len(list)

	for i := length - 1; i >= 0; i-- {
		if list[i] == 1 {
			result += int64(math.Pow(10, float64(length - i - 1)))
		}
	}

	if result >= 1 && result <= value {
		itemList[result] = true
	}
