	if startsWith < length {
		checkNumber(list, value)
		calc(append([]int64{}, list...), length, startsWith + 1, value)

		list[startsWith] = 1

		checkNumber(list, value)
		calc(append([]int64{}, list...), length, startsWith + 1, value)
	}
}

