type Cell int

const (
	EmptyCell Cell = iota
	PigCell
	WolfCell
)

func main() {
	s := bufio.NewScanner(os.Stdin)
	s.Split(bufio.ScanWords)
	n := nextInt(s)
	m := nextInt(s)
	gs := make([][]Cell, n)
	wolves := make([]Wolf, 0, n)
	for i := 0; i < len(gs); i++ {
		gs[i] = make([]Cell, m)
		s.Scan()
		row := s.Text()
		for j := 0; j < m; j++ {
			switch row[j] {
			case 'P':
				gs[i][j] = PigCell
			case 'W':
				gs[i][j] = WolfCell
				wolves = append(wolves, Wolf{i, j})
			default:
				gs[i][j] = EmptyCell
			}
		}
	}

	cache := initArray(len(wolves), -1)
	fmt.Println(solve(gs, wolves, len(wolves)-1, cache))
}

func solve(gs [][]Cell, wolves []Wolf, k int, cache []int) int {
	if k < 0 {
		return 0
	}
	if cache[k] != -1 {
		return cache[k]
	}

	i := wolves[k].i
	j := wolves[k].j

	a, b, c, d, e := 0, 0, 0, 0, 0
	if ix(gs, i-1, j) == PigCell {
		hs := copyGrid(gs)
		hs[i-1][j] = EmptyCell
		hs[i][j] = EmptyCell
		a = 1 + solve(hs, wolves, k-1, cache)
	}
	if ix(gs, i+1, j) == PigCell {
		hs := copyGrid(gs)
		hs[i+1][j] = EmptyCell
		hs[i][j] = EmptyCell
		b = 1 + solve(hs, wolves, k-1, cache)
	}
	if ix(gs, i, j+1) == PigCell {
		hs := copyGrid(gs)
		hs[i][j+1] = EmptyCell
		hs[i][j] = EmptyCell
		c = 1 + solve(hs, wolves, k-1, cache)
	}
	if ix(gs, i, j-1) == PigCell {
		hs := copyGrid(gs)
		hs[i][j-1] = EmptyCell
		hs[i][j] = EmptyCell
		d = 1 + solve(hs, wolves, k-1, cache)
	}
	e = solve(gs, wolves, k-1, cache)

	cache[k] = maximum(a, b, c, d, e)
	return cache[k]
}

type Wolf struct {
	i, j int
}

func maximum(xs ...int) int {
	max := 0
	for i := 0; i < len(xs); i++ {
		if xs[i] > max {
			max = xs[i]
		}
	}
	return max
}

func ix(gs [][]Cell, i, j int) Cell {
	if i < 0 || j < 0 || i > len(gs)-1 || j > len(gs[i])-1 {
		return EmptyCell
	}

	return gs[i][j]
}

func copyGrid(gs [][]Cell) [][]Cell {
	cs := make([][]Cell, len(gs))
	for i := 0; i < len(gs); i++ {
		cs[i] = make([]Cell, len(gs[i]))
		copy(cs[i], gs[i])
	}
	return cs
}

func copyAppend(ys []int, xs ...int) []int {
	ns := make([]int, len(ys), len(ys)+len(xs))
	copy(ns, ys)
	return append(ns, xs...)
}

func max(a, b int) int {
	if a > b {
		return a
	}
	return b
}

func toLower(x byte) byte {
	return x + ('a' - 'A')
}

func isUpper(x byte) bool {
	return x >= 'A' && x <= 'Z'
}

func initArray(n, x int) []int {
	xs := make([]int, n)
	for i := 0; i < n; i++ {
		xs[i] = x
	}
	return xs
}

func nextInt(s *bufio.Scanner) (n int) {
	s.Scan()
	n, _ = strconv.Atoi(s.Text())
	return
}

