func findMax() int {
	for i := 0; i < n; i++ {
		for j := 0; j < m; j++ {
			if board[i][j] == 'W' {
				a, b, c, d := 0, 0, 0, 0
				if i > 0 && board[i-1][j] == 'P' {
					a = max[i-1][j] + 1
				}
				if j > 0 && board[i][j-1] == 'P' {
					b = max[i][j-1] + 1
				}
				if i < n - 1 && board[i+1][j] == 'P' {
