}

func main() {
	var n, m int
	fmt.Scanf("%d %d\n", &n, &m)
	g1 := make([][]*Vertex, n)
	g2 := make([][]*Vertex, n)
	for i := range g1 {
		g1[i] = make([]*Vertex, m)
		g2[i] = make([]*Vertex, m)
		for j := range g1[i] {
			g1[i][j] = &Vertex{neighbors: make([]*Vertex, 2)}
			g2[i][j] = &Vertex{neighbors: make([]*Vertex, 2)}
		}
	}
	var horizon, vertical string
	fmt.Scanf("%s\n", &horizon)
	fmt.Scanf("%s\n", &vertical)
	for i, c := range horizon {
		if c == '>' {
			for j := 0; j < m-1; j++ {
				g1[i][j].neighbors[0] = g1[i][j+1]
			}
			for j := 1; j < m; j++ {
				g2[i][j].neighbors[0] = g2[i][j-1]
			}
		} else {
			for j := 1; j < m; j++ {
				g1[i][j].neighbors[0] = g1[i][j-1]
			}
			for j := 0; j < m-1; j++ {
				g2[i][j].neighbors[0] = g2[i][j+1]
			}
		}
	}
	for j, c := range vertical {
		if c == 'v' {
			for i := 0; i < n-1; i++ {
				g1[i][j].neighbors[1] = g1[i+1][j]
			}
			for i := 1; i < n; i++ {
				g2[i][j].neighbors[1] = g2[i-1][j]
			}
		} else {
			for i := 1; i < n; i++ {
				g1[i][j].neighbors[1] = g1[i-1][j]
			}
			for i := 0; i < n-1; i++ {
				g2[i][j].neighbors[1] = g2[i+1][j]
			}

		}
	}
	if dfs(g1) && dfs(g2) {
		fmt.Println("YES")
	} else {
		fmt.Println("NO")
	}
}

func dfs(g [][]*Vertex) bool {
	visited := make(map[*Vertex]struct{})
	v := g[0][0]
	dfsRecurse(v, visited)
	return len(visited) == len(g) * len(g[0])

}

func dfsRecurse(v *Vertex, visited map[*Vertex]struct{}) {
	visited[v] = struct{}{}
	for _, n := range v.neighbors {
		if n == nil {
			continue
		}
		if _, ok := visited[n]; !ok {
			dfsRecurse(n, visited)
		}
	}
}

