  }
  if b < 0 {
    a, b = -a, -b
  }
  g := gcd(a, b)
  return Fraction{ A: a/g, B: b/g }
}

type Line struct {
  A, B, C int
  Slope, Intercept Fraction
  Empty, Plane, Vertical, Horizontal bool
}

func makeLine(a, b, c int) Line {
  line := Line{ A: a, B: b, C: c }
  line.Slope = makeFraction(-a, b)
  line.Intercept = makeFraction(-c, b)
  if a == 0 && b == 0 {
    if c == 0 {
      line.Plane = true
    } else {
      line.Empty = true
    }
  } else if a == 0 {
    line.Horizontal = true
  } else if b == 0 {
    line.Vertical = true
  }
  return line
}

func solve(q, r Line) int {
  if q.Empty || r.Empty {
    return 0
  }
  if q.Plane || r.Plane {
    return -1
  }
  if q.Horizontal && r.Horizontal {
    if q.Intercept == r.Intercept {
      return -1
    }
    return 0
  }
  if q.Vertical && r.Vertical {
    if makeFraction(-q.C, q.A) == makeFraction(-r.C, r.A) {
      return -1
    }
    return 0
  }
  if q.Horizontal || q.Vertical || r.Horizontal || r.Vertical {
    return 1
  }
  if q.Slope == r.Slope {
    if q.Intercept == r.Intercept {
      return -1
    }
    return 0
  }
  return 1
}

func main() {
  scanner = bufio.NewScanner(os.Stdin)
  scanner.Split(bufio.ScanWords)
  writer := bufio.NewWriter(os.Stdout)
  defer writer.Flush()

  q := makeLine(getI(), getI(), getI())
  r := makeLine(getI(), getI(), getI())
  writer.WriteString(fmt.Sprintf("%d\n", solve(q, r)))
}

