	"sort"
)

var a, b int64
var aDiv, bDiv, sumDiv []int64


func checkDivisor(d []int64, n, div int64) []int64 {
	if n % div == 0 && div * div <= n {
		d = append(d, div)
		q := n / div
		if q * q != n {
			d = append(d, q)
		}
	}
	return d
}

func checkBest(divs []int64, n int64, smaller, bigger int64, best *int64) {
	ld := len(divs)
	l := sort.Search(ld, func(ind int) bool {
		return smaller < divs[ind]
	})
	if l == ld && divs[l - 1] > smaller {
		return
	}
	y := n / divs[l - 1]
	if y <= bigger {
		tmp := 2 * (smaller + bigger)
		if tmp < *best {
			*best = tmp
		}
	}
}


func main() {
	fmt.Scanf("%d %d", &a, &b)
	s := a + b
	aDiv, bDiv, sumDiv = make([]int64, 0), make([]int64, 0), make([]int64, 0)

	for i := int64(1); i*i <= s; i++ {
		aDiv = checkDivisor(aDiv, a, i)
		bDiv = checkDivisor(bDiv, b, i)
		sumDiv = checkDivisor(sumDiv, s, i)
	}

	makeLess := func(s []int64) func(x, y int) bool {
		return func(x, y int) bool {
			return s[x] < s[y]
		}
	}

	sort.Slice(aDiv, makeLess(aDiv))
	sort.Slice(bDiv, makeLess(bDiv))
	sort.Slice(sumDiv, makeLess(sumDiv))

	best := (s + 1) * 2

	for i := 0; i < len(sumDiv); i++ {
		smaller := sumDiv[i]
		if smaller * smaller > s {
			break
		}
		bigger := s / smaller
		checkBest(aDiv, a, smaller, bigger, &best)
		checkBest(bDiv, b, smaller, bigger, &best)
	}

	fmt.Println(best)
}

