type position struct {
	x, y int
}

func solve() {
	m := readString()
	pos := position{0, 0}
	badpos := make(map[position]bool)

	for _, c := range m {
		if badpos[pos] {
			fmt.Println("BUG")
			return
		}
		badpos[pos] = true

		up := position{pos.x, pos.y + 1}
		down := position{pos.x, pos.y - 1}
		right := position{pos.x + 1, pos.y}
		left := position{pos.x - 1, pos.y}

		switch c {
		case 'U':
			badpos[down] = true
			badpos[left] = true
			badpos[right] = true
			pos = up
			break
		case 'D':
			badpos[up] = true
			badpos[left] = true
			badpos[right] = true
			pos = down
			break
		case 'L':
			badpos[up] = true
			badpos[down] = true
			badpos[right] = true
			pos = left
			break
		case 'R':
			badpos[up] = true
			badpos[down] = true
			badpos[left] = true
			pos = right
			break
		}
	}
	if badpos[pos] {
		fmt.Println("BUG")
		return
	}
	fmt.Println("OK")
}

