func main() {
	path := []rune(nextWord())
	x, y := 0, 0
	visited := make(map[int64]bool)
	visited[0] = true
	for _, c := range path {
		switch c {
		case 'U':
			y--
		case 'D':
			y++
		case 'L':
			x--
		case 'R':
			x++
		}
		if _, ok := visited[int64(x * 1000 + y)]; ok {
			printf("BUG\n")
			return
		}
		count := 0
		if _, ok := visited[int64((x - 1) * 1000 + y)]; ok {
			count++
		}
		if _, ok := visited[int64((x + 1) * 1000 + y)]; ok {
			count++
		}
		if _, ok := visited[int64(x * 1000 + y - 1)]; ok {
			count++
		}
		if _, ok := visited[int64(x * 1000 + y + 1)]; ok {
			count++
		}
		if count > 1 {
			printf("BUG\n")
			return
		}
		visited[int64(x * 1000 + y)] = true
	}
