package main

import (
	"bufio"
	"fmt"
	"os"
)

type Node struct {
	X int
	Y int
}

func getAdjacentNodes(n Node) []Node {
	return []Node{
		Node{X: n.X - 1, Y: n.Y},
		Node{X: n.X + 1, Y: n.Y},
		Node{X: n.X, Y: n.Y - 1},
		Node{X: n.X, Y: n.Y + 1},
	}
}

func Solve(path string) string {
	currentPosition := Node{X: 0, Y: 0}
	visited := make(map[Node]int)
	visited[currentPosition] = 0
	for index, char := range path {
		currentTime := index + 1
		for _, node := range getAdjacentNodes(currentPosition) {
			_, ok := visited[node]
			if !ok {
				visited[node] = currentTime
			}
		}
		s := string(char)
		if s == "L" {
			currentPosition.X -= 1
		} else if s == "R" {
			currentPosition.X += 1
		} else if s == "U" {
			currentPosition.Y += 1
		} else if s == "D" {
			currentPosition.Y -= 1
		}
		time, ok := visited[currentPosition]
		if ok && time < currentTime {
			return "BUG"
		} else if !ok {
			visited[currentPosition] = currentTime + 1
		}
	}
	return "OK"
}

func main() {
	reader := bufio.NewReader(os.Stdin)
	writer := bufio.NewWriter(os.Stdout)
	defer writer.Flush()

	var path string
	fmt.Fscanf(reader, "%s\n", &path)
	fmt.Fprintf(writer, "%s\n", Solve(path))
}

