func isalpha(c rune) bool {
	if c >= 'a' && c <= 'z' {
		return true;
	}
	if c >= 'A' && c <= 'Z' {
		return true;
	}
	return false;
}

func isdigit(c rune) bool {
	if c >= '0' && c <= '9' {
		return true;
	}
	return false;
}

func do_str(s string) bool {
	idx := strings.Index(s, "@");
	if idx == -1 {
		// No "@"
		return false;
	}

	username := s[0:idx];
	if len(username) > 16 || len(username) < 1 {
		return false;
	}

	for _, c := range(username) {
		if isalpha(c) { continue }
		if isdigit(c) { continue }
		if c == '_' { continue }
		return false
	}

	if len(s[idx:]) == 1 {
		return false;
	}
	var resource string;
	var hostname string;

	rest := s[idx+1:]
	idx = strings.Index(rest, "/");
	if idx == -1 {
		resource = "";
		hostname = rest;
	} else {
		resource = rest[idx:];
		if len(resource) == 1 {
			return false;
		}
		resource = rest[idx+1:];
		hostname = rest[0:idx];
	}

	if len(hostname) < 1 || len(hostname) > 32 {
		return false
	}
	for _, c := range(hostname) {
		if isalpha(c) { continue }
		if isdigit(c) { continue }
		if c == '_' { continue }
		if c == '.' { continue }
		return false
	}
	words := strings.Split(hostname, ".");
	for _, word := range(words) {
		if len(word) < 1 || len(word) > 16 {
			return false;
		}
	}
	if len(resource) > 16 {
		return false;
	}
	for _, c := range(resource) {
		if isalpha(c) { continue }
		if isdigit(c) { continue }
		if c == '_' { continue }
		return false
	}

	return true
}

package main

import (
  "os"
  "bufio"
  "strconv"
  "strings"
  "fmt"
)

var scanner *bufio.Scanner

func getI64() int64 {
  scanner.Scan()
  x, _ := strconv.ParseInt(scanner.Text(), 10, 64)
  return x
}
func getI() int {
  return int(getI64())
}
func getF() float64 {
  scanner.Scan()
  x, _ := strconv.ParseFloat(scanner.Text(), 64)
  return x
}
func getS() string {
  scanner.Scan()
  return scanner.Text()
}

var validChars = "_0123456789abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ"

func valid(s string) bool {
  if len(s) < 1 || len(s) > 16 {
    return false
  }
  for _, ch := range s {
    if strings.IndexRune(validChars, ch) == -1 {
      return false
    }
  }
  return true
}

func validate(s string) bool {
  if strings.Count(s, "@") != 1 || strings.Count(s, "/") > 1 {
    return false
  }

  parts := strings.Split(s, "@")
  username, hostname := parts[0], parts[1]
  if !valid(username) {
    return false
  }

  if strings.Count(hostname, "/") == 1 {
    parts = strings.Split(hostname, "/")
    hostname = parts[0]
    resource := parts[1]
    if !valid(resource) {
      return false
    }
  }

  parts = strings.Split(hostname, ".")
  for _, part := range parts {
    if !valid(part) {
      return false
    }
  }

  return true
}

func main() {
  scanner = bufio.NewScanner(os.Stdin)
  scanner.Split(bufio.ScanWords)
  writer := bufio.NewWriter(os.Stdout)
  defer writer.Flush()

  s := getS()
  result := "YES"
  if !validate(s) {
    result = "NO"
  }
  writer.WriteString(fmt.Sprintf("%s\n", result))
}

