	ret := 0
	sqrtQ := math.Sqrt(float64(q))
	for i := 1; float64(i) < sqrtQ; i++ {
		if q%i != 0 || q/i < b {
			continue
		}
		ret++
		if i <= b {
			continue
		}
		ret++
	}
	if sqrtQ > float64(b) && int(sqrtQ)*int(sqrtQ) == q {
		ret++
	}
	return ret
}

