const mod = 998244353

func binpow(a, n uint64) (res uint64) {
	res = 1
	for n != 0 {
		if (n & 1) != 0 {
			res *= a
			res %= mod
		}
		a *= a
		a %= mod
		n >>= 1
	}
	return res
}

// http://e-maxx.ru/algo/reverse_element
func inv(a uint64) uint64 {
	return binpow(a, mod-2)
}

func main() {
	ints := getInts()

	n := uint64(ints[0])
	m := uint64(ints[1])

	if n-1 > m {
		fmt.Println(0)
		return
	}

	if n == 2 {
		fmt.Println(0)
		return
	}

	ans := uint64(1)

	// C(m, n-1)
	for i := m; i > n-1; i-- {
		ans *= uint64(i)
		ans %= mod
	}
	for i := m - (n - 1); i > 1; i-- {
		ans *= inv(i)
		ans %= mod
	}

	// * 2^(n-3)
	ans *= binpow(2, n-3)
	ans %= mod

	// * (n-2)
	ans *= n - 2
	ans %= mod

	fmt.Println(ans)
}

