import "fmt"

// Retorna slice de slices com as duplas retiradas.
func possiveisJogadas(row []int, num int, x int) [][]int {
	duplas := make([][2]int, 0)

	for i := 0; i+1 <= num-1; i++ {
		if row[i] == x && row[i] == row[i+1] {
			duplas = append(duplas, [2]int{i, i + 1})
		}
	}

	possibilidades := make([][]int, len(duplas))

	for i, v := range duplas {
		copia := make([]int, num)
		copy(copia, row)
		x, y := v[0], v[1]

		possibilidades[i] = append(copia[:x], copia[y+1:]...)

	}

	return possibilidades
}

// Remove um range de um array. [x, y] != [x, y)
func removerElementos(row *[]int, x, y int) {
	*row = append((*row)[:x], (*row)[y+1:]...)
}

func limparRow(row []int) []int {
	i := 1
	grupo := 1
	grupoAchado := false
	for {
		if i >= len(row) {
			if grupo >= 3 {
				removerElementos(&row, i-grupo, i-1)
			}
			break
		}

		if row[i] == row[i-1] {
			grupo++
			if grupo >= 3 {
				grupoAchado = true
			}
		} else {
			if grupoAchado {
				removerElementos(&row, i-grupo, i-1)
				i = 0
				grupoAchado = false

			}
			grupo = 1
		}

		i++
	}

	return row
}

func main() {
	// len(row), num de cores, cor escolhida pelo player.
	var num, k, x int
	fmt.Scan(&num, &k, &x)

	// Criar slice que representa a row.
	row := make([]int, num)
	for i := 0; i < num; i++ {
		fmt.Scan(&row[i])
	}

	// Copia e algoritmos.
	jogadas := possiveisJogadas(row, num, x)

	maior := 0
	for _, jogada := range jogadas {
		cont := num - len(limparRow(jogada))
		if cont > maior {
			maior = cont
		}
	}
	fmt.Println(maior)
}

