func get_type(l1, r1, l2, r2 int) int {
	if r1 < l2 || r2 < l1 {
		return 0 // 相离
	}

	if l1 == l2 && r1 == r2 {
		return 1 // 相等
	}

	if l1 < l2 && r2 < r1 {
		return 2 // 包含
	}

	if l2 <= l1 && r1 <= r2 {
		return 3 // 被包含
	}

	if l2 <= r1 && r1 <= r2 {
		return 4
	}

	return 5 // 相交
}

func intersect(x1, y1, x2, y2, x3, y3, x4, y4 int) (int, int, int, int) {
	x_type := get_type(x1, x2, x3, x4)
	y_type := get_type(y1, y2, y3, y4)

	if x_type == 0 || y_type == 0 {
		return x1, y1, x2, y2
	} else if x_type == 1 || x_type == 3 {
		if y_type == 1 {
			return -1, -1, -1, -1
		} else if y_type == 2 {
			return x1, y2, x2, y2
		} else if y_type == 3 {
			return -1, -1, -1, -1
		} else if y_type == 4 {
			return x1, y1, x2, y3
		} else { // 5
			return x1, y4, x2, y2
		}
	} else if x_type == 2 {
		return x1, y1, x2, y2
	} else if x_type == 4 {
		if y_type == 1 || y_type == 3 {
			return x1, y1, x3, y2
		} else { // 2, 4, 5
			return x1, y1, x2, y2
		}
	} else { // 5
		if y_type == 1 || y_type == 3 {
			return x4, y1, x2, y2
		} else { // 2, 4, 5
			return x1, y1, x2, y2
		}
	}
}

