type Point struct {
	X int
	Y int
}

type Rectangle struct {
	BottomLeft Point
	TopRight   Point
}

func max(x int, y int) int {
	if x > y {
		return x
	}
	return y
}

func min(x int, y int) int {
	if x < y {
		return x
	}
	return y
}

func intersection(R1, R2 Rectangle) Rectangle {
	bottomLeft := Point{
		X: max(R1.BottomLeft.X, R2.BottomLeft.X),
		Y: max(R1.BottomLeft.Y, R2.BottomLeft.Y),
	}
	topRight := Point{
		X: min(R1.TopRight.X, R2.TopRight.X),
		Y: min(R1.TopRight.Y, R2.TopRight.Y),
	}
	if topRight.X <= bottomLeft.X || topRight.Y <= bottomLeft.Y {
		return Rectangle{BottomLeft: Point{0, 0}, TopRight: Point{0, 0}}
	}
	return Rectangle{BottomLeft: bottomLeft, TopRight: topRight}
}

func area(R Rectangle) int64 {
	return int64(R.TopRight.X-R.BottomLeft.X) * int64(R.TopRight.Y-R.BottomLeft.Y)
}

func Solve(R1, R2, R3 Rectangle) string {
	R4 := intersection(R1, R2)
	R5 := intersection(R1, R3)
	R6 := intersection(R4, R5)
	coveredArea := area(R4) + area(R5) - area(R6)
	if area(R1) > coveredArea {
		return "YES"
	}
	return "NO"
}

