	n, _ = strconv.ParseInt(r.Text(), 0, 64)
	r.Scan()
	m, _ = strconv.ParseInt(r.Text(), 0, 64)
	r.Scan()
	k, _ = strconv.ParseInt(r.Text(), 0, 64)
	const max int64 = 1000000009
	var x int64 = (m-(n-m)*(k-1))/k
	if x < 0 {
		x = 0
	}
	var res int64 = exp(x, 2)
	var final int64 = (2*k*(res-1))%max+m-(k*x)%max
	final = final%max
	w.WriteString(strconv.FormatInt(final, 10)+"\n")
	w.Flush()
}

