func count(N int) int{
	h := 0
	v := 0
	area := h*v
	for i:= 1 ; i<=N;i++{
		if i == 1{
			h = 1
			v = 1
			area = h*v
		}else{
			if i > area && math.Mod(math.Sqrt(float64(i)),1) != 0{
				h += 1
			}else if i > area && math.Mod(math.Sqrt(float64(i)),1) == 0{
				h -=1
				v += 1
			}
			area = h*v
		}
	}
	return h+v
}

