// a+b+e+g == a+c+f+g == b+d+g+h == c+d+g+i
//
// b+e = c+f
// a+f = d+i
// b+h = c+i
// a+e = d+h
//
// e-f = c-b
// h-i = c-b
// e-h = d-a
// f-i = d-a
//
// f+h = e+i
//
// g can be anything from 1 to n
// assume c >= b && d >= a (problem is symmetric)
// i can be from 1 to (n-(c-b)-(d-a))
// h = i + (c-b); from (1+(c-b)) to (n-(d-a))
// f = i + (d-a); from (1+(d-a)) to (n-(c-b))
// e = i + (c-b) + (d-a); from (1+(c-b)+(d-a)) to n
//
// total combinations: n * (n-(c-b)-(d-a)) assuming c>=b && d>=a
//  
func Combinations(n, a, b, c, d uint64) uint64 {
	if b > c {
		c, b = b, c
	}
	if a > d {
		d, a = a, d
	}
	if (c-b)+(d-a) >= n {
		return 0
	}
	return n*(n-(c-b)-(d-a))
}

func CombinationsStr(s string) string {
	var n, a, b, c, d uint64
	fmt.Sscanf(s, "%d %d %d %d %d", &n, &a, &b, &c, &d)
	res := Combinations(n, a, b, c, d)
	return fmt.Sprint(res)
}

func main() {
	// fmt.Println(CombinationsStr("2 1 1 1 2")) // 2
	// fmt.Println(CombinationsStr("3 3 1 2 3")) // 6
	buf, err := ioutil.ReadAll(os.Stdin)
	if err != nil {
		panic(err)
	}
	res := CombinationsStr(string(buf))
	fmt.Println(res)
}

