func sol() int64 {
	n := getInt()
	a := getInt()
	b := getInt()
	c := getInt()
	d := getInt()

	e, f, g, h := a+b, b+d, d+c, c+a
	mx := max(max(e, f), max(g, h))
	mn := min(min(e, f), min(g, h))

	x := mx + 1 - mn
	if n-x < 0 {
		return 0
	}
	return int64(n-x+1) * int64(n)
}

