				if j > 0 {
					dp[i][j] = dp[i][j-1] + i + 1
				}
			} else {
				if j == 0 {
					dp[i][j] = dp[i-1][j+1]
				} else if j == v-1 {
					dp[i][j] = dp[i][j-1] + i + 1
				} else {
					dp[i][j] = min(dp[i-1][j+1], dp[i][j-1]+i+1)
				}
			}
		}
	}
	m := int(1e9)
	for i := 0; i < v; i++ {
		m = min(m, dp[n-1][i])
