func splitToDigits(n int) []int {
    var a []int = make([]int, 0)
    for n > 0 {
        a = append(a, n%10)
        n = n/10
    }
    return a
}

func main() {
    var n int
    fmt.Scanf("%v\n", &n)
    pos := 0
    for q := 1; q <= n; q++ {
        a := splitToDigits(q)
        pos += len(a)
        //fmt.Printf("%v %v\n", pos, a)
        if pos == n {
            fmt.Printf("%v", a[0])
            return
        } else if pos > n {
            for i := 0; i < len(a); i++ {
                pos -= 1
                if pos == n-1 {
                    fmt.Printf("%v", a[i])
                    return
                }
            }
        }
    }
}

