func solv(n int, a []int) int {
	dp := make([][]int, n+1)
	for i := 0; i <= n; i++ {
		dp[i] = make([]int, 4)
	}
	// j
	// 0 = rest
	// 1 = write
	// 2= gym

	// a[i]
	// 0 >> no gym && no write
	// 1 >> no gym &&    write
	// 2 >>    gym && no write
	// 3 >>    gym && 	 write
	for i := 1; i <= n; i++ {
		dp[i][0] = Mx(dp[i-1][0], dp[i-1][1], dp[i-1][2])

		if a[i-1] == 1 || a[i-1] == 3 {
			dp[i][1] = Mx(dp[i-1][2], dp[i-1][0]) + 1
		}
		if a[i-1] == 2 || a[i-1] == 3 {
			dp[i][2] = Mx(dp[i-1][0], dp[i-1][1]) + 1
		}
	}

	return n - Mx(dp[n][0], dp[n][1], dp[n][2])
}

