	visited[t][v] = true
	res := -1145141919
	res = IntMax(res, memo(t+1, v)+v)
	for i := 1; i <= D; i++ {
		res = IntMax(res, memo(t+1, v+i)+v+i)
		if v-i >= 0 {
			res = IntMax(res, memo(t+1, v-i)+v-i)
		}
	}
	dp[t][v] = res
	return res
}

