type graph struct {
	size   int
	edges  [][]bool
	degree []int
	color  []int
}

func (g *graph) add(from, to int) {
	g.edges[from][to] = true
	g.degree[from]++
}

func (g *graph) addBoth(from, to int) {
	g.add(from, to)
	if from != to {
		g.add(to, from)
	}
}

func (g *graph) _isBipartite(v int) bool {
	for w, e := range g.edges[v] {
		if e || w == v {
			continue
		}
		if g.color[w] == g.color[v] {
			return false
		}
		if g.color[w] == 0 {
			g.color[w] = 3 - g.color[v]
			if !g._isBipartite(w) {
				return false
			}
		}
	}
	return true
}

func (g *graph) isBipartite() bool {
	checked := false
	cnt := 0
	for i, deg := range g.degree {
		deg = g.size - 1 - deg
		if deg > 0 {
			if checked {
				if g.color[i] == 0 {
					return false
				}
				continue
			}
			g.color[i] = 1
			if !g._isBipartite(i) {
				return false
			}
			for w := range g.edges[i] {
				if g.color[w] == 2 {
					cnt++
				}
			}
			checked = true
		}
	}
	if cnt > 0 {
		for v, c := range g.color {
			if c == 1 {
				cntW := 0
				for w, e := range g.edges[v] {
					if e || w == v {
						continue
					}
					if g.color[w] == 2 {
						cntW++
					}
				}
				if cntW != cnt {
					return false
				}
			}
		}
	}
	return true
}

