func Sol623A(reader io.Reader, writer io.Writer) {
	in := bufio.NewReader(reader)
	out := bufio.NewWriter(writer)
	defer out.Flush()

	var n, m int
	Fscan(in, &n, &m)
	g := &graph{
		size:   n,
		edges:  make([][]bool, n),
		degree: make([]int, n),
		color:  make([]int, n),
	}
	for i := range g.edges {
		g.edges[i] = make([]bool, n)
	}
	for ; m > 0; m-- {
		var v, w int
		Fscan(in, &v, &w)
		g.addBoth(v-1, w-1)
	}

	// 若反图为空或二分图，则存在
	if !g.isBipartite() {
		Fprint(out, "No")
		return
	}

	Fprintln(out, "Yes")
	for _, c := range g.color {
