const MOD = int64(1e9) + 7

func solve(n int64) int64 {
	var ans int64 = 1
	for i := int64(1); i <= n; i++ {
		ans *= i
		ans %= MOD
	}

	var tmp int64 = 1
	for i := int64(1); i <= n-1; i++ {
		tmp <<= 1
		tmp %= MOD
	}

	ans -= tmp
	for ans < 0 {
		ans += MOD
	}
	return ans
}

