func gcd(a, b int64) int64 {
	switch {
	case a == 0 && b > 0:
		return b
	case a > 0 && b == 0:
		return a
	case a == b:
		return a
	case a == 1 && b > 0:
		return 1
	case a > 0 && b == 1:
		return 1
	case a%2 == 0 && b%2 == 0:
		return 2 * gcd(a/2, b/2)
	case a%2 == 0 && b%2 == 1:
		return gcd(a/2, b)
	case a%2 == 1 && b%2 == 0:
		return gcd(a, b/2)
	case b > a:
		return gcd((b-a)/2, a)
	case b < a:
		return gcd((a-b)/2, b)
	default:
		panic("not reachable")
	}
}

