	defer writer.Flush()

	var n, l, r, x int64
	scanf("%d%d%d%d\n", &n, &l, &r, &x)
	arr := make([]int64, n)

	for i:=int64(0);i<n;i++ {
		var temp int64
		scanf("%d", &temp)
		arr[i] = temp
	}

	ans := int64(0)
	for i:=int64(0);i<(int64(1) << n);i++ {
