			if i & (int64(1) << j) != 0 {
				if min > arr[j] {
					min = arr[j]
				}
				if max < arr[j] {
					max = arr[j]
				}
				sum += arr[j]
			}
		}

		if sum >= l && sum <= r && (max-min) >= x {
			ans++
		}
	}

	printf("%d\n", ans)

