/* solution */

type nodeType struct {
	next [2]*nodeType
	// count of digits need to be removed
	// ...from the end of binary value (count of divisions by 2)
	// ...to make an added value equal to the current
	cuts [20]int
	cnt  int
}

func solve() {

	n, k := readInt(), readInt()
	root := &nodeType{}

	for i := 0; i < n; i++ {

		v := readInt()

		digits := make([]int, 0)
		for v > 0 {
			// reversed binary representation of the value
			digits = append(digits, v%2)
			v = v / 2
		}

		addToTree(root, digits, len(digits))

	}

	printInt(search(root, k))

}

func search(node *nodeType, k int) int {

	if node == nil || node.cnt < k {
		return 1000000000 // INF
	}

	s0 := 0
	rem := k - node.cuts[0] // how many equal values do we need more
	for i := 1; rem > 0 && i < 20; i++ {
		if rem > node.cuts[i] {
			s0 += node.cuts[i] * i
			rem -= node.cuts[i]
		} else {
			s0 += rem * i
			rem = 0
		}
	}

	s1, s2 := search(node.next[0], k), search(node.next[1], k)

	return min(s0, min(s1, s2))

}

func addToTree(node *nodeType, digits []int, idx int) {

	node.cnt++
	node.cuts[idx]++

	idx--
	if idx < 0 {
		return
	}

	next := node.next[digits[idx]]
	if next == nil {
		node.next[digits[idx]] = &nodeType{}
		next = node.next[digits[idx]]
	}

	addToTree(next, digits, idx)

}

func min(a, b int) int {
	if a < b {
		return a
	}
	return b
}

