func pointCount(i int64) int64 {
	var sum int64
	for j:=int64(2); j*j*j < i + 1; j++ {
		sum += i / (j*j*j)
	}
	return sum
}


func solve(m int64) int64 {
	var lo, hi, mid int64
    lo = int64(0)
	hi = int64(5000000000000000)
	for lo + 1 < hi {
		mid = (lo + hi) / 2
		if pointCount(mid) < m {
			lo = mid
		} else {
			hi = mid
		}
	}
	if pointCount(hi) == m {
		return hi
	} else {
		return -1
	}
}


