func getI64() int64 {
  scanner.Scan()
  x, _ := strconv.ParseInt(scanner.Text(), 10, 64)
  return x
}

func getCount(x int64) int64 {
  count := int64(0)
  limit := int64(math.Floor(math.Pow(float64(x), 0.34)))
  for k := int64(2); k <= limit; k++ {
    count += x / (k * k * k)
  }
  return count
}

func main() {
  scanner = bufio.NewScanner(os.Stdin)
  scanner.Split(bufio.ScanWords)
  writer = bufio.NewWriter(os.Stdout)
  defer writer.Flush()

  m := getI64()
  low, high := int64(1), int64(8000000000000000)
  for low < high {
    x := (low + high) / 2
    y := getCount(x)
    if y > m {
      high = x - 1
    } else if y < m {
      low = x + 1
    } else {
      high = x
    }
  }
  x := low
  y := getCount(x)
  if y != m {
    x = -1
  }
  writer.WriteString(fmt.Sprintf("%d\n", x))
}

