type byteSet map[byte]bool

func main() {
	var n int
	var s string
	fmt.Scan(&n)
	fmt.Scan(&s)

	sets := make([]byteSet, 0)
	curSet := byteSet{}

	for i := 0; i < n; i++ {
		if s[i] >= 'a' && s[i] <= 'z' {
			curSet[s[i]] = true
			if i != n-1 {
				continue
			}
		}
		sets = append(sets, curSet)
		curSet = byteSet{}
	}

	maxSet := byteSet{}

	for _, set := range sets {
		if len(set) > len(maxSet) {
			maxSet = set
		}
	}

	fmt.Printf("%d\n", len(maxSet))
}

