  x, _ := strconv.ParseFloat(scanner.Text(), 64)
  return x
}
func getS() string {
  scanner.Scan()
  return scanner.Text()
}

func getNext(x int64) int64 {
  //fmt.Fprintf(os.Stderr, "in: %d\n", x)
  digits := []int64{}
  for x != 0 {
    digits = append(digits, x%10)
    x /= 10
  }
  carry := int64(0)
  resetIndex := -1
  for i, digit := range digits {
    if carry == 1 {
      digit++
      carry = 0
    }
    if digit <= 4 {
      if digit < 4 {
        resetIndex = i-1
      }
      digits[i] = 4
    } else if digit <= 7 {
      if digit < 7 {
        resetIndex = i-1
      }
      digits[i] = 7
    } else {
      digits[i] = 4
      resetIndex = i
      carry = 1
    }
  }
  if carry == 1 {
    digits = append(digits, 4)
  }
  for i := 0; i <= resetIndex; i++ {
    digits[i] = 4
  }
  base := int64(1)
  for _, digit := range digits {
    x += base*digit
    base *= 10
  }
  //fmt.Fprintf(os.Stderr, " -> %d\n", x)
  return x
}

