  scanner.Split(bufio.ScanWords)
  writer := bufio.NewWriter(os.Stdout)
  defer writer.Flush()

  n := getI64()
  d2 := n*n

  if n == 0 {
    writer.WriteString("1\n")
    return
  }

  result := 0
  if n > 0 {
    result += 4
  }
  if n > 1 {
    x := int64(float64(n)/math.Sqrt(2))
    if (x+1)*(x+1) + x*x > d2 {
      result += 4
    }
  }

  x, y := n, int64(0)
  for true {
    y++
    for x*x + y*y > d2 {
      x--
    }
    if x <= y {
      break
    }
    result += 8
  }

  writer.WriteString(fmt.Sprintf("%d\n", result))
}

