var notes = []string{ "C", "C#", "D", "D#", "E", "F", "F#", "G", "G#",
                      "A", "B", "H" }

func position(a string) int {
  for i := 0; i < 12; i++ {
    if notes[i] == a {
      return i
    }
  }
  return -1
}

func distance(a, b string) int {
  i, j := position(a), position(b)
  if i <= j {
    return j-i
  } else {
    return 12+j-i
  }
  return -1
}

func kind(a, b, c string) string {
  x, y := distance(a, b), distance(b, c)
  if x == 4 && y == 3 {
    return "major"
  } else if x == 3 && y == 4 {
    return "minor"
  }
  return "strange"
}

func main() {
  scanner = bufio.NewScanner(os.Stdin)
  scanner.Split(bufio.ScanWords)
  writer := bufio.NewWriter(os.Stdout)
  defer writer.Flush()

  x, y, z := getS(), getS(), getS()
  permutations := [][]string{
      []string{ x, y, z },
      []string{ x, z, y },
      []string{ y, x, z },
      []string{ y, z, x },
      []string{ z, x, y },
      []string{ z, y, x },
    }
  for _, p := range permutations {
    s := kind(p[0], p[1], p[2])
    if s != "strange" {
      writer.WriteString(fmt.Sprintf("%s\n", s))
      return
    }
  }
  writer.WriteString("strange\n")
}

