func ceilDiv(i, div int64) int64 {
    if div == 0 {
        return 0 // should not happen
    }
    if i % div == 0 {
        return i / div
    }
    return (i / div) + 1
}

func max(i, j int64) int64 {
    if i > j {
        return i
    }
    return j
}

func main() {
    defer writer.Flush()
    var n, m int64
    scanf("%d\n", &n)
    scanf("%d\n", &m)
    total := m
    maxSoFar := int64(0)
    for i := int64(0); i < n; i++ {
        var i int64
        scanf("%d\n", &i)
        total += i
        maxSoFar = max(maxSoFar, i)
    }
    minK := max(ceilDiv(total, n), maxSoFar)
    maxK := maxSoFar + m
    printf("%d %d", minK, maxK)
}

