func intPow(x int64, y int64) (res int64) {
	res = 1
	for i := int64(0); i < y; i++ {
		res *= x
	}
	return
}

func main() {
	var n, x, y, numx, numy, t int64
	fmt.Scan(&n, &x)
	numx = 0
	for i := int64(1); i <= n; i++ {
		fmt.Scan(&t)
		numx += t * intPow(x, (n-i))
	}
	fmt.Scan(&n, &y)
	numy = 0
	for i := int64(1); i <= n; i++ {
		fmt.Scan(&t)
		numy += t * intPow(y, (n-i))
	}

	if numx == numy {
		fmt.Println("=")
	} else if numx < numy {
		fmt.Println("<")
	} else {
		fmt.Println(">")
	}
}

