import (
	"fmt"
	"bufio"
	"strconv"
	"os"
)

var in = bufio.NewScanner(os.Stdin)
var out = bufio.NewWriter(os.Stdout)
var MOD int64


func pow(x, p int64) int64 {
	var ret int64 = 1
	for p > 0 {
		if p % 2 == 1 {
			ret = ret * x % MOD
		}
		x = x * x % MOD
		p >>= 1
	}
	return ret
}

func powM(a [][]int64, p int64) [][]int64 {
	ret := make([][]int64, 2)
	for i := 0; i < 2; i++ {
		ret[i] = make([]int64, 2)
		ret[i][i] = 1
	}
	for p > 0 {
		if p % 2 == 1 {
			ret = mult(ret, a)
		}
		a = mult(a, a)
		p >>= 1
	}
	return ret
}

func mult(a, b [][]int64) [][]int64 {
	c := make([][]int64, 2)
	for i := 0; i < 2; i++ {
		c[i] = make([]int64, 2)
	}
	for i := 0; i < 2; i++ {
		for j := 0; j < 2; j++ {
			for k := 0; k < 2; k++ {
				c[i][j] += a[i][k] * b[k][j] % MOD
			}
		}
	}
	return c
}

func main() {

	defer out.Flush()
	in.Split(bufio.ScanWords)

	var n, k int64 = NextInt64(), NextInt64()
	var l int = NextInt()
	MOD = NextInt64()

	if l < 63 && 1 << uint(l) <= k {
		fmt.Fprintln(out, 0)
		return
	}

	if l == 0 {
		if k == 0 {
			fmt.Fprintln(out, 1 % MOD)
		}else {
			fmt.Fprintln(out, 0)
		}
		return
	}

	a := make([][]int64, 2)
	for i := 0; i < 2; i++ {
		a[i] = make([]int64, 2)
	}
	a[0][1], a[1][0], a[1][1] = 1, 1, 1
	a = powM(a, n - 2)
	var dp int64 = (2 * a[0][1] + 3 * a[1][1]) % MOD
	var two int64 = pow(int64(2), n)
	var ret int64 = 1
	for i := 0; i < l; i++ {
		if ((k >> uint(i)) & 1) == 0 {
			ret = ret * dp % MOD
		}else {
			ret = ret * (two - dp + MOD) % MOD
		}
	}

	fmt.Fprintln(out, ret)
}

func Next() string{
	if !in.Scan() {
		panic("Scan error")
	}
	return in.Text()
}

func NextInt64() int64 {
	ret, _ := strconv.ParseInt(Next(), 10, 64)
	return ret
}

func NextInt() int{
	ret, _ := strconv.Atoi(Next())
	return ret
}

