)

const (
	EPS = 1e-8
)

var (
	reader = bufio.NewReader(os.Stdin)
)

type Light struct {
	p complex128
	a float64
}

type Line struct {
	p1, p2 complex128
}

func CrossProduct(a complex128, b complex128) float64 {
	return real(a)*imag(b) - real(b)*imag(a)
}

func Roatate(x complex128, a float64) complex128 {
	r, t := cmplx.Polar(x)
	return cmplx.Rect(r, t+a)
}

func Intersact(a Line, b Line) (intersaction complex128, isIntersact bool) {
	s1 := CrossProduct(a.p2-a.p1, b.p1-a.p1)
	s2 := CrossProduct(a.p2-a.p1, b.p2-a.p1)
	if math.Abs(s2-s1) >= EPS {
		isIntersact = true
		intersaction = complex(real(b.p1)*s2-real(b.p2)*s1, imag(b.p1)*s2-imag(b.p2)*s1) / complex(s2-s1, 0.0)
	}
	return
}

func foo(l float64, lit Light, r float64) float64 {
	v1 := complex(l-real(lit.p), 0-imag(lit.p))
	v2 := Roatate(v1, lit.a)
	if imag(v2) > -EPS {
		return r
	}

	p1 := complex(0.0, 0.0)
	p2 := complex(100.0, 0.0)
	inter, _ := Intersact(Line{lit.p, lit.p + v2}, Line{p1, p2})
	return real(inter)
}

func main() {
	var (
		n    int
		l, r float64
		lits []Light
	)

	fmt.Fscan(reader, &n, &l, &r)
	for i := 0; i < n; i++ {
		var x, y, a float64
		fmt.Fscan(reader, &x, &y, &a)
		lits = append(lits, Light{complex(x, y), a * math.Pi / 180.0})
	}

	f := make([]float64, 1<<uint(n))
	for i := range f {
		f[i] = l
	}
	for i := 0; i < (1 << uint(n)); i++ {
		for j := 0; j < n; j++ {
			if k := i | 1<<uint(j); i != k {
				cur := foo(f[i], lits[j], r)
				if cur > f[k] {
					f[k] = cur
				}
			}
		}
	}
	fmt.Print(math.Min(f[(1<<uint(n))-1]-l, r-l))
}

