type Num []int

func (self Num) Len() int           { return len(self) }
func (self Num) Less(i, j int) bool { return self[i] < self[j] }
func (self Num) Swap(i, j int)      { self[i], self[j] = self[j], self[i] }

func main() {
    scanner.Split(bufio.ScanWords)

    var dp [1 << 18][100]int64
    var num []int = make([]int, 0)

    n, m := scanner.NextInt64(), int(scanner.NextInt64())
    for n > 0 {
        num = append(num, int(n%10))
        n /= 10
    }
    sort.Sort(Num(num))
    dp[0][0] = 1
    for mask := 0; mask < (1 << uint(len(num))); mask++ {
        for k := 0; k < m; k++ {
            if dp[mask][k] > 0 {
                pre := -1
                for i := 0; i < len(num); i++ {
                    if mask&(1<<uint(i)) > 0 || num[i] == pre || (mask == 0 && num[i] == 0) {
                        continue
                    }
                    dp[mask|(1<<uint(i))][(k*10+num[i])%m] += dp[mask][k]
                    pre = num[i]
                }
            }
        }
    }
    fmt.Println(dp[(1<<uint(len(num)))-1][0])
}

