	b := readInt()
	movesNum := readInt()

	dp := make([][]int, 2)
	for i := 0; i < len(dp); i++ {
		dp[i] = make([]int, n + 1)
	}

	for i := 1; i <= n; i++ {
		dp[0][i] = 1 + dp[0][i - 1] 
		if dp[0][i] >= MOD {
			dp[0][i] -= MOD
		}
	}

	for move := 0; move < movesNum; move++ {
		for x := 1; x <= n; x++ {
			length := absInt(x - b)
			dp[(move & 1) ^ 1][x] = dp[(move & 1) ^ 1][x - 1]
			if length > 1 {
				left := maxInt(x - (length - 1), 1)
				right := minInt(x + (length - 1), n)
				add := dp[(move & 1)][right] - dp[(move & 1)][left - 1]
				if add < 0 {
					add += MOD
				}
				sub := dp[(move & 1)][x] - dp[(move & 1)][x - 1]
				if sub < 0 {
					sub += MOD
				}
				diff := add - sub
				if diff < 0 {
					diff += MOD
				}
				dp[(move & 1) ^ 1][x] += diff 
				if dp[(move & 1) ^ 1][x] >= MOD {
					dp[(move & 1) ^ 1][x] -= MOD 
				}
			}
		}
	}
//	logln(dp)
	ans := dp[((movesNum - 1) & 1) ^ 1][a] - dp[((movesNum - 1) & 1) ^ 1][a - 1]
	if ans < 0 {
		ans += MOD
	}
