				filled = false
			}
		}
	}
	for i := 0; i < 8; i++ {
		if victory[i]&x == victory[i] {
			xWinChess = xWinChess & victory[i]
		}
		if victory[i]&o == victory[i] {
			oWinChess = oWinChess & victory[i]
		}
	}

	// two non-intersect line
	if xWinChess == 0 || oWinChess == 0 {
		fmt.Printf("illegal")
		return
	}

	// x o both win
	if xWinChess != 0x777 && oWinChess != 0x777 {
		fmt.Printf("illegal")
		return
	}

	if xCount-oCount != 0 && xCount-oCount != 1 {
		fmt.Printf("illegal")
		return
	}

	if xCount-oCount == 1 && oWinChess != 0x777 {
		fmt.Printf("illegal")
		return
	}

	if xCount-oCount == 0 && xWinChess != 0x777 {
		fmt.Printf("illegal")
		return
	}

	if xWinChess == 0x777 && oWinChess != 0x777 {
		fmt.Printf("the second player won")
		return
	}

	if xWinChess != 0x777 && oWinChess == 0x777 {
		fmt.Printf("the first player won")
		return
	}

	if filled == false && xWinChess == 0x777 && oWinChess == 0x777 {
		if xCount-oCount == 1 {
			fmt.Printf("second")
			return
		}
		if xCount == oCount {
			fmt.Printf("first")
			return
		}
	}

	if filled == true && xWinChess == 0x777 && oWinChess == 0x777 {
		fmt.Printf("draw")
		return
	}
}

