  scanner.Split(bufio.ScanWords)
  writer := bufio.NewWriter(os.Stdout)
  defer writer.Flush()

  xCount, oCount := 0, 0
  for i := range grid {
    grid[i] = []byte(getS())
    for j, ch := range grid[i] {
      if ch == 'X' {
        xCount++
        grid[i][j] = 'x'
      } else if ch == '0' {
        oCount++
        grid[i][j] = 'o'
      }
    }
  }
  diff := xCount - oCount
  if diff < 0 || diff > 1 {
    writer.WriteString("illegal\n")
