		}

		safe_ind := 0
		lower_bound := -1
		upper_bound := N
		if len(safe) > 0 {
			upper_bound = safe[safe_ind]
		}
		res := "Yes"
		for true {			

			retval := is_path_safe(lower_bound, upper_bound, K, L, A)
			//fmt.Println("is_path_safe() beg: ", lower_bound, "end: ", upper_bound, "retval: ", retval)
			if !retval {
				res = "No"
				break
			} else {
				if safe_ind > len(safe) -1 {
					break 
				}

				lower_bound = safe[safe_ind]
				safe_ind++
				if safe_ind > len(safe) -1 {
					upper_bound = N
				} else {
					upper_bound = safe[safe_ind]
				}
			}
		}

		fmt.Println(res)
	}
}

func is_path_safe(beg, end, K, L int, A []int) bool {	
	abeg := beg + 1
	aend := end - 1
	if abeg >= aend {
		return true
	}

	t := 0
	for i:=abeg; i<=aend; i++ {
		t = get_time_to_enter(K, L, t, A[i])
		//fmt.Println("t: ", t)
		if t < 0 {
			return false
		}		
	}

	// last step 
	t++

	//fmt.Println("t: ", t)
	if t > 2*K {
		return false
	}

	return true
}

/*
The precise time pos, where we can enter that position
*/
func get_time_to_enter(K, L, t, d int) int {

	t++
	x := d + K - L
	if t >= x && t <= 2 * K - x {
		return t
	} else if t < x {
		return x
	} else {
		return -1
	}
}

