type tide struct {
	d int64 // delta
	i bool  // increasing - false by default
}

// Next adjusts the tide level to the next most optimal value
// Returns false if unable to do so
func (t *tide) Next(currDepth int64, k, l int64) bool {
	// rest spot -> reset params
	if currDepth + k <= l {
		t.d = k
		t.i = false
		return true
	}

	// tide decreasing -> check min
	if !t.i {
		t.d--
		if currDepth + t.d > l {
			t.d = l - currDepth
		}
		if t.d < 0 {
			return false
		}
		if t.d == 0 {
			t.i = true
		}
		return true
	}

	// tide increasing
	t.d++
	if currDepth + t.d > l {
		return false
	}
	if t.d == k {
		t.i = false
	}
	return true
}

