	defer writer.Flush()
	t := sint64()
	for ; t > 0; t-- {
		n := sint64()
		k := sint64()
		l := sint64()
		d := make([]int64, n)
		for i := range d {
			d[i] = sint64()
		}
		printf("%s\n", sol(d, n, k, l))
	}
}

func sol(d []int64, n, k, l int64) string {
	t := &tide{
		d: k,
		i: false,
	}
	for _, di := range d {
		if !t.Next(di, k, l) {
			return "No"
		}
	}
	return "Yes"
}

