const MaxBurgers = int64(1e13)

func max(x, y int64) int64 {
	if x >= y {
		return x
	}
	return y
}

func p(burgers, cb, cs, cc, nb, ns, nc, pb, ps, pc int64) int64 {
	return max(0, cb*burgers-nb)*pb + max(0, cs*burgers-ns)*ps + max(0, cc*burgers-nc)*pc
}

func _Solve(left, right, cb, cs, cc, nb, ns, nc, pb, ps, pc, rubles int64) int64 {
	if !(left < right) {
		return left
	}
	m := (left + right + 1) / 2
	cost := p(m, cb, cs, cc, nb, ns, nc, pb, ps, pc)
	if cost <= rubles {
		return _Solve(m, right, cb, cs, cc, nb, ns, nc, pb, ps, pc, rubles)
	}
	return _Solve(left, m-1, cb, cs, cc, nb, ns, nc, pb, ps, pc, rubles)
}

func Solve(s string, nb, ns, nc, pb, ps, pc, r int64) int64 {
	cb := int64(strings.Count(s, "B"))
	cs := int64(strings.Count(s, "S"))
	cc := int64(strings.Count(s, "C"))
	return _Solve(0, MaxBurgers, cb, cs, cc, nb, ns, nc, pb, ps, pc, r)
}

func main() {
	reader := bufio.NewReader(os.Stdin)
	writer := bufio.NewWriter(os.Stdout)
	defer writer.Flush()

	var s string
	fmt.Fscanf(reader, "%s\n", &s)
	var nb, ns, nc int64
	fmt.Fscanf(reader, "%d %d %d\n", &nb, &ns, &nc)
	var pb, ps, pc int64
	fmt.Fscanf(reader, "%d %d %d\n", &pb, &ps, &pc)
	var r int64
	fmt.Fscanf(reader, "%d\n", &r)

	fmt.Fprintf(writer, "%d\n", Solve(s, nb, ns, nc, pb, ps, pc, r))
}

