		if j, ok := mm[a[l[i]]]; ok && j != l[i] {
			fmt.Println(-1)
			return
		}
		mm[a[l[i]]] = l[i]
	}

	// fill in zeroes
	for i := 0; i < n; i++ {
		if a[i] != 0 {
			continue
		}
		for j := 1; j <= n; j++ {
