	if d <= k {
		// only car without repair
		res = min(res, a*d)
	} else {
		// only car with repair (x*k >= d)
		x = (d + k - 1) / k
		res = min(res, a*d+(x-1)*t)

		// car with repair and then walk
		alpha = k*a - k*b + t
		beta = b*d - t

		if alpha >= 0 {
			res = min(res, alpha+beta)
		} else {
			x = d / k
			res = min(res, x*alpha+beta)
		}
	}

	fmt.Fprintln(bufout, res)
}

