func mabs(x int) int {
	if x < 0 {
		return -x
	}
	return x
}

func main() {
	var s, x1, x2, t1, t2, p, d int
	in := bufio.NewReader(os.Stdin)
	fmt.Fscan(in, &s, &x1, &x2, &t1, &t2, &p, &d)
	best := mabs(x1-x2) * t2
	traintime := 0
	if d == 1 {
		if p <= x1 {
			traintime = (x1 - p) * t1
		} else {
			traintime = (s-p)*t1 + (s-x1)*t1
			d = -1
		}
	} else {
		if p >= x1 {
			traintime = (p - x1) * t1
		} else {
			traintime = (p * t1) + (x1 * t1)
			d = 1
		}
	}
	if d == 1 {
		if x1 < x2 {
			traintime += (x2 - x1) * t1
		} else {
			traintime += (s-x1)*t1 + (s-x2)*t1
		}
	} else {
		if x2 < x1 {
			traintime += (x1 - x2) * t1
		} else {
			traintime += x1*t1 + x2*t1
		}
	}
	if traintime < best {
		best = traintime
	}
	fmt.Println(best)
}

