	fmt.Scan(&n, &x, &y, &c)
	r,l,m:=n*2+1,-1,0
	for r-l>1{
		m = int((int64(r)+int64(l))/2)
		tiles:=count(n,x,y,m)
		if (tiles<c) {
			l=m
		} else {
			r=m
		}
	}
	fmt.Print(r)
}

func count(N,X,Y,T int) int64 {
	n,x,y,t:=int64(N),int64(X),int64(Y),int64(T)
	out := 2*t*t + 2*t + 1
	out -= sq(t-dist(x,y,x,1))
	out -= sq(t-dist(x,y,x,n))
	out -= sq(t-dist(x,y,n,y))
	out -= sq(t-dist(x,y,1,y))
	h:=t-dist(x,y,1,0)
	if (h>0) {out+=(sq(h)+h)/2}
	h=t-dist(x,y,n,0)
	if (h>0) {out+=(sq(h)+h)/2}
	h=t-dist(x,y,1,n+1)
	if (h>0) {out+=(sq(h)+h)/2}
	h=t-dist(x,y,n,n+1)
	if (h>0) {out+=(sq(h)+h)/2}
	return out
}

func sq(n int64) int64 {if (n<0) {return 0}else{return n*n}}
func dist(x1,y1,x2,y2 int64) int64 {return abs(x1-x2)+abs(y1-y2)}
func abs(n int64) int64 {if (n<0) {return -n}else{return n}}

