type key struct {
	lastIdx    int
	nDifferent int
}

var (
	n, m, k int
	cache   = make(map[key]int64)
)

// colorings will calculate how many different colorings are at a[0]..a[lastIdx], so that nDifferent for 0..lastIdx holds.
func colorings(lastIdx int, nDifferent int) (ret int64) {
	k := key{lastIdx, nDifferent}
	if r, ok := cache[k]; ok {
		return r
	}
	defer func() {
		cache[k] = ret
	}()

	// We have spent all our different brick possibilities.
	if nDifferent < 0 {
		return 0
	}

	if lastIdx == 0 {
		if nDifferent == 0 {
			// If there is only one brick remaining, it can have m different colors.
			return int64(m)
		}
		// But only, if there is exactly zero bricks different on its left.
		return 0
	}

	// There are p combinations for 0..lastIdx-1. For each combination:
	//   - there is (m-1) combinations with nDifferent that is the same
	//   - one combination with nDifferent less.
	lastIdxDifferent := colorings(lastIdx-1, nDifferent-1) * int64(m-1)
	lastIdxSame := colorings(lastIdx-1, nDifferent)
	// dprintf("lastIdx=%d, nDifferent=%d, noDiff=%d, diff=%d", lastIdx, nDifferent, noDiffChange, diffChange)

	return (lastIdxDifferent + lastIdxSame) % 998244353

	// m combinations where [lastIdx-1, lastIdx are the same]
	// m**2 - m combinations where [lastIdx-1 and lastIdx are different]
}

