func main() {
	in := bufio.NewReader(os.Stdin)
	out := bufio.NewWriter(os.Stdout)
	defer out.Flush()
	n, m, k := 0, 0, 0
	fmt.Fscanf(in, "%d %d %d\n", &n, &m, &k)
	f := make([][]int64, n+1)
	for i := 0; i < n+1; i++ {
		f[i] = make([]int64, k+1)
	}
	f[1][0] = int64(m)
	for i := 2; i < n+1; i++ {
		for j := 0; j < k+1; j++ {
			if j == 0 {
				f[i][j] = f[i-1][j]
			} else {
				f[i][j] = f[i-1][j] + f[i-1][j-1]*int64(m-1)
				f[i][j] %= mod
			}
		}
	}
	fmt.Fprintf(out, "%d\n", f[n][k])
	return
}

