import "fmt"

func process(row, col, step int64) (resultRow, resultCol int64) {
	if step == 0 {
		return 1, 1
	}

	if step <= row-1 {
		return step + 1, 1
	}

	step = step - (row - 1)

	var rowCount = step / (col - 1) // количество полностью пройденный строк змейкой
	var offset = step % (col - 1)
	var direction = rowCount % 2

	// direction 1 - left
	// direction 0 - right

	if offset == 0 {
		resultRow = row - rowCount + 1
		if direction == 1 {
			resultCol = col
		} else {
			resultCol = 2
		}
	} else {
		if direction == 1 {
			resultRow = row - rowCount
			resultCol = col - offset + 1
		} else {
			resultRow = row - rowCount
			resultCol = offset + 1
		}
	}

	return resultRow, resultCol
}

func main() {
	var (
		row  int64
		col  int64
		step int64
	)

	fmt.Scanln(&row, &col, &step)

	fmt.Println(process(row, col, step))
}

