func findGolden(cut int, rem []string) bool {
	total := 0
	for i := 0; i < len(rem); i++ {
		a, _ := strconv.Atoi(rem[i])

		total += a
		if total > cut {
			return false
		}
		if total == cut {
			return i+1 == len(rem) || findGolden(cut, rem[i+1:]) || findGolden(0, rem[i+1:])

		}
	}
	return false
}

