type Cube struct {
	elements [24]int
}

type Turn struct {
	square [4]int
	wall   [8]int
}

func NewTurn(cube [4]int, wall [8]int) Turn {
	for index := 0; index < 4; index++ {
		cube[index]--
	}

	for index := 0; index < 8; index++ {
		wall[index]--
	}

	return Turn{cube, wall}
}

func (cube *Cube) RotateLeft(turn Turn) {
	square := turn.square
	wall := turn.wall

	first := cube.elements[square[0]]
	for index := 0; index < 3; index++ {
		cube.elements[square[index]] = cube.elements[square[index+1]]
	}
	cube.elements[square[3]] = first

	for iteration := 0; iteration < 2; iteration++ {
		first := cube.elements[wall[0]]
		for index := 0; index < 7; index++ {
			cube.elements[wall[index]] = cube.elements[wall[index+1]]
		}
		cube.elements[wall[7]] = first
	}
}

func (cube *Cube) RotateRight(turn Turn) {
	square := turn.square
	wall := turn.wall

	last := cube.elements[square[3]]
	for index := 3; index > 0; index-- {
		cube.elements[square[index]] = cube.elements[square[index-1]]
	}
	cube.elements[square[0]] = last

	for iteration := 0; iteration < 2; iteration++ {
		last := cube.elements[wall[7]]
		for index := 7; index > 0; index-- {
			cube.elements[wall[index]] = cube.elements[wall[index-1]]
		}
		cube.elements[wall[0]] = last
	}
}

func (cube *Cube) IsPerfect() bool {
	perfect := true

	for side := 0; side < 6 && perfect; side++ {
		for index := 0; index < 4 && perfect; index++ {
			if cube.elements[4*side+index] != cube.elements[4*side] {
				perfect = false
			}
		}
	}

	return perfect
}

func main() {
	var cube Cube
	for index := 0; index < 24; index++ {
		fmt.Scanf("%d", &cube.elements[index])
	}

	turns := []Turn{
		NewTurn([4]int{1, 2, 4, 3}, [8]int{22, 21, 18, 17, 6, 5, 14, 13}),
		NewTurn([4]int{5, 6, 8, 7}, [8]int{3, 4, 17, 19, 10, 9, 16, 14}),
		NewTurn([4]int{9, 10, 12, 11}, [8]int{7, 8, 19, 20, 23, 24, 15, 16}),
		NewTurn([4]int{13, 14, 16, 15}, [8]int{1, 3, 5, 7, 9, 11, 24, 23}),
		NewTurn([4]int{17, 18, 20, 19}, [8]int{4, 2, 21, 23, 12, 10, 8, 6}),
		NewTurn([4]int{21, 22, 24, 23}, [8]int{2, 1, 13, 15, 11, 12, 20, 18}),
	}

	can := false

	for _, turn := range turns {
		cube.RotateLeft(turn)

		if cube.IsPerfect() {
			can = true
		}

		cube.RotateRight(turn)
		cube.RotateRight(turn)

		if cube.IsPerfect() {
			can = true
		}

		cube.RotateLeft(turn)
	}

	if can {
		fmt.Println("YES")
	} else {
		fmt.Println("NO")
	}
}

