func check(data [24]int, row0, row1 []int, dir int) bool {
	for i := 0; i < len(row0); i++ {
		if data[row0[i]] != data[row1[(i+dir+len(row1))%len(row1)]] {
			return false
		}
	}
	return true
}

func isFullSide(data [24]int, side int) bool {
	color := data[side*4]
	for i := 0; i < 4; i++ {
		if data[side*4+i] != color {
			return false
		}
	}
	return true
}

