var MD int64 = 1000000007
var f map[int]int

func deg(d int) int64 {
	if d == 0 {
		return 1
	}
	t := deg(d / 2)
	t *= t
	t %= MD
	if d % 2 == 1 {
		t = t * 2 % MD
	}
	return t
}

func calc(x int) int {
	if val, exists := f[x]; exists {
		return val
	}
	res := int(deg(x - 1))
	for i:= 2;i * i <= x; i++ {
		if x % i == 0 {
			first := i
			second := x / i
			res = res - calc(x / first)
			if res < 0 {
				res += 1000000007
			}
			if second != first {
				res = res - calc(x / second)
				if res < 0 {
					res += 1000000007
				}
			}
		}
	}
	res = res - 1
	if res < 0 {
		res += 1000000007
	}
	f[x] = res
	return res
}

