var n, m, k int64

func solve(n int64) {
	I(&m, " ")
	I(&k, "\n")
	if n == m {
		O(1, "\n")
		return
	}
	if n == 1 {
		O(m, "\n")
		return
	}
	ans := int64(2)
	m -= n + 1
	h := int64(1)
	l := k - 1
	r := n - k
	for m > 0 {
		if l > 0 {
			h++
			l--
		}
		if r > 0 {
			h++
			r--
		}
		if r <= 0 && l <= 0 {
			ans += m / h
			m = 0
		} else {
			m -= h
			if m >= 0 {
				ans++
			}
		}
	}
	O(ans, "\n")
}

