	k := readInt()
	if people == 1 {
		fmt.Println(pillow)
		return
	}
	pillow -= people
	left := int64(k - 1)
	right := int64(people - k)
	best := 0
	lo := 0
	hi := pillow
	for lo <= hi && pillow > 0 {
		mi := lo + (hi-lo)/2
		rest := int64(pillow - mi)
		step := int64(mi - 1)
		var sum1 int64
		var sum2 int64
		if left > 0 && step > 0 {
			t := left
			if step < t {
				t = step
			}
			sum1 = int64(step-t+1+step) * t / 2
		}
		if right > 0 && step > 0 {
			t := right
			if step < t {
				t = step
			}
			sum2 = int64(step-t+1+step) * t / 2
		}
		if sum1+sum2 <= rest {
			best = mi
			lo = mi + 1
		} else {
			hi = mi - 1
		}
	}
	fmt.Println(best + 1)
}

