func digit2pos(a int) (int, int) {
	if a == 0 {
		return 3, 1
	}
	a--
	return a / 3, a % 3
}

func legal(y, x int) bool {
	if y == 3 {
		return x == 1
	}
	return y >= 0 && y < 3 && x >= 0 && x < 3
}

// apply a→b like move to x
func move(x, a, b int) int {
	ay, ax := digit2pos(a)
	by, bx := digit2pos(b)

	py, px := digit2pos(x)

	py += by - ay
	px += bx - ax

	if !legal(py, px) {
		return -1
	}
	if py == 3 {
		return 0
	}
	return 1 + py*3 + px
}

