}

func _solve(s string, minLength int, maxLength int, queue []string, answers []string) string {
	elem := queue[0]
	if minLength <= len(elem) && len(elem) <= maxLength {
		elemInt, _ := strconv.Atoi(elem)
		sInt, _ := strconv.Atoi(s)
		if isSuperLuckyNumber(elem) && sInt <= elemInt {
			return elem
		}
	}
	if len(elem) <= maxLength {
		queue = append(queue, elem+"4")
		queue = append(queue, elem+"7")
		answers = append(answers, elem)
		return _solve(s, minLength, maxLength, queue[1:], answers)
	}
	return _solve(s, minLength, maxLength, queue[1:], answers)
}

