	if len(s)%2 == 0 {
		return len(s), len(s) + 2
	}
	return len(s) + 1, len(s) + 1
}

func solve(s string) string {
	minLength, maxLength := findMinAndMaxLength(s)
	return _solve(s, minLength, maxLength, []string{"4", "7"}, []string{})
}

