	}

	return string(bytes)
}

func readInts(r *bufio.Reader) []int {
	elems := strings.Fields(readLine(r))

	ret := make([]int, len(elems))
	for i, el := range elems {
		tmp, err := strconv.ParseInt(el, 10, 64)
		if err != nil {
			log.Fatalf("Failed to parse number %v", el)
		}
		ret[i] = int(tmp)
	}

	return ret
}

func min(a, b int64) int64 {
	if a > b {
		return b
	}
	return a
}

func combination(a, b int64) int64 {
	b = min(b, a-b)
	nom, denom := int64(1), int64(1)
	for b > 0 {
		nom *= a
		denom *= b
		a -= 1
		b -= 1
	}

	return nom / denom
}

func pow(a, b int64) int64 {
	ret := int64(1)
	for b > 0 {
		ret *= a
		b -= 1
	}

	return ret
}

