func solve(n, x uint64) uint64 {
	if x > n {
		return 0
	}

	res := uint64(1)
	if x % 2 == 0 {
		res += solve(n, x + 1)
	}

	xlen := uint(bits.Len64(x))
	nlen := uint(bits.Len64(n))

	nx := x << (nlen - xlen)

	if nlen > xlen {
		res += (uint64(1) << (nlen - xlen)) - 2
	}

	if nx <= n && nlen > xlen {
		if n >> (nlen - xlen) == x {
			res += n - nx + 1
		} else {
			res += uint64(1) << (nlen - xlen)
		}
	}

	return res
}

func solveStupid(n, x uint64) uint64 {
	if x > n {
		return 0
	}

	res := uint64(1)
	if x % 2 == 0 {
		res += solveStupid(n, x + 1)
	}
	res += solveStupid(n, x * 2)

	return res
}

