import "fmt"
const MAX int64 = 1e7
const MOD int64 = 1e9+7
var isgood [MAX]bool
func Max(a, b int64) int64 {
	if (a < b) {
		return b
	}
	return a
}
func Init(a, b, n int64) {
	var k int64
	for k = 0; k < MAX; k++ { isgood[k] = true }
	for k = 1; k <= Max(a,b) * n; k++ {
		p := k
		for p > 0 {
			if p % 10 != a && p % 10 != b {
				isgood[k] = false
				break
			}
			p /= 10
		}
	}
}

func EE(a, b int64) int64 {
	var (
		r=a%b
		x0 int64=1
		y0 int64=0
		x1 int64=0
		y1 int64=1
		mod=b
	)
	for r > 0 {
		f:=a/b
		tx:=x0-f*x1
		ty:=y0-f*y1
		x0=x1
		y0=y1
		x1=tx
		y1=ty
		a=b
		b=r
		r=a%b
	}
	return (x1%mod+mod)%mod
}

func main() {
	var a,b,n int64
	fmt.Scanf("%d%d%d",&a,&b,&n)
	Init(a,b,n)
	var (
		choose int64=1
		x int64=0
		y int64
	)
	cnt := make(map[int64]int64)
	for x <= n {
		y=n-x
		s:=a*x+b*y
		if isgood[s] { cnt[s]=(cnt[s]+choose)%MOD }
		choose=((choose*(n-x))%MOD)*EE(x+1,MOD)%MOD
		x++
	}
	var ans int64 = 0
	for k,v := range cnt {
		if isgood[k] { ans = (ans + v) % MOD }
	}
	fmt.Println(ans)
}

