import "fmt"

func gcd(a int, b int, x *int, y *int) int {
    if a == 0 {
        *x, *y = 0, 1
        return b
    }
    var xx, yy int
    g := gcd(b%a, a, &xx, &yy)
    *x = yy - (b/a)*xx
    *y = xx
    return g
}

func normal(n int, mod *int) int {
    n %= (*mod)
    if n < 0 {
        n += (*mod)
    }
    return n
}

func inv(a int, mod *int) int {
    var x, y int
    gcd(a, *mod, &x, &y)
    return normal(x, mod)
}

func addmod(a, b int, mod *int) int { 
    if a + b >= (*mod) {
        return a + b - (*mod)
    } else {
        return a + b
    }
}

func submod(a, b int, mod *int) int { 
    if a - b < 0 {
        return a - b + (*mod)
    } else {
        return a - b
    }
}

func mulmod(a, b int, mod *int) int { 
    return int((int64(a)*int64(b))%int64(*mod))
}

func divmod(a, b int, mod *int) int { 
    return mulmod(a, inv(b, mod), mod)
}

func binpowmod(a, b int, mod *int) int {
    ans := 1
    for b > 0 {
        if b%2 == 1 {
            ans = mulmod(ans, a, mod)
        }
        a = mulmod(a, a, mod)
        b = b/2
    }
    return ans
}

func calc(y []int, x int, mod *int) int {
    ans := 0
    k := 1
    for j := 1; j < len(y); j++ {
        k = mulmod(k, normal(x - j, mod), mod)
        k = divmod(k, normal(0 - j, mod), mod)
    }
    for i := 0; i < len(y); i++ {
        ans = addmod(ans, mulmod(y[i], k, mod), mod)
        if (i + 1) >= len(y) {
            break
        }
        k = mulmod(k, divmod(normal(x - i, mod), normal(x - (i + 1), mod), mod), mod)
        k = mulmod(k, divmod(normal(i - (len(y) - 1), mod), normal(i + 1, mod), mod), mod)
    }
    return ans
}

func main() {
    var n, k int
    var mod int = 1000000007
    var y []int = make([]int, 0)
    s := 0
    y = append(y, s)
    fmt.Scanf("%d %d", &n, &k)
    for i := 0; i < k + 1; i++ {
        s = addmod(s, binpowmod(i + 1, k, &mod), &mod) //k-th powwer of (i+1)
        y = append(y, s)
    }
    if n < len(y) {
        fmt.Printf("%d", y[n])
    } else {
        p := calc(y, n, &mod)
        fmt.Printf("%d", p)
    }
}

