import "fmt"

func nextPermutation(a []int) bool {
    i := len(a)-1
    for (i > 0) && (a[i] <= a[i-1]) { i-- }
    if (i == 0) { return false }
    j := len(a)-1
    for a[j] <= a[i-1] { j-- }
    a[j], a[i-1] = a[i-1], a[j]
    j = len(a)-1
    for i < j {
        a[i], a[j] = a[j], a[i]
        i++; j--
    }
    return true
}

