        for i := 0; i < 4; i++ {
            for j := 0; (i+j) < 4; j += 2 {
                cnt += g[a[i+j]][a[i+j+1]]+g[a[i+j+1]][a[i+j]]
            }
        }
        if max < cnt { max = cnt }
