func verifyReallyBig(num int64, minDiff int64) (isReallyBig bool) {
	sum := int64(0)
	for n := num; n > 0; n /= 10 {
		sum += n % 10
	}
	diff := num - sum
	if diff >= minDiff {
		isReallyBig = true
	} else {
		isReallyBig = false
	}
	return
}

func searchMin(n int64, s int64) (min int64) {
	var left, right int64
	var isReallyBig bool
	lastMin := n + 1
	for left, right = 1, n/10 + 1; right > left; {
		min = (left + (right - left) / 2) * 10
		isReallyBig = verifyReallyBig(min, s)
		if isReallyBig {
			right = min / 10
			lastMin = min
		} else {
			left = min / 10 + 1
		}
	}
	return lastMin
}

func Solve(input io.Reader) (result string) {
	var n, s int64
	fmt.Fscan(input, &n, &s)
	return fmt.Sprintln(n - searchMin(n, s) + 1)
}

func main() {
	fmt.Print(Solve(os.Stdin))
}

