type Position struct {
	X int
	Y int
}

type Node struct {
	Position Position
	Time     int
}

func getNeighbors(p Position) []Position {
	var validNeighbors []Position
	for i := -1; i <= 1; i++ {
		for j := -1; j <= 1; j++ {
			x := p.X + i
			y := p.Y + j
			if 0 <= x && x < 8 && 0 <= y && y < 8 {
				validNeighbors = append(validNeighbors, Position{X: x, Y: y})
			}
		}
	}
	return validNeighbors
}

func hasStatue(board [8]string, p Position, time int) bool {
	if 0 <= p.X-time && p.X-time < 8 {
		if string(board[p.X-time][p.Y]) == "S" {
			return true
		}
	}
	if 0 <= p.X-time-1 && p.X-time-1 < 8 {
		if string(board[p.X-time-1][p.Y]) == "S" {
			return true
		}
	}
	return false
}

func Solve(board [8]string) string {
	stack := []Node{{Position: Position{X: 7, Y: 0}, Time: 0}}
	for {
		currentNode := stack[len(stack)-1]
		stack = stack[:len(stack)-1]
		if currentNode.Time == 8 || currentNode.Position.X == 0 {
			return "WIN"
		}
		for _, neighbor := range getNeighbors(currentNode.Position) {
			if !hasStatue(board, neighbor, currentNode.Time) {
				stack = append(stack, Node{Position: neighbor, Time: currentNode.Time + 1})
			}
		}
		if len(stack) == 0 {
			break
		}
	}
	return "LOSE"
}

func main() {
	reader := bufio.NewReader(os.Stdin)
	writer := bufio.NewWriter(os.Stdout)
	defer writer.Flush()

	var board [8]string
	for i := 0; i < 8; i++ {
		fmt.Fscanf(reader, "%s\n", &board[i])
	}
	fmt.Fprintf(writer, "%s\n", Solve(board))
}

