func solve() {
    n := readInt()
    init := [2]int{}
    a, c := make([][2]int, n), make([]int, n)
    for i := 0; i < n; i++ {
        ch := readString()
        if ch == "B" {
            c[i] = 1
        }
        for j := range a[i] {
            v := readInt()
            if v > n {
                init[j] += v-n
                v = n
            }
            a[i][j] = v
        }
    }

    const inf = 100000000
    const mx = 1<<16
    const sz = 16*16+1
    mem := [mx][2][sz]int{}
    was := [mx]bool{}
    for i := range mem {
        for col := range mem[i] {
            diff := min(max(init[1-col]-init[col], 0), sz-1)
            for j := range mem[i][col] {
                val := inf
                if i == 0 && diff == j {
                    val = 0
                }
                mem[i][col][j] = val
            }
        }
    }

    ans := inf
    d := [mx][2]int{}
    q := make([]int, 1, 1<<16)
    q[0] = 0
    un := uint(n)
    was[0] = true
    for curI := 0; curI < len(q); curI++ {
        cur := q[curI]
        curD := d[cur]
        //fmt.Println("BFS", cur, curD)
        for col, u := range mem[cur] {
            for cnt, val := range u {
                if cur == (1<<un)-1 {
                    ans = min(ans, val)
                }

                if val >= inf {
                    continue
                }

                r, b := 0, 0
                if col == 0 {
                    r = cnt
                } else {
                    b = cnt
                }

                for bit := uint(0); bit < un; bit++ {
                    mask := 1 << bit
                    if cur & mask == 0 {
                        next := cur | mask
                        priceR, priceB := max(a[bit][0]-curD[0], 0), max(a[bit][1]-curD[1], 0)
                        //fmt.Println(" Price", priceR, priceB, val)
                        steps := max(priceR-r, priceB-b)
                        nextR, nextB := r+steps-priceR, b+steps-priceB
                        nextCol, nextVal := 0, min(nextR+nextB, sz-1)
                        if nextB > 0 {
                            nextCol = 1
                        }
                        mem[next][nextCol][nextVal] = min(mem[next][nextCol][nextVal], val+steps+1)

                        if !was[next] {
                            was[next] = true

                            nextD := curD
                            nextD[c[bit]]++
                            d[next] = nextD

                            q = append(q, next)
                        }
                    }
                }
            }
        }
    }

    ans += max(init[0], init[1])
    fmt.Println(ans)
}



