func add(a, b int) int {
	return (a + b) % MOD
}

func mul(a, b int) int {
	return int(int64(a) * int64(b) % MOD)
}

var dp [MAXK][LCM16]int
var pown [MAXK + 1]int

func main() {
	defer flush()

	var n, a0, k, ai int
	var genX, genY, genMod int64
	scan(&n, &a0, &genX, &genY, &k, &genMod)

	pown[0] = 1
	for i := 1; i <= MAXK; i++ {
		pown[i] = mul(pown[i-1], n)
	}

	ans := 0
	ai = a0
	for i := 0; i < n; i++ {
		dp[0][ai%LCM16]++
		ans = add(ans, mul(ai-ai%LCM16, mul(k, pown[k-1])))
		ai = int((int64(ai)*genX + genY) % genMod)
	}

	for i := 0; i+1 < k; i++ {
		for j := 0; j < LCM16; j++ {
			dp[i+1][j-j%(i+1)] = add(dp[i+1][j-j%(i+1)], dp[i][j])
			dp[i+1][j] = add(dp[i+1][j], mul(dp[i][j], n-1))
		}
	}

	for j := 1; j <= k; j++ {
		for i := 0; i < LCM16; i++ {
			ans = add(
				ans,
				mul(mul(dp[j-1][i], i), pown[k-j]),
			)
		}
	}

