var mem [1e6 + 1]*big.Int

func exp(k int) *big.Int {
	if mem[k] != nil {
		return mem[k]
	}
	t := exp(k / 2)
	mem[k] = new(big.Int).Mul(t, t)
	if k&1 != 0 {
		mem[k].Mul(mem[k], mem[1])
	}
	return mem[k]
}

func main() {
	var k, b, n, t int64
	fmt.Scan(&k, &b, &n, &t)
	if k == 1 {
		ans := (b*n + b - t) / b
		if ans < 0 {
			ans = 0
		}
		fmt.Println(ans)
		return
	}
	mem[0] = big.NewInt(1)
	mem[1] = big.NewInt(k)
	mul := big.NewInt(k - 1 + b)
	target := big.NewInt(t*(k-1) + b)
	for i := 0; ; i++ {
		if target.Cmp(new(big.Int).Mul(exp(i), mul)) < 0 {
