import "fmt"

func main() {
	var numCases int
	fmt.Scanf("%d\n", &numCases)

	answers := make([]int, numCases)

	for i := 0; i < numCases; i++ {
		var n, k, d int
		fmt.Scanf("%d %d %d\n", &n, &k, &d)

		_ = k // unused

		schedule := make([]int, n)
		for j := 0; j < n; j++ {
			if j == n-1 {
				fmt.Scanf("%d\n", &schedule[j])
			} else {
				fmt.Scanf("%d", &schedule[j])
			}
		}

		answers[i] = solveCase(schedule, d)
	}

	for _, a := range answers {
		fmt.Println(a)
	}
}

// solveCase solves single task case for:
// * schedule -- index - day, value - show id
// * days -- target number of days for subscription
func solveCase(schedule []int, days int) (numShows int) {
	shows := make(map[int]int)

	for i := 0; i < days; i++ {
		shows[schedule[i]]++
	}

	numShows = len(shows)

	for i := days; i < len(schedule); i++ {
		cnt := shows[schedule[i-days]]
		if cnt == 1 {
			delete(shows, schedule[i-days])
		} else {
			shows[schedule[i-days]]--
		}

		shows[schedule[i]]++

		if len(shows) < numShows {
			numShows = len(shows)
		}
	}

	return numShows
}

